(window.GIM_TS=window.GIM_TS||{})["Gittin.1"]={"from":24,"a":[["\u0003בההיא\u0004 \u0005[באותה]\u0006 \u0003הנאה\u0004 שיש ללווה \u0003דקא משתניא ליה\u0004 \u0005[שמשתנה לו]\u0006 עתה חובו \u0003בין מלוה ישנה למלוה חדשה,\u0004 כי עכשיו החוב אינו עוד למלווה הראשון אלא לאדם אחר, ונוח לו שיש לו עכשיו נושה חדש שיכול לבקש ממנו ארכה עד שיצטרך לשלם לו את חובו — מכוח הנאה זו \u0003גמר ומשעביד נפשיה\u0004 \u0005[גומר\u0006 בדעתו \u0005ומשעבד\u0006 את \u0005עצמו]\u0006 עכשיו למלווה החדש.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003הונא מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמיה לרב אשי: אלא מעתה,\u0004 לפי דבריך, \u0003כגון הני דבי בר\u0004 \u0005[אלה\u0006 האנשים \u0005של בית בן]\u0006 \u0003אלישיב דכפתי ושקלי לאלתר\u0004 \u0005[ש\u0006הם \u0005כופתים\u0006 באזיקים \u0005ולוקחים\u0006 את ממונם \u0005מיד]\u0006 כאשר מגיע זמן פרעון של הלוואה שנתנו, והם בוודאי לא יתנו ללווה ארכה יתירה על זמן ההלוואה הראשונה ואין הוא משעבד עצמו להם, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003לא קנו\u0004 בדרך קנין זו של מעמד שלושתם? שהרי לגבי הלווה אין הבדל בין מילוה הישנה לבין המילוה החדשה.","\u0003וכי תימא הכי נמי\u0004 \u0005[ואם תאמר\u0006 ש\u0005כך\u0006 הוא \u0005גם כן],\u0006 ודין זה אמנם אינו שייך בהם, \u0003אם כן נתת דבריך לשיעורין,\u0004 שחלות קנין \"מעמד שלושתם\" אינה מוחלטת אלא תלויה כל פעם במידה שנוח לו ללווה להעביר את השיעבוד מאיש אחד לחבירו,","\u0003אלא\u0004 יש לחזור מן ההסברים הקודמים, ולנקוט כפי ש\u0003אמר מר זוטרא: הני תלת מילי\u0004 \u0005[שלושה דברים אלה]\u0006 \u0003שוינהו רבנן כהלכתא\u0004 \u0005[עשו אותם חכמים כהלכה]\u0006 \u0003בלא טעמא\u0004 \u0005[טעם],\u0006 כלומר, קבעו הלכה שאין עניינה ברור לנו: \u0003חדא\u0004 \u0005[האחד]\u0006 — \u0003הא\u0004 \u0005[זו]\u0006 של מעמד שלושתם, \u0003ואידך\u0004 \u0005[והאחר],\u0006 זו ש\u0003אמר רב יהודה אמר שמואל: הכותב כל נכסיו לאשתו\u0004 במתנה — \u0003לא עשאה אלא אפיטרופיא\u0004 (אפוטרופסית), כלומר, ממונה על הנכסים, אבל לא נתן לה אותם במתנה. \u0003ואידך\u0004 \u0005[והאחר],\u0006 זו ש\u0003אמר רב חנניא: המשיא אשה לבנו גדול\u0004 ועושה את משתה החתונה \u0003בבית\u0004 — \u0003קנאו\u0004 הבן לאותו בית.","ובענין זה של מעמד שלושתם מסופר: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב לרב אחא ברדלא: קבא דמוריקא אית לי גבך\u0004 \u0005[קב של כרכום יש לי אצלך]\u0006 שאתה חייב לי, \u0003יהביה\u0004 \u0005[תן אותו]\u0006 \u0003לפלוני\u0004 זה, שיקנהו בקנין מעמד שלושתם. והוסיף רב: \u0003באפיה קאמינא\u0004 \u0005[בפניו אני אומר]\u0006 \u0003לך\u0004 ש\u0003לא הדרנא\u0004 \u0005[אחזור]\u0006 \u0003בי\u0004 מקנין זה.","ושואלים: \u0003מכלל\u0004 הדברים אתה למד \u0003דאי בעי הדר ביה, מצי הדר ביה\u0004 \u0005[שאם היה רוצה לחזור בו, היה יכול לחזור בו]\u0006 ונמצא שאין מעמד שלושתם קונה קנין גמור? ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 בפניו אני אומר לך דבר זה, שכן \u0003דברים הללו\u0004 הנעשים במעמד שלושתם \u0003לא ניתנו לחזרה,\u0004 שיש בכך נתינה שאין הנותן יכול לחזור בו ממנה.","ושואלים: לשם מה הובאו דברי רב אלה? \u0003הא\u0004 \u0005[הרי]\u0006 כבר \u0003אמר רב\u0004 הלכה זו \u0003חדא זימנא\u0004 \u0005[פעם אחת],\u0006 ש\u0003אמר רב הונא אמר רב: \"מנה לי בידך, תנהו לו לפלוני\", במעמד שלשתן\u0004 — \u0003קנה!\u0004","ודוחים: \u0003אי\u0004 \u0005[אם]\u0006 קנין מעמד שלושתם היה נלמד רק \u0003מההיא\u0004 \u0005[מאותה\u0006 הלכה\u0005]\u0006 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שיש צורך במעמד שלושתם אמורים דווקא ב\u0003מתנה מרובה,\u0004 שרק בה צריך לעשות דווקא כך, \u0003אבל מתנה מועטת לא ליבעי\u0004 \u0005[יצטרך]\u0006 לעשות אותה \u0003בפניו\u0004 של המקבל, אלא יכול המקנה לתת הוראה בלבד, ובכך ייקנה הדבר לאותו פלוני, שאין מסתבר שיחזור בו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין הדבר כן, ושרק מעמד שלושתם מחיל קנין גמור.","מסופר: \u0003הנהו גינאי דעביד חושבנא בהדי הדדי\u0004 \u0005[אותם גננים שעשו חשבון זה עם זה],\u0006 \u0003פש חמש איסתרי זוזי גבי חד מנייהו\u0004 \u0005[נשארו חמישה איסרים אצל אחד מהם]\u0006 יותר מן המגיע לו, ונמצא חייב סכום זה לאחרים, \u0003אמרי ליה\u0004 \u0005[אמרו לו]\u0006 האחרים: \u0003\"יהבינהו ניהליה למרי ארעא\"\u0004 \u0005[תן אותם,\u0006 את המעות, \u0005לבעל הקרקע],\u0006 ואמרו זאת \u0003באפי מרי ארעא\u0004 \u0005[בפני בעל הקרקע],\u0006 \u0003וקנה מיניה\u0004 \u0005[וקנו ממנו],\u0006 כלומר, עשו קנין לגבי זה.","\u0003לסוף אזל עבד חושבנא בין דיליה לנפשיה\u0004 \u0005[הלך ועשה\u0006 אותו אדם \u0005חשבון בינו לבין עצמו],\u0006 והתברר לו ש\u0003לא פש גביה\u0004 \u0005[נשאר אצלו]\u0006 \u0003ולא מידי\u0004 \u0005[דבר],\u0006 שבאמת לא היה עודף כזה בידיו. \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב נחמן\u0004 לשאול מה לעשות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003מאי איעביד\u0004 \u0005[מה אעשה]\u0006 \u0003לך? חדא\u0004 \u0005[אחת],\u0006 ש\u0003אמר רב הונא אמר רב,\u0004 שמעמד שלושתם קונה קנין מיידי וכבר קנה בעל הקרקע את המעות. \u0003ועוד, הא קנו מינך\u0004 \u0005[הרי עשו קנין איתך].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אטו האי מי קאמר \"לא יהבינא\"\u0004 \u0005[האם\u0006 אדם \u0005זה אומר \"איני נותן\"],\u0006 שאינו רוצה לתת מה שהתחייב? הלא \u0003\"דליכא גבאי\" קאמר\u0004 \u0005[\"שאין אצלי\"\u0006 הוא \u0005אומר],\u0006 שהרי אמרו לו חביריו לתת חמישה איסרים שנשארו בידו, והוא טוען שכלל לא נשאר בידו סכום כזה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אם כן, קנין בטעות הוא\u0004 זה, \u0003וכל קנין בטעות חוזר.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה הבאה, מי שאמר לשלוחו: \u0003\"הולך מנה לפלוני שאני חייב לו\", אמר רב: חייב\u0004 המשלח \u0003באחריותו,\u0004 ואם יאבד המנה לשליח צריך המשלח לתת מנה אחר לאיש שהוא חייב לו. \u0003ו\u0004אולם \u0003אם\u0004 \u0003בא\u0004 (מבקש) המשלח \u0003לחזור\u0004 בו מנתינה זו לאחר שנתן לשליחו — \u0003אינו חוזר. ושמואל אמר: מתוך שחייב\u0004 המשלח \u0003באחריותו,\u0004 הרי המנה נחשב עדיין ברשותו, ומשום כך \u0003אם בא לחזור\u0004 — \u0003חוזר.\u0004","ושואלים: \u0003לימא בהא קמיפלגי\u0004 \u0005[\u0006האם \u0005לומר\u0006 ש\u0005ב\u0006דבר \u0005זה\u0006 הם \u0005חלוקים],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 רב, \u0005סבור]:\u0006 \u0003\"הולך\" כ\u0004אילו אמר לו \u0003\"זכי\" דמי\u0004 \u0005[\"זכה\" נחשב],\u0006 וזכה השליח מיד בקבלתו עבור המקבל, ולכן אין המשלח יכול לחזור בו. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 שמואל, \u0005סבור]:\u0006 \u0003\"הולך\" לאו כ\"זכי\" דמי\u0004 \u0005[לא כמו \"זכה\"\u0006 הוא \u0005נחשב]\u0006 ומשום שעדיין לא זכה המקבל בדבר, יכול המשלח לחזור בו?","ודוחים: \u0003לא,\u0004 אפשר לומר \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 \u0003\"הולך\" כ\"זכי\" דמי\u0004 \u0005[כמו \"זכה\"\u0006 הוא \u0005נחשב],\u0006 \u0003והכא\u0004 \u0005[ו\u0006אולם \u0005כאן]\u0006 במקרה זה שהאחריות חלה עדיין על המשלח \u0003בהא קמיפלגי\u0004 \u0005[ב\u0006דבר \u0005זה\u0006 הם \u0005חלוקים],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 רב, \u0005סבור]:\u0006 \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]:\u0006 \u0003מיגו\u0004 \u0005[מתוך]\u0006 שחייב המשלח באחריותו — יכול גם לחזור בו. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 שמואל, \u0005סבור]:\u0006 \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003מיגו\u0004 \u0005[מתוך].\u0006 שבמקום שאנו מחייבים את המשלח באחריות (כגון בהלוואה) נמצא שאין אנו סבורים שהשליח זכה עבור המקבל זכייה גמורה, וכיון שלא יצא הדבר מרשות המשלח — יכול המשלח אף לחזור בו.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב:\u0004 מי שאמר לחבירו \u0003\"הולך מנה לפלוני שאני חייב לו\",\u0004 או שאמר \u0003\"תן מנה לפלוני שאני חייב לו\",\u0004 או \u0003\"הולך מנה לפלוני פקדון שיש לו בידי\",\u0004 או \u0003\"תן מנה לפלוני פקדון שיש לו בידי\"\u0004 — \u0003חייב באחריותו, ואם בא לחזור\u0004 — \u0003אינו חוזר.\u0004","ושואלים לגבי אותה ברייתא: במקרה שבו השליח קיבל להביא \u0003פקדון\u0004 לבעליו, \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 המשלח, שומר הפקדון, לשליח: \u0003אין רצונו\u0004 של בעל הפקדון \u0003שיהא פקדונו ביד אחר!\u0004 וכיון שנעשה דבר שאינו לזכות בעל הפקדון — אין כאן זכייה, וממילא יכול המשלח לחזור בו. \u0003אמר ר' זירא:\u0004 כאן מדובר \u0003כשהוחזק\u0004 המשלח, שומר הפקדון \u0003כפרן,\u0004 אדם שאינו נאמן. ומשום כך בוודאי מרוצה בעל הפקדון שהפקדון יוצא מידו לידי אדם אחר.","מסופר: \u0003רב ששת הוה ליה אשרתא דסרבלי\u0004 \u0005[היה לו אשראי של מעילים]\u0006 \u0003ב\u0004עיר \u0003מחוזא,\u0004 שהיה לו הסכם קבוע שהוא נותן להם מעילים לסחור בהם בעיר מחוזא, והם משלמים עבורם אחר כך מעות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003לרב יוסף בר חמא: בהדי דאתית, אייתינהו ניהלי\u0004 \u0005[כאשר אתה בא\u0006 לכאן ממחוזא עירך, \u0005הבא אותם לי].\u0006 \u0003אזל, יהבינהו ליה\u0004 \u0005[הלך,\u0006 ו\u0005נתנום לו].\u0006 \u0003אמרי ליה\u0004 \u0005[אמרו לו]\u0006 הנותנים: \u0003ניקני מינך\u0004 \u0005[נעשה איתך קנין]\u0006 על זה שקיבלת, שאם יקרה דבר תהיה אחראי עליהם. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006","\u0003לסוף אישתמיט להו\u0004 \u0005[השתמט מהם]\u0006 ולא עשה את הקנין. \u0003כי אתא לגביה\u0004 \u0005[כאשר בא אליו],\u0006 לרב ששת וסיפר לו על כך, \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ששת: \u0003שפיר עבדת\u0004 \u0005[יפה,\u0006 נכון \u0005עשית]\u0006 ש\u0003לא שוית נפשך\u0004 \u0005[עשית\u0006 את \u0005עצמך]\u0006 על ידי קנין שכזה \u0003\"עבד לוה לאיש מלוה\"\u0004 (משלי כב, ז), שכן לולא כן היית מחייב את עצמך לחינם כאילו לווית מהם. \u0003לישנא אחרינא\u0004 \u0005[\u0006ב\u0005לשון אחרת]\u0006 אומרים שכך אמר לו רב ששת: \u0003שפיר עבדת\u0004 \u0005[יפה עשית],\u0006 \u0003\"עבד לוה לאיש מלוה\",\u0004 ואנשי מחוזא שלוו ממני צריכים להיות אחראים לכך שיגיעו הדברים לידי.","עוד מסופר: \u0003ר' אחי בר' יאשיה הוה ליה איספקא דכספא\u0004 \u0005[היה לו כלי כסף]\u0006 \u0003ב\u0004עיר \u0003נהרדעא,\u0004"],["\u0003אמר\u0004 ר' אחי \u0003להו\u0004 \u0005[להם]\u0006 \u0003לר' דוסתאי בר ר' ינאי ולר' יוסי בר כיפר: בהדי דאתיתו אתיוה ניהלי\u0004 \u0005[כאשר אתם באים\u0006 משם \u0005הביאו אותו,\u0006 את הכלי, \u0005אלי].\u0006 \u0003אזול\u0004 \u0005[הלכו\u0006 לנהרדעא\u0005],\u0006 \u0003יהביה ניהליה\u0004 \u0005[נתנוהו\u0006 המחזיקים בכלי \u0005להם].\u0006 לאחר שנתנו להם את הכלי \u0003אמרי להו\u0004 \u0005[אמרו להם]\u0006 המחזיקים בכלי: \u0003נקני מינייכו\u0004 \u0005[נעשה קנין איתכם]\u0006 לגבי אחריותכם על הכלי עד שיגיע לידי ר' אחא. \u0003אמרי להו\u0004 \u0005[אמרו להם]\u0006 השליחים: \u0003לא,\u0004 אין אנו רוצים, שהרי כאמור, בדבר כזה האחריות על המשלח. \u0003אמרי להו\u0004 \u0005[אמרו להם]:\u0006 אם כן, \u0003אהדריה ניהלן\u0004 \u0005[החזירו אותו,\u0006 את הכלי, \u0005לנו]\u0006 שאין אנו רוצים לתת אותו באופן זה שתהיה האחריות עלינו.","\u0003ר' דוסתאי בר' ינאי אמר להו\u0004 \u0005[להם]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 שהוא מוכן להחזיר, \u0003ר' יוסי בר כיפר אמר להו\u0004 \u0005[להם]:\u0006 \u0003לא,\u0004 שהרי כאמור, אין הנותן יכול לחזור בו לאחר שנתנו לשליח. \u0003הוו קא מצערו ליה\u0004 \u0005[היו מצערים,\u0006 מענים, \u0005אותו]\u0006 את ר' יוסי בר כיפר, שיסכים להחזיר את הכלי, \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוסי בר כיפר לר' דוסתאי: \u0003חזי מר היכי קא עביד\u0004 \u0005[ראה אדוני איך\u0006 הוא \u0005עושה\u0006 לי\u0005]!\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003טב רמו ליה\u0004 \u0005[טוב\u0006 אתם עושים, \u0005הכו אותו].\u0006","\u0003כי אתו לגביה\u0004 \u0005[כאשר באו\u0006 שני השליחים הללו \u0005אליו,\u0006 אל ר' אחי\u0005],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוסי בר כיפר: \u0003חזי מר\u0004 \u0005[ראה אדוני],\u0006 \u0003לא מיסתייה\u0004 \u0005[די לו]\u0006 ש\u0003לא סייען\u0004 \u0005[סייע לי]\u0006 ר' דוסתאי, \u0003אלא\u0004 עוד \u0003אמר להו נמי\u0004 \u0005[להם גם כן]\u0006 \u0003\"טב רמו ליה\"\u0004 \u0005[טוב הכו אותו]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אחי לר' דוסתאי: \u0003אמאי תיעבד הכי\u0004 \u0005[מדוע עשית כך]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אותן בני אדם\u0004 שהחזיקו בכלי \u0003הן אמה, וכובען אמה, ומדברין מחצייהן, ושמותיהן מבוהלין\u0004 (מוזרים): \u0003ארדא וארטא ופילי בריש,\u0004 אם \u0003אומרין להם \"כפותו\"\u0004 — \u0003כופתין\u0004 את האדם, \u0003אומרין\u0004 להם \u0003\"הרוגו\"\u0004 — \u0003הורגין,\u0004 ומה היה קורה \u0003אילו הרגו את דוסתאי,\u0004 כלומר, אותי, \u0003מי נתן\u0004 (ייתן) \u0003לינאי אבא בר\u0004 \u0005[בן]\u0006 \u0003כמותי!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אחי: רצונך לומר ש\u0003בני אדם הללו קרובים למלכות הן? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הן\u0004\u0005.\u0006 שאל אותו: \u0003יש להן סוסים ופרדים שרצים אחריהן?\u0004 כלומר, משרתים וכוח לעשות את הדברים הללו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הן. אמר ליה\u0004 \u0005[לו]\u0006 ר' אחי: \u0003אי הכי, שפיר עבדת\u0004 \u0005[אם כך, יפה עשית],\u0006 שהיה זה אונס גמור.","לאחר שנידונה אמירת \"הולך\" האם היא כ\"זכה\" לענין מילוה ופקדון, דנים בה לענין מתנה. מי שאמר לשלוחו \u0003\"הולך מנה לפלוני\", והלך\u0004 השליח \u0003ובקשו\u0004 (חיפש את פלוני זה) \u0003ולא מצאו,\u0004 שכבר מת. \u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 במקרה שכזה \u0003יחזרו\u0004 המעות \u0003למשלח, ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 יינתנו המעות \u0003ליורשי מי שנשתלחו לו\u0004 (אליו).","ומציעים: \u0003לימא בהא קמיפלגי\u0004 \u0005[האם לומר\u0006 ש\u0005ב\u0006ענין \u0005זה\u0006 הם \u0005חלוקים],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה\u0006 שבברייתא השניה \u0005סבור]:\u0006 \u0003\"הולך\"\u0004 נחשב \u0003כ\"זכי\"\u0004 \u0005[כ\"זכה\"]\u0006 ולכן זכה השליח עבור מי שנשתלחו לו, וממילא כמותו ירשו בניו את זכותו זו, \u0003ומר סבר\u0004 \u0005[וחכם זה\u0006 שבברייתא הראשונה \u0005סבור]:\u0006 \u0003\"הולך\" לאו כ\"זכי\"\u0004 \u0005[אינו\u0006 נחשב \u0005כ\"זכה\"]\u0006 ולכן צריך להחזיר את המעות למשלח?","\u0003אמר ר' אבא בר ממל:\u0004 לא, \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003\"הולך\" לאו\u0004 \u0005[אינו\u0006 נחשב\u0005]\u0006 \u0003כ\"זכי\", ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה],\u0006 אין סתירה בין שתי הברייתות; \u0003הא\u0004 \u0005[זו]\u0006 הברייתא האומרת שיחזיר למשלח, עוסקת \u0003ב\u0004מקרה שהיה הנותן \u0003בריא\u0004 בשעה שציווה לתת את המנה, ומתנה כזו אינה נקנית למקבל מייד אלא כשזוכה בה, וכאן הרי מת. \u0003הא\u0004 \u0005[זו]\u0006 האומרת שייתן ליורשי מי שנשתלחו לו, עוסקת \u0003ב\u0004מקרה שהיה זה \u0003שכיב מרע\u0004 שציווה לתת, ובמתנת שכיב מרע מזכה מייד למקבל, ונמצא שזכה מיד במנה ומכוחו זכו יורשיו.","\u0003רב זביד אמר:\u0004 לדרך זו ש\"הולך\" אינו כ\"זכה\" יש לפרש עוד, כי \u0003הא והא\u0004 \u0005[זו וזו]\u0006 עוסקות \u0003ב\u0004מקרה שהיה הנותן \u0003שכיב מרע,\u0004 אלא \u0003הא\u0004 \u0005[זו]\u0006 האומרת: ליורשי מי שנשתלחו לו — במקרה \u0003דאיתיה\u0004 \u0005[שישנו]\u0006 \u0003למקבל בשעת מתן מעות,\u0004 שבשעה שנתן את הכסף לשליח היה המקבל עדיין חי, ולכן כשנתן לשליח מייד זכה המקבל בכסף, וזכו יורשיו מכוחו, \u0003הא\u0004 \u0005[זו]\u0006 האומרת: למשלח — במקרה \u0003דליתיה\u0004 \u0005[שלא היה]\u0006 כבר \u0003למקבל בשעת מתן מעות\u0004 לשליח, שנמצא שלא היה עבור מי לזכות.","ואילו \u0003רב פפא אמר,\u0004 אפשר לפרש באופן אחר את שתי הברייתות לדרך זו ש\"הולך\" אינו כ\"זכה\": \u0003הא והא\u0004 \u0005[זו וזו]\u0006 עוסקות \u0003בבריא\u0004 ששלח מתנה זו ומת, אלא \u0003הא\u0004 \u0005[זו]\u0006 האומרת שיחזיר למשלח, עוסקת במקרה \u0003דמית\u0004 \u0005[שמת]\u0006 ה\u0003מקבל בחיי\u0004 ה\u0003נותן,\u0004 ומשום שלא זכה בעצמו במעות, גם יורשיו אינם זכאים להם. \u0003הא\u0004 \u0005[זו]\u0006 האומרת שהמעות ינתנו ליורשי מי שנשתלחו אליו, עוסקת במקרה \u0003דמית\u0004 \u0005[שמת]\u0006 ה\u0003נותן בחיי\u0004 ה\u0003מקבל.\u0004 שכיון שמת, מצוה לקיים את דבריו, ומשום כך זכה המקבל במעות, ויורשיו אחריו.","ועוד מציעים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 שהשאלה האם \u0003\"הולך\" כ\"זכי\"\u0004 מחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003היא? דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מי שאמר לחבירו \u0003\"הולך מנה לפלוני\", והלך ובקשו ולא מצאו,\u0004 לפי שכבר מת — \u0003יחזרו\u0004 המעות \u0003למשלח. מת משלח\u0004 — \u0003ר' נתן ור' יעקב אמרו: יחזרו ליורשי משלח, ויש אומרים: ליורשי מי שנשתלחו לו.\u0004","\u0003ר' יהודה הנשיא אמר משום\u0004 (בשם) \u0003ר' יעקב שאמר משום\u0004 (בשם) \u0003ר' מאיר: מצוה לקיים דברי המת,\u0004 ולכן יש לתת אותם ליורשי המקבל. \u0003וחכמים אומרים:\u0004 מספק \u0003יחלוקו. וכאן\u0004 (בבבל) \u0003אמרו: כל מה שירצה שליח\u0004 — \u0003יעשה. אמר ר' שמעון הנשיא: על ידי\u0004 (אצלי) \u0003היה מעשה\u0004 כגון זה, ושאלתי כיצד לנהוג, \u0003ואמרו\u0004 לי חכמים: \u0003יחזרו ליורשי משלח.\u0004","ומעתה, \u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006ענין \u0005זה\u0006 הם \u0005חלוקים],\u0006 שה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]:\u0006 \u0003\"הולך\" לאו כ\"זכי\"\u0004 \u0005[אינו\u0006 נחשב \u0005כ\"זכה\"],\u0006 ולכן יחזור הכסף למשלח. \u0003ור' נתן ור' יעקב נמי\u0004 \u0005[גם כן]\u0006 סבורים: \u0003\"הולך\" לאו כ\"זכי\"\u0004 \u0005[אינו\u0006 נחשב \u0005כ\"זכה\"],\u0006 \u0003ו\u0004אולם מוסיפים עוד ש\u0003אף על גב דמית\u0004 \u0005[אף על פי שמת]\u0006 המשלח, \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]:\u0006 \u0003מצוה לקיים דברי המת,\u0004 ולכן יחזרו המעות ליורשיו. \u0003ו\u0004דעת \u0003יש אומרים\u0004 כי \u0003\"הולך\"\u0004 נחשב \u0003כ\"זכי\"\u0004 \u0005[כ\"זכה],\u0006 ולכן זכה המקבל מיד, ומכוחו זכו יורשיו.","\u0003ר' יהודה הנשיא אמר משום\u0004 (בשם) \u0003ר' יעקב שאמר משום\u0004 (בשם) \u0003ר' מאיר\u0004 סבור כי אמנם \u0003\"הולך\" לאו כ\"זכי\"\u0004 \u0005[לא\u0006 נחשב \u0005כ\"זכה\"],\u0006 \u0003מיהו היכא דמית\u0004 \u0005[אולם במקום שמת]\u0006 המשלח \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003מצוה לקיים דברי המת\u0004 ולכן יתנו את המנה למקבל או ליורשיו.","\u0003וחכמים אומרים: יחלוקו,\u0004 כי \u0003מספקא להו\u0004 \u0005[מסופק להם]\u0006 מה הדין בענין זה. \u0003ו\u0004דעת חכמים המכונים \u0003\"כאן אמרו\":\u0004 במקרה זה שיש ספק בדבר — \u0003שודא עדיף\u0004 \u0005[הכרעה עדיפה],\u0006 הם סבורים שבמקום לחלק את המעות בין שני הצדדים, מוטב לקבוע את הדבר הזה בהכרעה שרירותית כרצון השליח. \u0003ור' שמעון הנשיא\u0004 אין לו שיטה משלו, אלא \u0003מעשה אתא לאשמועינן\u0004 \u0005[בא להשמיע,\u0006 לספר \u0005לנו]\u0006 שכך נפסקה הלכה.","ודוחים: \u0003לא,\u0004 אפשר לומר כי \u0003ב\u0004מקרה שהיה הנותן \u0003בריא\u0004 בשעת השליחות \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 ש\"הולך\" אינו כ\"זכה\", \u0003והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים]\u0006 — \u0003בשכיב מרע\u0004 ששלח מנה זה, \u0003ובפלוגתא\u0004 \u0005[ובמחלוקת]\u0006 של \u0003ר' אלעזר ורבנן קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005].\u0006","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה]: \u0003המחלק נכסיו על פיו,\u0004 שמצווה בחייו לתת נכסיו לאנשים שונים — \u0003ר' אלעזר אומר: אחד בריא ואחד מסוכן, נכסים שיש להן אחריות\u0004 כגון קרקעות וכיוצא בהם — \u0003נקנין בכסף ובשטר ובחזקה, ו\u0004נכסים \u0003שאין להן אחריות\u0004 (מיטלטלים) — \u0003אין נקנין אלא במשיכה.\u0004 \u0003ו\u0004אילו \u0003חכמים אומרים:\u0004 אם היה הנותן שכיב מרע \u0003אלו ואלו נקנין באמירה,\u0004 ואין צורך בקנין נוסף.","\u0003אמרו לו\u0004 לר' אלעזר: הלא \u0003מעשה\u0004 היה \u0003באמן של\u0004 משפחת \u0003בני רוכל שהיתה חולה, ואמרה: \"תינתן\u0004"],["\u0003כבינתי\u0004 (סיכת קישוט שלי) \u0003לבתי, והיא\u0004 הסיכה \u0003ב\u0004שווי של \u0003שנים עשר מנה\", ומתה\u0004 האשה, \u0003וקיימו חכמים את דבריה! אמר להם\u0004 ר' אלעזר: אין להביא משם ראיה, \u0003בני רוכל תקברם אמם\u0004 (לשון קללה), אין מקום להביא ראיה מהם מפני שאנשים רשעים היו, ולכן עשו חכמים בהם מעשה שאינו כשורת הדין ונתנו תכשיט יקר זה לאחותם. ומעתה נאמר כי ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 סבור \u0003כר' אלעזר\u0004 שצריך קנין ממש, ואם לא עשה קנין, הכסף שייך עדיין לנותן. \u0003ור' נתן ור' יעקב נמי\u0004 \u0005[גם כן]\u0006 סבורים \u0003כר' אלעזר, אף על גב דמית\u0004 \u0005[אף על פי שמת]\u0006 המצווה, \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003מצוה לקיים דברי המת. ו\u0004המכונים \u0003\"יש אומרים\"\u0004 סבורים \u0003כרבנן\u0004 \u0005[כחכמים]\u0006 האומרים שדברי שכיב מרע נקנים באמירה.","","\u0003ור' יהודה הנשיא שאמר משום\u0004 (בשם) \u0003ר' מאיר\u0004 סבור \u0003כר' אלעזר, מיהו היכא דמית\u0004 \u0005[אמנם במקום שמת]\u0006 הנותן \u0003אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003מצוה לקיים דברי המת. וחכמים אומרים יחלוקו\u0004 — \u0003מספקא להו\u0004 \u0005[מסופק להם]\u0006 מה לעשות, \u0003ו\u0004בעלי הדעה המכונה \u0003\"כאן אמרו\"\u0004 סבורים ש\u0003שודא עדיף\u0004 \u0005[הכרעה עדיפה],\u0006 \u0003ור' שמעון הנשיא —\u0004 \u0003מעשה אתא לאשמועינן\u0004 \u0005[בא להשמיע לנו]\u0006 ולא דעה נוספת.","אגב הבאת דברי הברייתא, מביאים: \u0003אבעיא להו\u0004 \u0005[נשאלה להם\u0006 שאלה ללומדים\u0005]:\u0006 \u0003ר' שמעון הנשיא\u0004 הנזכר כאן, \u0003נשיא הוא, או\u0004 הכוונה היא ש\u0003משמיה\u0004 \u0005[משמו]\u0006 של ה\u0003נשיא קאמר\u0004 \u0005[\u0006הוא \u0005אומר]?\u0006 והכוונה כאן, ר' שמעון אומר: אמר הנשיא וכו'. ואומרים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ממה ש\u0003אמר רב יוסף\u0004 במילים אלה בדיוק: \u0003הלכה כר' שמעון הנשיא.\u0004 ושואלים: \u0003ו\u0004אף על פי שקבע הלכה כמותו \u0003עדיין תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 השאלה: \u0003נשיא הוא, או דקאמר משמיה דנשיא\u0004 \u0005[ש\u0006הוא \u0005אומר משמו של הנשיא]?\u0006 ואומרים: אין תשובה לשאלה זו, ו\u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003גופא\u0004 \u0005[לגופם]\u0006 של הדברים ש\u0003אמר רב יוסף: הלכה כר' שמעון הנשיא,\u0004 תוהים: \u0003והא קיימא לן\u0004 \u0005[והרי מוחזק בידינו]\u0006 ש\u0003דברי שכיב מרע ככתובין וכמסורין דמו\u0004 \u0005[נחשבים],\u0006 ולכן היה צריך השליח למסור את הכספים ליורשי המקבל, ואילו פסק ההלכה הזה אינו כן!","ומשיבים: \u0003רב יוסף מוקי לה\u0004 \u0005[מעמיד,\u0006 מסביר, \u0005אותה]\u0006 את ההלכה הזו \u0003בבריא\u0004 ולא בחולה. ותוהים: \u0003והא\u0004 \u0005[וזה]\u0006 \u0003ליורשי משלח קאמר\u0004 \u0005[אמר],\u0006 \u0003וקיימא לן\u0004 \u0005[ומוחזק בידינו]:\u0006 \u0003מצוה לקיים דברי המת\u0004 אף על פי שציווה על כך כשהיה בריא! ומשיב: \u0003תני\u0004 \u0005[שנה]\u0006 ותקן כאן בדברי ר' שמעון הנשיא: \u0003יחזרו למשלח\u0004 ולא ליורשי המשלח, שאין אנו עוסקים במקרה שמת המשלח.","","\u0003המביא גט ממדינת הים, ואמר \"בפני נכתב\u0004 הגט \u0003אבל לא בפני נחתם\",\u0004 או \u0003\"בפני נחתם אבל לא בפני נכתב\",\u0004 או שאמר \u0003\"בפני נכתב כולו ובפני נחתם חציו\",\u0004 שראיתי רק חתימה של עד אחד, או \u0003\"בפני נכתב חציו ובפני נחתם כולו\" —\u0004 הרי זה \u0003פסול.\u0004","היה עד \u0003אחד אומר \"בפני נכתב\" ו\u0004עד \u0003אחד אומר \"בפני נחתם\" — פסול.\u0004 היו \u0003שנים אומרים \"בפנינו נכתב\" ואחד אומר \"בפני נחתם\" —\u0004 \u0003פסול, ור' יהודה מכשיר.\u0004 היה \u0003אחד אומר \"בפני נכתב\" ושנים אומרים \"בפנינו נחתם\" —\u0004 \u0003כשר.\u0004","על כל דברי המשנה שואלים: \u0003הא תו\u0004 \u0005[זו עוד]\u0006 \u0003למה לי? הא תנא ליה חדא זימנא\u0004 \u0005[הרי שנה אותו,\u0006 את הדינים הללו, כבר \u0005פעם אחת],\u0006 שכן \u0003שנינו:\u0004 \u0003המביא גט ממדינת הים, צריך שיאמר \"בפני נכתב ובפני נחתם\"\u0004 ומשמע שאם לא אמר כמו כן — הרי זה פסול! ודוחים: \u0003אי מההיא הוה אמינא\u0004 \u0005[אם מאותה\u0006 משנה בלבד \u0005הייתי אומר]:\u0006 אמנם \u0003צריך\u0004 לומר כן, \u0003ואי\u0004 \u0005[ו\u0006אולם \u0005אם]\u0006 \u0003לא אמר —\u0004 בכל זאת \u0003כשר\u0004 הגט בדיעבד, ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שהגט פסול.","שנינו במשנה שאם אמר \u0003\"בפני נכתב חציו ובפני נחתם כולו\" —\u0004 \u0003פסול.\u0004 ושואלים: \u0003הי\u0004 \u0005[באיזה]\u0006 \u0003חציו\u0004 של הגט מדובר? \u0003אלימא\u0004 \u0005[אם תאמר]\u0006 שראה השליח שנכתב \u0003חציו\u0004 ה\u0003ראשון, והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אלעזר: אפילו לא כתב בו אלא שיטה\u0004 (שורה) \u0003אחת לשמה, שוב אינו צריך\u0004 לבדוק! \u0003אלא אמר רב אשי:\u0004 שראה שנכתב \u0003חציו אחרון\u0004 ואינו מעיד על חציו הראשון, שעליו בעיקר הוא צריך להעיד.","שנינו במשנה שאם אמר \u0003\"בפני נכתב כולו ובפני נחתם חציו\"\u0004 — \u0003פסול. אמר רב חסדא: ואפילו\u0004 היו \u0003שנים מעידים על חתימת יד\u0004 העד ה\u0003שני\u0004 ומקיימים אותה בחתימתו — \u0003פסול. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? הרי לכאורה יש לנו את עדות השליח שהיא מועילה לעד אחד, וקיום שלם של חתימת העד השני!","אלא הטעם הוא: \u0003או\u0004 שיהיה \u0003כולו בקיום הגט,\u0004 שיקיימו את הגט כפי שעושים בכל קיום שטרות, שמעידים שניים על חתימות שני העדים שבגט, \u0003או כולו בתקנת חכמים,\u0004 שיש לומר על כולו בשלימות \"בפני נכתב ובפני נחתם\".","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא: מי איכא מידי\u0004 \u0005[האם יש דבר]\u0006 ש\u0003אילו אמר\u0004 אותו \u0003חד\u0004 \u0005[אחד]\u0006 היה \u0003כשר,\u0004 שהרי אם השליח היה אומר שהוא מכיר את חתימת העד השני היה די בכך, \u0003השתא דאיכא תרי\u0004 \u0005[עכשיו שיש שני\u0006 עדים\u0005]\u0006 האומרים כך הרי הוא \u0003פסול? אלא אמר רבא:\u0004 יש לומר \u0003אפילו\u0004"],["\u0003הוא,\u0004 השליח, \u0003ואחר מעידין על חתימת יד\u0004 ה\u0003שני\u0004 — \u0003פסול\u0004 הגט. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? שמא \u0003אתו לאיחלופי\u0004 \u0005[יבואו להחליף]\u0006 את הדבר ולהכשיר אף \u0003בקיום שטרות דעלמא\u0004 \u0005[בכלל],\u0006 ויסמכו על עד אחד שמעיד על חתימת אחד החתומים, ועוד יצטרף עם אחר להעיד על חתימה אחרת, \u0003ו\u0004נמצא כי \u0003קא נפיק נכי ריבעא דממונא אפומא דחד סהדא\u0004 \u0005[יוצא הכל פחות רבע\u0006 (כלומר, שלושה רבעים) \u0005של הממון על פיו של עד אחד].\u0006","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי: מי איכא מידי\u0004 \u0005[האם יש דבר],\u0006 ש\u0003אילו מסיק ליה איהו לכוליה דיבורא\u0004 \u0005[הוא\u0006 עצמו \u0005היה גומר את כל דיבורו]\u0006 שאילו היה אומר רק \"בפני נכתב ובפני נחתם\" היה \u0003כשר, השתא דאיכא חד בהדיה\u0004 \u0005[עכשיו שיש\u0006 עוד \u0005אחד איתו]\u0006 \u0003פסול?!\u0004","\u0003אלא אמר רב אשי: אפילו אומר\u0004 השליח \u0003\"אני הוא עד שני\"\u0004 החתום על הגט — \u0003פסול. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — אין הגט כשר על ידי צירוף שני סוגים שונים של נאמנות. ולכן \u0003או\u0004 שיהיה \u0003כולו בקיום הגט\u0004 כפי שמקיימים שטרות אחרים, ובזה אדם נאמן להעיד על חתימת עצמו בכל שטר שהוא, \u0003או כולו בתקנת חכמים\u0004 שהאמינו לשליח הגט כשניים להעיד על חתימת אחרים.","ומנסים להביא ראיה לכך, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 שליח הגט שאמר \u0003\"בפני נכתב כולו, בפני נחתם חציו\"\u0004 — אותו הגט \u0003פסול.\u0004 ונברר: \u0003אידך\u0004 \u0005[אותו]\u0006 \u0003חציו\u0004 האחר \u0003היכי דמי\u0004 \u0005[איך הוא בדיוק]?\u0006 \u0003אילימא דליכא דקא מסהיד עליה\u0004 \u0005[אם תאמר שאין\u0006 מי \u0005שמעיד עליו]\u0006 \u0003כלל,\u0004 יש לשאול: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 שנינו במשנה שאם \u0003אחד אומר \"בפני נכתב\" ואחד אומר: \"בפני נחתם\", דהאי קמסהיד אכולה\u0004 \u0005[שזה מעיד על כל]\u0006 ה\u0003כתיבה והאי קמסהיד אכולה\u0004 \u0005[וזה מעיד על כל]\u0006 ה\u0003חתימה\u0004 — \u0003פסול,\u0004 אם כן כאשר מעיד \u0003\"\u0004בפני נחתם \u0003חציו\" מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שפסול?","\u0003אלא\u0004 חידוש יש כאן, שאף אם יש עדות נוספת על החתימה השניה — הגט פסול. ודבר זה יש לפרש \u0003או כ\u0004דברי \u0003רבא\u0004 כשמצרף לעדות על חצי החתימה עדות אחרת של אחר, \u0003או כ\u0004דברי \u0003רב אשי\u0004 כשמעיד על חתימתו שלו,","\u0003ולאפוקי\u0004 \u0005[ולהוציא]\u0006 \u0003מ\u0004דברי \u0003רב חסדא\u0004 שפוסל אף כשיש קיום מלא לחתימה השניה, שדבר כזה צריכה היתה המשנה לומר בפירוש.","ודוחים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב חסדא: ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שכך אתה מדייק, אם כן מה ששנינו שם שאם אמר השליח \u0003\"בפני נכתב אבל לא בפני נחתם\"\u0004 שהגט פסול, \u0003למה לי?\u0004 הרי היה יכול לומר רק שאם אמר \"בפני נכתב כולו ובפני נחתם חציו\" — פסול, וכל שכן אם אינו מעיד כלל על החתימה! \u0003אלא\u0004 צריך אתה לומר כי התנא של המשנה בסגנון \u0003לא זו אף זו קתני\u0004 \u0005[שנה]\u0006 את המשנה, שמוסיף חידוש יתר בכל פיסקה, אם כן,","\u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 תפרש ש\u0003לא זו אף זו קתני\u0004 \u0005[שנה]\u0006 ואין לדייק מכאן להוציא מדברי רב חסדא.","אגב הבאת מחלוקת זו, מביאים דיון בנושא שהעיקרון שבו דומה לדברים הללו; \u0003אמר רב חסדא:\u0004 הדבר המועיל להבדיל בין שתי רשויות לענין איסור טלטול בשבת הוא מחיצה בת עשרה טפחים, בין שעשויה בגובה (כגדר) ובין שהיא בעומק (כחפירה, תעלה), אבל אם היה \u0003גידוד\u0004 (חפירה) בעומק של \u0003חמשה\u0004 טפחים \u0003ו\u0004מעליו \u0003מחיצה\u0004 של \u0003חמשה\u0004 טפחים — \u0003אין מצטרפין\u0004 לשיעור עשרה טפחים, \u0003עד שיהא או כולו במחיצה או כולו בגידוד.\u0004","לעומת זאת \u0003דרש מרימר\u0004 ברבים: \u0003גידוד חמשה ומחיצה חמשה\u0004 — \u0003מצטרפין.\u0004 ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006 \u0003מצטרפין.\u0004","ואגב כך, מובא נושא נוסף שיש בו עקרון דומה, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003אילפא: ידים\u0004 לנטילת ידיים, \u0003טהורות לחצאין, או אין טהורות לחצאין?\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 הוא \u0005בדיוק\u0006 הדבר\u0005]\u0006 שדן בו אילפא שידיים טהורות לחצאין? \u0003אילימא דקא משו בי תרי\u0004 \u0005[אם תאמר שנוטלים שני\u0006 אנשים\u0005]\u0006 \u0003מרביעית\u0004 אחת של מים, ונמצא שכל אחד מהם בפועל נוטל רק במחצית, \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה במפורש\u0005]:\u0006 \u0003מרביעית\u0004 אחת \u0003נוטלין לידים,\u0004 \u0003ל\u0004אדם \u0003אחד ואפילו לשנים,\u0004 וזה ודאי כשר!","\u0003ואלא\u0004 תאמר כך: \u0003דקא משי חדא חדא ידיה\u0004 \u0005[ש\u0006הוא \u0005נוטל אחת אחת,\u0006 את שתי \u0005ידיו]\u0006 ולא את שתיהן יחד, \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003הנוטל ידו אחת בנטילה\u0004 מכלי \u0003ו\u0004ידו \u0003אחת בשטיפה,\u0004 שטובל אותה בנהר — \u0003ידיו טהורות,\u0004 משמע שהנטילה אינה צריכה להיות בשתי ידיים כאחת!","\u0003ואלא\u0004 כך צריך לפרש את שאלתו של אילפא: מדובר \u0003דקא משי פלגא פלגא דידיה\u0004 \u0005[ש\u0006הוא \u0005נוטל חצי חצי של ידו],\u0006 כלומר, נוטל קודם מחצית היד ואחר כך מחצית שניה, \u0003והאמרי\u0004 \u0005[והרי אמרו]\u0006 חכמים \u0003דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי: ידים\u0004 — \u0003אין טהורות לחצאין\u0004 ואם כן, כשהוא נוטל כל פעם מחצית ידו אינו מועיל בכך כלל! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 שאלה זו של אילפא אלא במקרה \u0003דאיכא\u0004 \u0005[שיש]\u0006 עדיין \u0003משקה טופח,\u0004 שבשעה שנוטל מחצית היד השניה נותרה עדיין רטיבות כלשהי על מחצית היד שכבר נטל, ואפשר היה לחשוב שהיא מצטרפת עם המים שנוטל בהם את החצי השני.","ושואלים: \u0003וכי איכא\u0004 \u0005[וכאשר יש]\u0006 \u0003משקה טופח, מאי הוי\u0004 \u0005[מה יש]?\u0006 האם דבר זה מועיל? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006"],["\u0003הנצוק\u0004 (קילוח של מים), \u0003והקטפרס\u0004 (מים היורדים במדרון משופע), \u0003ומשקה טופח\u0004 — \u0003אינו\u0004 נחשב \u0003חיבור לא לטומאה ולא לטהרה!\u0004 לטומאה — שאם היו מים טמאים במקום אחד, ונתחברו למים אחרים שלמעלה מהם על ידי ניצוק — אין המים שלמעלה נחשבים כמחוברים ואינם נטמאים. ולטהרה — שאם היו שני מקווי מים המחוברים בניצוק, אין הם מצטרפים לידי שיעור מקווה לטהר. ואם כן, אף בנטילת ידיים לא ייחשב משקה טופח לחבר בין שני חצאי היד שנטלם!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דאיכא\u0004 \u0005[שיש]\u0006 משקה שהוא \u0003טופח להטפיח,\u0004 שחצי היד שכבר ניטלה אינה רטובה במעט, אלא שרטיבות זו היא רבה כל כך עד שיכולה להרטיב דבר אחר. ותוהים: \u0003הא נמי תנינא\u0004 \u0005[\u0006הלא \u0005זו גם כן שנינו]\u0006 במפורש: \u0003טופח להטפיח\u0004 — \u0003חיבור\u0004 הוא, ומה מקום לשאלתו של אילפא!","ודוחים: \u0003דלמא\u0004 \u0005[שמא]\u0006 מה שאמרו שם שהוא חיבור הרי זה \u0003לענין מקואות\u0004 בלבד, \u0003ו\u0004הלכה זו ששנה \u0003ר' יהודה היא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מקוה שיש בו ארבעים סאה מכוונות\u0004 בדיוק, ולא יותר מזה, \u0003וירדו שנים וטבלו\u0004 בו, אם טבלו \u0003שניהם בבת אחת\u0004 — \u0003טהורים,\u0004 ואם טבלו","\u0003בזה אחר זה\u0004 — \u0003ראשון\u0004 בהם \u0003טהור,\u0004 שהרי טבל במקווה שיש בו שיעור שלם, \u0003והשני טמא\u0004 משום שמקצת מהמים שבמקווה בוודאי דבקו בראשון והוציאם עמו, ונמצא שעכשיו יש במקווה פחות מעט מארבעים סאה.","\u0003ר' יהודה אומר: אם היו רגליו של ראשון נוגעות\u0004 עדיין \u0003במים\u0004 שבמקווה כאשר טבל בו השני — \u0003אף השני טהור.\u0004 שלדעת ר' יהודה המים שעל גופו של הטובל מצטרפים עם המים שבתוך המקוה להשלים לשיעור מקווה. ולמדנו איפוא שלדעתו טופח להטפיח הוא חיבור. אבל הלכה זו שמענו רק לענין מקווה, ואין זה ברור מה הדין לענין נטילת ידיים כאשר יש טופח להטפיח בין נטילת מחצית ראשונה של ידיו למחציתן השניה. ואם כן לא נמצא פתרון לשאלתו של אילפא.","ומביאים שאלה נוספת בענין זה: \u0003אמר ר' ירמיה\u0004 והקדים לכך, \u0003הרי אמרו\u0004 במשנה: \u0003הבא ראשו ורובו,\u0004 שנכנס כל גופו (או רובו) \u0003במים שאובין,\u0004 או \u0003טהור שנפלו\u0004 (נשפכו) \u0003על ראשו ועל רובו שלשה לוגין מים שאובין\u0004 — \u0003טמא\u0004 משום גזירת חכמים. בעקבות זה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה:\u0004 אם \u0003חציו בביאה,\u0004 חצי גופו הכניס במים, \u0003וחציו בנפילה\u0004 של מים עליו, \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין, האם מצטרפים הם לטמא אותו, או לא? לא נמצא פתרון לשאלה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003אמר רב פפא\u0004 כיוצא בזה, \u0003הרי אמרו: בעל קרי חולה\u0004 \u0003ש\u0004אינו יכול לטבול ולכך \u0003נתנו\u0004 (שפכו) \u0003עליו תשעה קבין מים\u0004 — \u0003טהור\u0004 ומותר להתפלל וללמוד תורה. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא: חציו בטבילה וחציו בנתינה, מאי\u0004 \u0005[מה]\u0006 יהא הדין? גם לשאלה זו לא נמצא פתרון, ועל אף היא \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","שנינו במשנה: \u0003אחד אומר \"בפני נכתב\" ואחד אומר\u0004 \"בפני נחתם\" — פסול. \u0003אמר רב שמואל בר יהודה אמר ר' יוחנן: לא שנו\u0004 שבמקרה שכזה הגט פסול \u0003אלא שאין הגט יוצא\u0004 בבית הדין \u0003מתחת ידי שניהם,\u0004 שלא היו שניהם שליחים בהבאתו אלא רק אחד מהם, והוא לא אמר \"בפני נכתב ובפני נחתם\" כתקנת חכמים. \u0003אבל\u0004 אם היה \u0003גט יוצא מתחת ידי שניהם\u0004 —"],["\u0003כשר.\u0004 ומעירים: \u0003אלמא קסבר\u0004 \u0005[מכאן\u0006 שהוא \u0005סבור]\u0006 ש\u0003שנים שהביאו גט ממדינת הים, אין צריכין שיאמרו: \"בפנינו נכתב ובפנינו נחתם\".\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה\u0004 שהמשנה מדברת באופן זה דווקא, אם כן \u0003סיפא דקתני\u0004 \u0005[סופה\u0006 של המשנה \u0005ששנה\u0006 בה\u0005]:\u0006 \u0003שנים אומרים \"בפנינו נכתב\" ואחד אומר \"בפני נחתם\"\u0004 — \u0003פסול, ור' יהודה מכשיר.\u0004","ונדייק: \u0003טעמא\u0004 \u0005[הטעם]\u0006 דווקא כש\u0003אין הגט יוצא מתחת ידי שניהם, הא\u0004 \u0005[הרי]\u0006 אם היה ה\u0003גט יוצא מתחת ידי שניהם\u0004 — \u0003מכשרי רבנן\u0004 \u0005[מכשירים\u0006 היו \u0005חכמים]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 אכן חכמים מכשירים בזה.","ושואלים: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003אין גט יוצא מתחת ידי שניהם במאי פליגי\u0004 \u0005[במה,\u0006 באיזה עקרון הם \u0005חלוקים]?\u0006 ומסבירים: \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חכמים, \u0005סבור]:\u0006 כי \u0003גזרינן דלמא אתיא לאיחלופי\u0004 \u0005[גוזרים אנו שמא יבואו להחליף]\u0006 את הדבר הזה \u0003בקיום שטרות דעלמא\u0004 \u0005[סתם]\u0006 ויקיימו כל סוגי שטרות \u0003ב\u0004עדות \u0003עד אחד. ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יהודה, \u0005סבור]:\u0006 ש\u0003לא גזרינן\u0004 \u0005[אין אנו גוזרים]\u0006 גזירה זו.","\u0003לישנא אחרינא אמרי לה\u0004 \u0005[\u0006ב\u0005לשון אחרת אומרים\u0006 כל \u0005אותה]\u0006 סוגיה באופן אחר: \u0003אמר רב שמואל בר יהודה אמר ר' יוחנן: אפילו גט יוצא מתחת ידי שניהם\u0004 — \u0003פסול.\u0004 ומעירים: \u0003אלמא קסבר\u0004 \u0005[מכאן\u0006 שהוא \u0005סבור]\u0006 ש\u0003שנים שהביאו גט ממדינת הים, צריכין שיאמרו \"בפנינו נכתב ובפנינו נחתם\".\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה, סיפא דקתני\u0004 \u0005[סופה\u0006 של המשנה \u0005ששנה\u0006 בה\u0005]:\u0006 \u0003שנים אומרים \"בפנינו נכתב\", ואחד אומר \"בפני נחתם\"\u0004 — \u0003פסול, ור' יהודה מכשיר,\u0004 האם \u0003אפילו\u0004 כאשר \u0003גט יוצא מתחת ידי שניהם פסלי רבנן\u0004 \u0005[פוסלים חכמים]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006","ושואלים: \u0003במאי קא מיפלגי\u0004 \u0005[במה\u0006 הם \u0005חלוקים]?\u0006 ומשיבים: \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חכמים, \u0005סבור]\u0006 שהטעם לאמירת \"בפני נכתב ובפני נחתם\" הוא \u0003לפי שאין\u0004 בני מדינת הים \u0003בקיאין\u0004 בכתיבת גט \u0003לשמה\u0004 ויש צורך שיעיד אותו עד גם על הכתיבה וגם על החתימה לשמה, כתקנת חכמים, אף אם שנים הביאו את הגט. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יהודה, \u0005סבור]:\u0006 שהטעם הוא \u0003לפי שאין עדים מצויין לקיימו,\u0004 וכשיש שנים שהביאו את הגט, הרי יש מי שמצוי לקיימו.","ושואלים: אם כן, \u0003לימא\u0004 \u0005[האם לומר]\u0006 שמחלוקת \u0003רבה ורבא\u0004 באותו נושא מחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003היא?\u0004 ודוחים: \u0003לא, רבא מתרץ\u0004 \u0005[מיישב]\u0006 את כל הענין \u0003כלישנא קמא\u0004 \u0005[כמו הלשון הראשונה]\u0006 לפיה שנים שהביאו גט אינם צריכים לומר \"בפנינו נכתב ובפנינו נחתם\", ואפשר להסביר את שתי הדעות החולקות כמי שסבורות שהטעם לתקנת \"בפני נכתב ובפני נחתם\" הוא כדי שיהיו עדים מצויים לקיימו.","\u0003ורבה אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 כלשון השניה בדברי רב שמואל בר יהודה, לפיה אף שניים שהביאו גט צריכים לומר \"בפנינו נכתב ובפנינו נחתם\", \u0003דכולי עלמא בעינן\u0004 \u0005[\u0006לדעת \u0005הכל צריכים אנו]\u0006 שיעידו על כתיבה \u0003לשמה, והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים]\u0006 — \u0003לאחר שלמדו\u0004 במדינת הים לכתוב גט לשמה,","\u0003ו\u0004אולם \u0003בגזירה שמא יחזור הדבר לקלקולו\u0004 ושוב לא יהיו בני מדינת הים בקיאים לשמה \u0003קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003גזרינן\u0004 \u0005[גוזרים אנו]\u0006 גזירה זו, ולכן אנו מצריכים עדות גם לאחר שלמדו, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יהודה, \u0005סבור]:\u0006 \u0003לא גזרינן\u0004 \u0005[אין אנו גוזרים]\u0006 גזירה זו.","ושואלים: \u0003ו\u0004אם כן, \u0003ליפלוג נמי\u0004 \u0005[ושיחלוק גם כן]\u0006 \u0003ר' יהודה ברישא\u0004 \u0005[בתחילתה\u0006 של המשנה\u0005]\u0006 בעד אחד אומר \"בפני נכתב\" והשני אומר \"בפני נחתם\"! ומדוע חולק הוא רק במקרה זה? ומשיבים: אכן חלוק הוא גם על הרישא, שכן \u0003הא אתמר עלה\u0004 \u0005[הרי\u0006 כבר \u0005נאמר עליה],\u0006 ש\u0003אמר עולא: חלוק היה ר' יהודה אף בראשונה\u0004 (בתחילת המשנה).","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב אושעיא לעולא\u0004 ממה ששנינו: \u0003ר' יהודה מכשיר בזו ולא באחרת. מאי לאו\u0004 \u0005[האם לא]\u0006 בא זה \u0003למעוטי\u0004 \u0005[למעט]\u0006 את המקרה של \u0003אחד אומר \"בפני נכתב\" ואחד אומר \"בפני נחתם\"?\u0004","ודוחים: \u0003לא,\u0004 הדבר בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 במקרה שהעיד רק עד אחד \u0003\"בפני נחתם אבל לא בפני נכתב\",\u0004 ומדוע יש צורך להדגיש זאת? — כי \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]:\u0006 \u0003הואיל ולא גזר ר' יהודה גזירה שמא יחזור דבר לקלקולו,\u0004 אם כן באותה מידה גם את גזירת \u0003דלמא אתי לאחלופי\u0004 \u0005[שמא יבואו להחליף]\u0006 את הדבר \u0003בקיום שטרות דעלמא\u0004 \u0005[סתם]\u0006 \u0003בעד אחד נמי\u0004 \u0005[גם כן]\u0006 \u0003לא גזר,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006","שאף על פי שלא חשש לקלקול, והוא סבור שאין לחשוש עוד בזמן הזה לכתיבה לשמה, מכל מקום להשוואה לקיום שטרות חשש. \u0003אתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 כיוצא בדברי ר' יוחנן בשם אמורא אחר, \u0003אמר רב יהודה: שנים שהביאו גט ממדינת הים, באנו למחלוקת ר' יהודה ורבנן\u0004 \u0005[וחכמים].\u0006 משמע שאף הוא סבור שלדעת חכמים שניים המביאים גט צריכים לומר \"בפני נכתב ובפני נחתם\".","מסופר: \u0003רבה בר בר חנה חלש\u0004 \u0005[חלה],\u0006 \u0003עול לגביה\u0004 \u0005[נכנסו אליו]\u0006 \u0003רב יהודה ורבה לשיולי ביה\u0004 \u0005[לשאול בו,\u0006 בשלומו\u0005].\u0006 וכיון שבאו לבקרו \u0003בעו מיניה\u0004 \u0005[שאלו אותו]\u0006 שאלה זו: \u0003שנים שהביאו גט ממדינת הים,\u0004 האם \u0003צריכין שיאמרו \"בפנינו נכתב ובפנינו נחתם\", או אין צריכין? אמר להם: אין צריכין,\u0004 וטעמו של דבר: \u0003מה אילו יאמרו \"בפנינו גירשה\" מי\u0004 \u0005[האם]\u0006 \u0003לא מהימני\u0004 \u0005[יהיו נאמנים]?\u0006 ואם כן, אפילו אם לא היו מביאים גט לא היו צריכים לכך, וכל שכן כשמביאים גט. ומספרים אגב כך: \u0003אדהכי\u0004 \u0005[בינתיים],\u0006 בעוד הם יושבים שם, \u0003אתא ההוא\u0004 \u0005[נכנס אותו]\u0006"],["\u0003חברא\u0004 \u0005[כומר פרסי],\u0006 \u0003שקלה לשרגא מקמייהו\u0004 \u0005[לקח את הנר מלפניהם],\u0006 שהיה זה יום חג שלהם שבו לא הניחו שיהיה אור אלא בבית מקדשם, \u0003אמר\u0004 רבה בר בר חנה שהיה מארץ ישראל: \u0003רחמנא\u0004 \u0005[ריבונו של עולם]!\u0006 \u0003או בטולך, או בטולא דבר עשו\u0004 \u0005[או בצילך, או בצל של בני עשו,\u0006 הרומאים\u0005]\u0006 כי קשה מאד לחיות תחת השלטון הפרסי.","ושואלים: \u0003למימרא, דארומאי מעלו מפרסאי\u0004 \u0005[האם\u0006 ניתן מדבר זה \u0005לומר, שהרומאים מעולים מהפרסיים]?\u0006 \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' חייא, מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"אלהים הבין דרכה והוא ידע את מקומה\"\u0004 (איוב כח, כג) — \u0003יודע הקדוש ברוך הוא בישראל שאין יכולין לקבל גזירת ארומיים, עמד והגלה אותם לבבל.\u0004 משמע שהבבליים טובים יותר!","ודוחים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא מקמי דניתו חברי\u0004 \u0005[זה לפני שהגיעו החברים]\u0006 \u0003לבבל,\u0004 שאז היה שם נוח יותר, \u0003הא לבתר דאתו חברי\u0004 \u0005[זה לאחר שהגיעו החברים]\u0006 \u0003לבבל\u0004 ואז השתנה המצב ונהיה קשה יותר.","שנינו במשנה שאם \u0003אחד אומר \"בפני נכתב\", ושנים אומרים \"בפנינו נחתם\"\u0004 — \u0003כשר. אמר ר' אמי אמר ר' יוחנן : לא שנו\u0004 שהגט כשר \u0003אלא\u0004 כ\u0003שהגט יוצא מתחת יד עד\u0004 ה\u0003כתיבה\u0004 שהוא השליח להביא את הגט, ש\u0003נעשו כשנים על זה וכשנים על זה,\u0004 שכיון שהוא שליח הגט, הריהו נאמן כשניים בעדותו על הכתיבה, \u0003אבל\u0004 אם יוצא הגט \u0003מתחת ידי עדי\u0004 ה\u0003חתימה\u0004 — \u0003פסול,\u0004 שהרי רק עד אחד שאינו שליח הגט מעיד על הכתיבה.","ומעירים: \u0003אלמא קסבר\u0004 \u0005[מכאן\u0006 שהוא \u0005סבור]:\u0006 \u0003שנים שהביאו גט ממדינת הים, צריכין שיאמרו: \"בפנינו נכתב ובפנינו נחתם\",\u0004 ואם לא אמרו — הריהו פסול. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אסי\u0004 לר' יוחנן: \u0003אלא מעתה, רישא דקתני\u0004 \u0005[\u0006ב\u0005ראשה\u0006 של המשנה \u0005ששנה\u0006 בה\u0005]:\u0006 \u0003שנים אומרים \"בפנינו נכתב\", ואחד אומר \"בפני נחתם\"\u0004 — \u0003פסול, ור' יהודה מכשיר, ו\u0004כי \u0003אפילו\u0004 כאשר ה\u0003גט יוצא מתחת ידי שניהם פסלי רבנן\u0004 \u0005[פוסלים חכמים]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006","ומסופר: \u0003זימנין אשכחיה דיתיב וקאמר\u0004 \u0005[פעם\u0006 אחרת \u0005מצא\u0006 ר' אסי, \u0005אותו,\u0006 את ר' יוחנן שהוא \u0005יושב ואומר]\u0006 ש\u0003אפילו גט יוצא מתחת ידי עדי חתימה\u0004 — \u0003כשר.\u0004 ומעירים: \u0003אלמא קסבר\u0004 \u0005[מכאן\u0006 שהוא \u0005סבור]\u0006 כי \u0003שנים שהביאו גט ממדינת הים, אין צריכין שיאמרו: \"בפנינו נכתב ובפנינו נחתם\".\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אסי: אלא מעתה,\u0004 לדרך זו, \u0003רישא דקתני\u0004 \u0005[בראשה\u0006 של המשנה \u0005ששנה\u0006 בה]: \u0003שנים אומרים \"בפנינו נכתב\" ואחד אומר \"בפני נחתם\"\u0004 — \u0003פסול, ור' יהודה מכשיר,\u0004 נדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003אין הגט יוצא מתחת ידי שניהם, הא\u0004 \u0005[הרי]\u0006 אם היה ה\u0003גט יוצא מתחת ידי שניהם\u0004 — \u0003מכשרי רבנן\u0004 \u0005[מכשירים חכמים]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003אין\u0004 \u0005[כן].\u0006 אמר לו ר' אסי: \u0003והא זמנין\u0004 \u0005[והרי\u0006 ב\u0005פעם\u0006 אחרת\u0005]\u0006 \u0003לא אמרת לן הכי\u0004 \u0005[לנו כך]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 מה שאני אומר לך עכשיו \u0003יתד היא שלא תמוט,\u0004 ויכול אתה לסמוך על כך, ואני חוזר בי ממה שאמרתי קודם.","\u0003נכתב\u0004 הגט \u0003ביום ונחתם ב\u0004אותו \u0003יום,\u0004 או נכתב \u0003בלילה ונחתם ב\u0004אותו \u0003לילה,\u0004 או נכתב \u0003בלילה ונחתם ביום\u0004 שלאחריו — \u0003כשר,\u0004 שהרי היום הולך אחר הלילה, ולכתיבה ולחתימה יש איפוא תאריך אחד. אבל אם נכתב \u0003ביום ונחתם בלילה\u0004 שלאחריו — \u0003פסול. ר' שמעון מכשיר.\u0004","\u0003שהיה ר' שמעון אומר: כל הגיטין\u0004 (שטרות) \u0003שנכתבו ביום ונחתמו בלילה\u0004 — \u0003פסולין,\u0004 משום שעל ידי כך קודם התאריך הכתוב בו לזמן של חלות השטר, \u0003חוץ מגיטי נשים\u0004 שאין לחשוש בהם לענין זה לפי שהגט אינו עשוי לגביית כספים, ואין חשש אם הזמן הכתוב בו קודם לזמן החתימה.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בשאלה: \u0003מפני מה תיקנו\u0004 לכתוב \u0003זמן\u0004 (תאריך) \u0003בגיטין?\u0004 הרי לכאורה השטר הזה אינו שטר גבייה! \u0003ר' יוחנן אמר: משום בת אחותו,\u0004 שאם יש לו אשה החביבה עליו, כגון שהיא בת אחותו, וחושש שזנתה תחתיו והוא רוצה להצילה מעונש על כך, יתן לה גט בלי תאריך, ואם יבואו עדים ויעידו שזנתה בזמן מסויים תוכל לטעון שהיתה כבר גרושה באותו זמן, וכדי שלא תיעשה עורמה כזו תיקנו שייכתב זמן בגט.","\u0003ריש לקיש אמר: משום פירות,\u0004 שמזמן הגט והלאה אם מוכר הבעל את פירות הנכסים שלה, יכולה האישה לגבות מן הקונים את מחיר הפירות, ואם אין זמן בגט אינה יכולה להוכיח שנמכרו הפירות לאחר שנתגרשה ולא תגבה מן הקונים את המגיע לה.","ושואלים: \u0003ריש לקיש מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כר' יוחנן\u0004 ובחר בהסבר אחר? ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 ריש לקיש:"],["\u0003זנות לא שכיחא\u0004 \u0005[מצוייה]\u0006 ולא היו חכמים מתקנים כתיבת הזמן בגט משום דבר שאינו מצוי.","ושואלים: \u0003ור' יוחנן מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כריש לקיש?\u0004 ומשיבים: \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003יש לבעל פירות עד שעת נתינה\u0004 של הגט, ורק לאחר מכן זוכה האשה בפירות נכסיה. ולכן אם תבוא לטרוף את פירות נכסיה מן הלקוחות, ידרשו הם ממנה ראיה על הזמן בו הגיע הגט לידיה, ומאותה שעה בה הגיע הגט לידיה ודאי תוכל למנוע ממנו מלאכול פירות.","ועוד שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ריש לקיש, משום הכי\u0004 \u0005[כך]\u0006 \u0003קא מכשיר ר' שמעון\u0004 במשנתנו גט שנחתם לאחר יום כתיבתו — משום שהוא סבור שיש לבעל פירות רק עד שעת כתיבת הגט, ואם תבוא לגבות מן הקונים את מה שמכר הבעל אחרי כתיבת הגט — מן הדין היא עושה. \u0003אלא ל\u0004שיטת \u0003ר' יוחנן\u0004 הסבור שהסיבה לכתיבת זמן בגט היא משום חשש זנות, אם כן \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' שמעון\u0004 ש\u0003מכשיר?\u0004","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך ר' יוחנן: אליבא\u0004 \u0005[על דעתו]\u0006 של \u0003ר' שמעון לא קאמינא\u0004 \u0005[איני אומר],\u0006 שהוא בוודאי אינו סבור שהטעם לכתיבת זמן בגט הוא משום זנות, אלא משום טעם אחר. \u0003כי קאמינא, אליבא דרבנן\u0004 \u0005[כאשר אני אומר,\u0006 הרי זה \u0005לדעת חכמים].\u0006","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003ר' יוחנן, היינו דאיכא\u0004 \u0005[זהו\u0006 ההבדל העקרוני \u0005שיש]\u0006 \u0003בין\u0004 שיטת \u0003ר' שמעון ל\u0004שיטת \u0003רבנן\u0004 \u0005[לחכמים],\u0006 שלשיטתו הם נחלקו בעצם השאלה מה טעם כותבים תאריך בגט. \u0003אלא ל\u0004דעת \u0003ריש לקיש, מאי איכא\u0004 \u0005[מה\u0006 הבדל \u0005יש]\u0006 \u0003בין ר' שמעון לרבנן\u0004 \u0005[לחכמים]?\u0006","ומשיבים: \u0003פירי\u0004 \u0005[פירות]\u0006 הנכסים שהגיעו \u0003משעת כתיבה ועד שעת חתימה איכא בינייהו\u0004 \u0005[יש ביניהם],\u0006 שחכמים סבורים שיש לבעל פירות עד שעת חתימת הגט, ולכן אם תאריך כתיבת הגט מוקדם לחתימתו — תטרוף האשה מן הלקוחות שמכר להם בעלה פירות שלא כדין. ואילו לדעת ר' שמעון כבר מזמן הכתיבה אין הבעל זכאי לפירות הנכסים, ואם תגבה האשה פירות שמכר הבעל מאותה שעה — כדין היא עושה.","על הסבר זה למחלוקת ר' יוחנן וריש לקיש מקשים: \u0003והא איפכא שמעינן להו\u0004 \u0005[והרי ההיפך\u0006 מזה \u0005אנו שומעים אותם],\u0006 את ר' יוחנן וריש לקיש, \u0003דאתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בשאלה: \u0003מאימתי מוציאין לפירות?\u0004 כלומר, ממתי יכולים להוציא את הפירות מרשות הבעל שלא ימכרם? \u0003ר' יוחנן אמר: משעת כתיבה, וריש לקיש אמר: משעת נתינה\u0004 ומן הסתם שניהם סבורים כדעת חכמים!","ומתרצים: \u0003איפוך\u0004 \u0005[הפוך]:\u0006 את השיטות במחלוקת האחרונה הזאת, כדי להתאים אותן למה שאמרנו קודם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף:\u0004 הרי שנינו: \u0003שלשה גיטין פסולים\u0004 הם, \u0003ואם ניסת\u0004 (נישאת) האשה לאחר שקיבלה אחד מהגיטין הללו — \u0003הולד כשר,\u0004 ואחד מהם הוא זה שאין בו זמן, ואם כן, \u0003מה הועילו חכמים בתקנתן\u0004 להצריך זמן בגט? שהרי בדיעבד הגט כשר אף בלא זמן! ומשיבים: \u0003אהנו\u0004 \u0005[הועילו]\u0006 ש\u0003לכתחילה לא תינשא\u0004 על סמך גט כזה. ואם כן נמצא שהם ממעטים בנזק שיכול להיגרם.","שאל עוד אביי את רב יוסף: אם אחרי שנכתב הגט \u0003גזייה לזמן דידיה ויהביה ניהלה, מאי\u0004 \u0005[גזז,\u0006 חתך הבעל \u0005את הזמן שלו,\u0006 של הגט, \u0005ונתנו לה,\u0006 את הגט, \u0005מה\u0006 יהיה הדין\u0005]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לרמאי לא חיישינן\u0004 \u0005[אין אנו חוששים]\u0006 עד כדי פסילה מוחלטת של גט שאין בו זמן.","שאל אותו עוד: אם \u0003כתוב בו,\u0004 בגט, כגון באיזה \u0003שבוע\u0004 (מחזור שבע שנות שמיטה) היה הדבר, או באיזו \u0003שנה,\u0004 או באיזה \u0003חדש,\u0004 או באיזה \u0003שבת\u0004 (שבוע), ולא נכתב היום המדוייק, \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כשר.\u0004 שאל אותו: \u0003ו\u0004אם כן, \u0003מה הועילו חכמים בתקנתן,\u0004 בין משום החשש לגביית פירות שלא כדין, ובין משום החשש שמא יחפה על בת אחותו?","השיב לו: בכל מקרה של כתיבת תאריך ישנה תועלת מסויימת, ואפילו כשנכתב באיזו שמיטה היה הדבר, \u0003אהנו\u0004 \u0005[הועילו]\u0006 \u0003לשבוע דקמיה\u0004 \u0005[שלפניו]\u0006 \u0003ולשבוע דבתריה\u0004 \u0005[שלאחריו],\u0006 שאם יבואו עדים שזנתה קודם לשמיטה זו — תתחייב האשה, ואם יבוא הבעל לקחת פירות לאחר שמיטה זו — תוכל האשה להוציא מידו. \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך]\u0006 שהתאריך אינו צריך להיות מדוייק לגמרי, אם כן \u0003יומא גופיה מי ידעינן אי מצפרא אי מפניא\u0004 \u0005[\u0006באותו \u0005יום עצמו האם אנו יודעים אם\u0006 היה זה \u0005בבוקר או בערב]?\u0006 וכל המכשולים שעלולים לקרות, הלא עלולים לקרות אף באותו יום! \u0003אלא\u0004 התאריך מועיל \u0003ליומא דקמיה וליומא דבתריה\u0004 \u0005[ליום שלפניו וליום שלאחריו],\u0006 \u0003הכא נמי אהני\u0004 \u0005[כך גם כן מועיל]\u0006 לפחות \u0003לשבוע דקמיה\u0004 \u0005[שלפניו]\u0006 \u0003ולשבוע דבתריה\u0004 \u0005[שלאחריו].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרבא: כתביה\u0004 \u0005[כתבו\u0006 את הגט\u0005]\u0006"],["\u0003ואותביה בכיסתיה\u0004 \u0005[ושם אותו בכיסו]\u0006 ולא נתנו בינתיים, כיון שחשב \u0003דאי מפייסה, תיפייס\u0004 \u0005[שאם תתפייס\u0006 עימו, \u0005תתפייס]\u0006 ולא יתן לה את הגט, ולבסוף לא התפייסו, ונתן לה את הגט, \u0003מאי\u0004 \u0005[מה]?\u0006 והרי אותם חששות שבגללם התקינו לכתוב זמן בגט קיימים אף שיש בו זמן!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003לא מקדים אינש פורענותא לנפשיה\u0004 \u0005[אדם פורענות לעצמו],\u0006 שאין אדם רגיל להכין גט מראש, שאין אדם טורח בדבר שאינו נעים לו להקדימו, ועושה אותו רק כאשר הוא נזקק לכך, ומשום כך לא חששו חכמים למקרה שכזה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: גיטין הבאים ממדינת הים, דמיכתבי\u0004 \u0005[שכתובים]\u0006 זמניהם \u0003ב\u0004חודש \u0003ניסן ולא מטו\u0004 \u0005[מגיעים]\u0006 לידי האשה \u0003עד\u0004 חודש \u0003תשרי\u0004 ורק אז הם חלים. אם כן, \u0003מה הועילו חכמים בתקנתם?\u0004 שהרי כל החששות בגט שאין בו תאריך מצויים גם בזה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הנהו, קלא אית להו\u0004 \u0005[אלה, קול,\u0006 פירסום, \u0005יש להם],\u0006 שגט הבא ממדינה רחוקה הכל יודעים שלא חל מזמן כתיבתו, וכשיבוא הדבר לדיון, על האשה להביא עדות על זמן מסירתו.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו חכמים בשאלה: \u0003מאימתי מונין לגט?\u0004 כיון שאסרו חכמים לאשה גרושה להינשא עד שיעברו שלושה חודשים מאז שנתגרשה, ממתי מונים שלושה חודשים אלה? \u0003רב אמר: משעת נתינה\u0004 של הגט, \u0003ושמואל אמר: משעת כתיבה\u0004 של הגט.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב נתן בר הושעיא: ל\u0004דברי \u0003שמואל,\u0004 מעתה \u0003יאמרו\u0004 אנשים בתמיהה: \u0003שתי נשים\u0004 הגרות \u0003בחצר אחת\u0004 שקיבלו גיטיהן באותו זמן, וגט אחד נכתב מוקדם, והשני נכתב מאוחר יותר, \u0003זו אסורה\u0004 עדיין (כי טרם עברו שלושה חודשים מזמן כתיבת גיטה) \u0003וזו\u0004 כבר \u0003מותרת!? אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 אין זו קושיה, כי \u0003זו זמן גיטה מוכיח עליה, וזו זמן גיטה מוכיח עליה.\u0004","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב, תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003שמואל.\u0004 ומפרטים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב\u0004 שמונים משעת הנתינה: \u0003השולח גט לאשתו ונשתהה\u0004 ה\u0003שליח בדרך שלשה חדשים, כשהגיע גט לידה\u0004 — \u0003צריכה להמתין שלשה חדשים\u0004 נוספים, \u0003ולגט ישן\u0004 (גט שנכתב בשעתו ואחר כך חזר האיש ובא על אשתו) \u0003אין חוששין, שהרי לא נתייחד עמה\u0004 במשך הזמן הזה.","ומאידך גיסא: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003שמואל\u0004 שמונים משעת כתיבה: \u0003המשליש\u0004 (מניח בידי שליש, ממונה) \u0003גט לאשתו, ואמר לו\u0004 לשליש: \u0003אל תתנהו לה אלא לאחר שלשה חדשים, משנתנו לה\u0004 — \u0003מותרת לינשא מיד\u0004 ואינה צריכה להמתין עוד שלושה חודשים, \u0003ולגט ישן אין חוששין, שהרי לא נתייחד עמה.\u0004","מסופר כי \u0003רב כהנא ורב פפי ורב אשי עבדי\u0004 \u0005[היו עושים]\u0006 הלכה למעשה שימתינו שלושה חודשים רק \u0003משעת\u0004 ה\u0003כתיבה,\u0004 ואילו \u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע עבדי\u0004 \u0005[היו עושים]\u0006 שימתינו שלושה חודשים \u0003משעת נתינה. והלכתא\u0004 \u0005[וההלכה]\u0006 בענין זה, שמונים את הזמן \u0003משעת כתיבה.\u0004","ומביאין מחלוקת נוספת של רב ושמואל בענייני שטרות. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו בשאלה: \u0003מאימתי\u0004 ההתחייבות הכלולה ב\u0003כתובה\u0004 לשלם לאשה סכום מסויים במקרה של גירושין או מות הבעל \u0003משמטת?\u0004 כלומר, ממתי חל עליה דין חוב העומד לפרעון, וכמו כל שאר החובות, שנת השמיטה משמטת גם אותו? לפי שכל זמן שאין השטר עומד לגבייה אין שביעית משמטת אותו.","\u0003רב אמר: משתפגום,\u0004 משעה שתיקח חלק מן הכתובה את שאר הכסף המגיע לה, \u0003ו\u0004את שאר הכסף המגיע לה \u0003תזקוף\u0004 כחוב בבית דין, ואז דינו של שטר הכתובה כשאר שטרי חוב, ושביעית משמטתו. \u0003ושמואל אמר:\u0004 אם \u0003פגמה\u0004 (לקחה מקצת) \u0003אף על פי שלא זקפה,\u0004 או ש\u0003זקפה\u0004 את כל הכלול בכתובה כחוב \u0003אף על פי שלא פגמה\u0004 — נעשה בכך כחוב ומשמטתו שביעית.","ואף במחלוקת זו \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב,\u0004 ו\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003שמואל. תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב: מאימתי כתובה משמטת? - משתפגום ותזקוף.\u0004 אבל אם \u0003פגמה ולא זקפה,\u0004 או \u0003זקפה ולא פגמה\u0004 — \u0003אינה משמטת, עד שתפגום ותזקוף.\u0004","וכן \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003שמואל: אונס,\u0004 כלומר, הכסף שמשלם האונס (קנס ושאר נזיקין), \u0003וקנס\u0004 שמשלם המוציא שם רע על אשתו, \u0003ופיתוי\u0004 (הקנס שמשלם המפתה), \u0003וכתובת אשה, שזקפן במלוה\u0004 — \u0003משמטין\u0004 בשביעית, \u0003ואם לאו\u0004 \u0005[לא]\u0006 זקפם במילווה — \u0003אין משמטין. מאימתי נזקפים במלוה,\u0004 מתי נחשבים כענין של הלוואה? — \u0003משעת העמדה בדין,\u0004 שברגע שעמד הנתבע לדין ופסקו בית דין שצריך לשלם, הרי זה נעשה כחוב.","ועוד בענייני כתובה, \u0003אמר שמואל: כתובה כמעשה בית דין דמיא\u0004 \u0005[\u0006היא \u0005נחשבת],\u0006 \u0003מה\u0004 כל \u0003מעשה בית דין נכתבין ביום ו\u0004יכולים שיהיו \u0003נחתמין\u0004 גם \u0003בלילה\u0004 שלאחריו, ואין מקום לחשש שאין זה אותו תאריך, \u0003אף כתובה נכתבת ביום ונחתמת בלילה.\u0004 מסופר: \u0003כתובתיה\u0004 \u0005[כתובתו]\u0006 של \u0003ר' חייא בר רב איכתוב\u0004 \u0005[נכתבה]\u0006 \u0003ביום ואיחתום\u0004 \u0005[ונחתמה]\u0006 \u0003בלילה, הוה\u0004 \u0005[היה]\u0006 \u0003רב התם\u0004 \u0005[שם]\u0006 \u0003ולא אמר להו\u0004 \u0005[להם]\u0006 \u0003ולא מידי\u0004 \u0005[דבר,\u0006 כלום\u0005].\u0006","ושואלים: \u0003לימא\u0004 \u0005[האם לומר,\u0006 אפשר להסיק], ש\u0003כשמואל סבירא ליה\u0004 \u0005[סבור הוא]\u0006 בענין זה? ודוחים: מכאן אין להוכיח, כי \u0003עסוקין באותו ענין\u0004 של הכתובה \u0003הוו\u0004 \u0005[היו]\u0006 עד שעת החתימה בלילה, ובמקרה זה הכל מודים. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמר ר' אלעזר בר ר' צדוק: לא שנו\u0004 ששטר הנכתב ביום ונחתם בלילה פסול \u0003אלא כשאין עסוקין\u0004 העדים \u0003באותו ענין אבל\u0004 אם \u0003עסוקין\u0004 הם \u0003באותו ענין\u0004 עד הלילה — \u0003כשר.\u0004","שנינו במשנה שגט שנכתב ביום ונחתם בלילה — \u0003ר' שמעון מכשיר. אמר רבא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' שמעון\u0004 שמכשיר? \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003כיון שנתן\u0004 הבעל \u0003עיניו לגרשה, שוב אין לו פירות,\u0004 ואין הוכחה ברורה יותר שנתן עיניו לגרשה מזה שכותב לה גט. ולשיטתו עולה כי לא זמן החתימה הוא הקובע, אלא זמן כתיבת הגט, ולכן גם אם נחתם לאחר מכן, לא יגרום הדבר נזק שלא כדין ללקוחות, כי ממילא זכות הבעל לפירות כבר פקעה.","\u0003אמר ריש לקיש: לא הכשיר ר' שמעון אלא לאלתר,\u0004 שחתמו את הגט בלילה שלאחר תאריך כתיבתו, \u0003אבל מכאן ועד עשרה ימים\u0004 — \u0003לא\u0004 התיר, ומדוע?"],["\u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא פייס\u0004 את אשתו בינתיים ובא עליה, ונמצא הגט גט ישן. \u0003ור' יוחנן אמר: אפילו מכאן ועד עשרה ימים\u0004 הכשיר ר' שמעון, ומדוע אין מקום לחשש פיוס? — כי \u0003אם איתא\u0004 \u0005[יש,\u0006 קרה\u0005]\u0006 הדבר ש\u0003פייס, קלא אית ליה למילתא\u0004 \u0005[קול,\u0006 פירסום, \u0005יש לו לדבר\u0006 זה\u0005]\u0006 והיו הכל יודעים זאת.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה הבאה: \u0003אמר\u0004 הבעל \u0003לעשרה\u0004 אנשים \u0003\"כתבו גט לאשתי\",\u0004 \u0003אמר ר' יוחנן:\u0004 כוונתו שכולם חותמים בגט, \u0003שנים\u0004 מהם חתומים בו \u0003משום עדים\u0004 שתפקידם הוא להעיד על הדבר, \u0003וכולם\u0004 (השאר), אינם חתומים בגט אלא \u0003משום תנאי\u0004 שהרי תלה בכך את הגט, ובלי זה לא יהא זה גט, אך לא התכוון שכולם יהיו עדים ממש. \u0003וריש לקיש אמר: כולם משום עדים.\u0004","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003לא אמר להו\u0004 \u0005[להם]:\u0006 \u0003\"כולכם\u0004 כתבו גט לאשתי \u0003\"\u0004— \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003אמר לעשרה: \"כתבו גט לאשתי\"\u0004 — \u0003אחד כותב ושנים חותמין,\u0004 ואין צורך שיחתמו כולם! \u0003אלא\u0004 מדובר ש\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003\"כולכם\",\u0004 ועל כך שנינו במשנה להלן שאחד כותב וכולם חותמים.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם\u0006 הלכה למעשה\u0005]\u0006 בין ר' יוחנן וריש לקיש אם השאר חתומים בגט משום עדים או משום תנאי? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 במקרה \u0003דחתום בי תרי מינייהו ביומיה\u0004 \u0005[שחתמו שניים מהם בו ביום]\u0006 \u0003ואינך\u0004 \u0005[והאחרים]\u0006 \u0003מכאן ועד עשרה ימים\u0004 ולא ביום הכתיבה; \u0003מאן דאמר\u0004 \u0005[\u0006לדעת \u0005מי שאומר]\u0006 שחתימת האחרים היא \u0003משום תנאי\u0004 — הגט \u0003כשר,\u0004 שהרי יש חתימה של שני עדים על הגט ביום הכתיבה ואילו התנאי גם הוא התקיים. \u0003ומאן דאמר\u0004 \u0005[ו\u0006לדעת \u0005מי שאומר]\u0006 \u0003משום עדים\u0004 — \u0003פסול,\u0004 מפני שלדעתו התכוון הבעל שגט זה ייחתם בעשרה עדים דווקא, וכיון שלא כולם חתמו בזמן הראוי — בטל הגט.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 יש ביניהם הבדל אחר: \u0003כגון שנמצא אחד מהם,\u0004 מן העשרה הללו \u0003קרוב, או פסול\u0004 לעדות מטעם אחר, \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שחתימת האחרים היא \u0003משום תנאי\u0004 — \u0003כשר,\u0004 שהרי חתימתו של הקרוב או הפסול אינה עדות אלא כדי לקיים את התנאי, ויש שני עדים כשרים חתומים על הגט. \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהוא \u0003משום עדים\u0004 — \u0003פסול\u0004 כדין כל כת עדים שנמצא אחד מהם קרוב או פסול.","ומוסיפים: אף לדעת האומר ששאר העדים הם משום תנאי, \u0003אי חתום\u0004 \u0005[אם חתם]\u0006 \u0003בתחילה\u0004 של גט כזה \u0003קרוב או פסול, אמרי לה\u0004 \u0005[יש אומרים]\u0006 שהגט \u0003כשר, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהוא \u0003פסול.\u0004 טעמם של \u0003אמרי לה\u0004 \u0005[יש אומרים]\u0006 שהוא \u0003כשר\u0004 — שכן \u0003תנאי הוא.\u0004 שכיון שעשרה אלה לא נועדו לשמש עדים אלא למלא את התנאי, אין הבדל אם חתמו בתחילה או בסוף. ואילו טעמם של \u0003אמרי לה\u0004 \u0005[יש אומרים]\u0006 שהוא \u0003פסול\u0004 — משום החשש שמא \u0003אתי לאיחלופי\u0004 \u0005[יבואו להחליף\u0006 אותו\u0005]\u0006 \u0003בשטרות דעלמא\u0004 \u0005[סתם]\u0006 ויבואו להכשיר עדים פסולים.","מסופר: \u0003ההוא\u0004 \u0005[אדם אחד]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003לעשרה \"כתבו גט לאשתי\", חתום בי תרי מינייהו ביומיה\u0004 \u0005[חתמו שניים מהם בו ביום]\u0006 \u0003ואינך\u0004 \u0005[והאחרים]\u0006 \u0003מכאן ועד עשרה ימים, אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' יהושע בן לוי,\u0004 לשאול מה דינו של גט זה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יהושע בן לוי:"],["\u0003כדאי\u0004 (ראוי) \u0003הוא ר' שמעון\u0004 שהכשיר גט שנכתב ביום ונחתם בלילה, \u0003לסמוך עליו בשעת הדחק.\u0004 וכיון שכבר נכתב הגט הזה וניתן — אין לבטלו.","ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ריש לקיש: לא הכשיר ר' שמעון אלא לאלתר\u0004 \u0005[מיד],\u0006 \u0003אבל מכאן ועד עשרה ימים, לא!\u0004 ומשיבים: \u0003בההיא\u0004 \u0005[באותה]\u0006 בעיה של הזמן, \u0003כ\u0004שיטת \u0003ר' יוחנן סבירא ליה\u0004 \u0005[סבור הוא]\u0006 ר' יהושע בן לוי.","ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: שנים משום עדים, וכולן,\u0004 האחרים, \u0003משום תנאי,\u0004 ואם כן אינו סובר כר' יוחנן, שהרי ברור שהוא חושש משום העדים האחרים! ומשיבים: \u0003בההיא\u0004 \u0005[בזו],\u0006 בענין הטעם לעשרה, \u0003כריש לקיש סבירא ליה\u0004 \u0005[סבור הוא]\u0006 שכולם הם משום עדות.","\u0003בכל\u0004 חומר שאפשר לכתוב בו \u0003כותבים\u0004 את הגט — \u0003בדיו, בסם, בסיקרא, ובקומוס, ובקנקנתום, ובכל דבר\u0004 אחר \u0003שהוא\u0004 עושה כתב \u0003של קיימא\u0004 (קיום). אבל \u0003אין כותבין לא במשקין\u0004 (נוזלים) שונים \u0003ולא במי פירות, ולא בכל דבר\u0004 \u0003ש\u0004הכתב שלו \u0003אינו מתקיים.\u0004","וכן הוא לגבי גוף שטר הגט; \u0003על הכל כותבין,\u0004 אפילו \u0003על העלה של זית, ועל הקרן של פרה.\u0004 \u0003ו\u0004אם נכתב הגט על קרן של פרה — \u0003נותן לה את הפרה\u0004 כולה. וכן יכול לכתוב את הגט \u0003על יד של עבד ונותן לה את העבד. ר' יוסי הגלילי אומר: אין כותבין\u0004 גט \u0003לא על דבר שיש בו רוח חיים, ולא על האוכלים.\u0004","תחילה מפרשים את המילים הנזכרות במשנה, ומסבירים: \u0003דיו\u0004 — הוא מה שקרוי בארמית \u0003דיותא. סם\u0004 — הוא \u0003סמא. סיקרא\u0004 — \u0003אמר רבה בר בר חנה: סקרתא שמה\u0004 בארמית. \u0003קומוס\u0004 — הוא הנקרא בארמית \u0003קומא. קנקנתום\u0004 — \u0003אמר רבה בר בר חנה אמר שמואל:\u0004 זהו \u0003חרתא דאושכפי\u0004 \u0005[שחור ש\u0006משתמשים בו \u0005הסנדלרים].\u0006","שנינו במשנה שניתן לכתוב את הגט \u0003בכל דבר שהוא מתקיים וכו'.\u0004 ושואלים: \u0003לאתויי מאי\u0004 \u0005[להביא,\u0006 לרבות את \u0005מה\u0006 הוא בא\u0005]?\u0006 ומשיבים: \u0003לאתויי הא דתני\u0004 \u0005[להביא,\u0006 לרבות את \u0005זו ששנה]\u0006 \u0003ר' חנינא: כתבו במי טריא\u0004 \u0005[מים ששורים בהן פירות]\u0006 או ב\u0003אפצא\u0004 \u0005[עפצים]\u0006 — הרי זה \u0003כשר,\u0004 כיון שהכתב מתקיים. \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא: כתבו באבר\u0004 (עופרת), \u0003בשחור\u0004 (פחמים), \u0003ובשיחור\u0004 (קנקנתום) — הרי זה \u0003כשר.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו בשאלה: \u0003המעביר\u0004 (חוזר וכותב) \u0003דיו על גבי\u0004 דבר הכתוב ב\u0003סיקרא,\u0004 ועושה זאת \u0003ב\u0004יום ה\u0003שבת, ר' יוחנן וריש לקיש דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 ולא נחלקו שבמקרה זה \u0003חייב\u0004 על כך \u0003שתים: אחת משום כותב,\u0004 שהוא כותב עכשיו אותיות בדיו, \u0003ואחת משום מוחק,\u0004 שמוחק על ידי כך את האותיות של הסיקרא. וכן לא נחלקו ביניהם אם כתב \u0003דיו על גבי דיו,\u0004 או \u0003סיקרא על גבי סיקרא,\u0004 שלדעת הכל הרי זה \u0003פטור,\u0004 שהרי לא שינה דבר בכתיבתו זו. אבל אם כתב ב\u0003סיקרא על גבי דיו, אמרי לה\u0004 \u0005[יש אומרים]:\u0006 \u0003חייב, ואמרי לה\u0004 \u0005[ויש אומרים]:\u0006 \u0003פטור.\u0004","ומסבירים את השיטות: \u0003אמרי לה\u0004 \u0005[יש אומרים]\u0006 ש\u0003חייב\u0004 משום שמלאכת \u0003מוחק הוא,\u0004 שמוחק את הכתב הראשון שהיה משובח יותר. \u0003אמרי לה\u0004 \u0005[יש אומרים]\u0006 ש\u0003פטור\u0004 משום ש\u0003מקלקל הוא\u0004 ומקלקל פטור במלאכת שבת.","דבר זה נאמר לענין הלכות שבת, אולם \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ריש לקיש מר' יוחנן: עדים שאין יודעים לחתום, מהו שיכתבו להם\u0004 אחרים את שמותיהם \u0003בסיקרא, ו\u0004הם \u0003יחתמו\u0004 עליהם בדיו? והשאלה היא: האם \u0003כתב עליון,\u0004 כתב שנכתב באופן זה על גבי כתב אחר, נחשב הוא ל\u0003כתב, או\u0004 ש\u0003אינו כתב? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אינו כתב\u0004 ולכן אין עושים כן לעדים שאין יודעים לחתום.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש: \u0003והלא לימדתנו רבינו,\u0004 כי \u0003כתב עליון\u0004 נחשב \u0003כתב לענין\u0004 מלאכת \u0003שבת! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003וכי מפני שאנו מדמין\u0004 הלכות גיטין להלכות שבת \u0003נעשה מעשה\u0004 ונורה לכתחילה לכתוב גט כזה? אין בכוחנו לסמוך על כך.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו בשאלה הבאה: \u0003עדים שאין יודעים לחתום\u0004 מה עושים בהם? \u0003רב אמר: מקרעין להם נייר חלק,\u0004 מניחים על המסמך נייר חלק וקורעים, חותכים, את שמותיהם בתוך הנייר, \u0003ו\u0004העדים \u0003ממלאים את הקרעים דיו\u0004 ועל ידי כך נכתבים שמותיהם במסמך, \u0003ושמואל אמר: באבר\u0004 (עופרת) כותבים להם תחילה בגוף המסמך, והעדים כותבים על הסימון שנעשה עבורם.","ותוהים: \u0003באבר סלקא דעתך\u0004 \u0005[עולה על דעתך\u0006 לומר\u0005]?\u0006 \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' חייא: כתבו באבר, בשחור, ובשיחור\u0004 — \u0003כשר!\u0004 אם כן, כתיבה מעולה היא זו, וכפי שאמרנו אם כותבים על גבי כתב אחר אין הכתיבה השנייה נחשבת כתיבה גמורה לענין גיטין! ומשיבים: זה \u0003לא קשיא\u0004 \u0005[קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שהתיר שמואל לעדים לחתום על גבי סימון שנעשה להם — הרי זה כאשר נעשה הסימון \u0003באברא\u0004 \u0005[בעופרת]\u0006 עצמה ואין זה עצמו נחשב ככתב, \u0003הא\u0004 \u0005[זה]\u0006 שאמר ר' חייא שכשר לכתיבת הגט — הרי זה \u0003במיא דאברא\u0004 \u0005[במים של עופרת].\u0006","\u0003ר' אבהו אמר:\u0004 אפשר לכתוב לעדים הללו תחילה \u0003במי מילין\u0004 \u0005[במים של עפצים].\u0006 ומקשים: \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' חנינא\u0004 שגט ש\u0003כתבו במי טריא ואפצא\u0004 — \u0003כשר,\u0004 ואם כן שוב כל כתיבה נוספת מעליו לא תיחשב ככתיבה גמורה!","ומשיבים: זה \u0003לא קשיא\u0004 \u0005[קשה]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שהתיר ר' אבהו לעדים לחתום על גביו, הרי זה באופן \u0003דאפיץ\u0004 \u0005[ש\u0006היה הקלף \u0005מעובד בעפצים],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שכשר הוא עצמו לכתיבת הגט, הרי זה באופן ש\u0003לא אפיץ\u0004 \u0005[\u0006היה \u0005מעובד\u0006 הקלף \u0005בעפצים],\u0006 והטעם שהתיר ר' אבהו לעדים לחתום על גבי מי מילין בקלף מעובד הוא, לפי \u0003שאין מי מילין\u0004 מתקיימים \u0003על גבי מי מילין\u0004 שקדמו להם בעיבוד הקלף, ואין חתימת העדים נחשבת כבאה על גבי כתב.","\u0003רב פפא אמר:\u0004 כותבים להם תחילה את שמותיהם \u0003ברוק\u0004 והם כותבים עליו בדיו את שמותיהם. \u0003וכן אורי ליה\u0004 \u0005[הורה לו]\u0006 \u0003רב פפא לפפא תוראה\u0004 \u0005[רועה השוורים]\u0006 שלא ידע לכתוב, שיעשו לו כך \u0003ברוק.\u0004 ומעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 לגבי חתימה התקינו דווקא \u0003בגיטין,\u0004 משום שפעמים לא ימצאו עדים ותישאר האישה עגונה, \u0003אבל בשטרות\u0004 של ממון — \u0003לא\u0004 תיקנו כן,","אלא יחפשו עדים היודעים לחתום. וכפי שמסופר, \u0003דההוא דעבד עובדא\u0004 \u0005[שאדם אחד שעשה מעשה]\u0006 כעין זה \u0003בשאר שטרות\u0004 שאינם גיטין, \u0003ונגדיה\u0004 \u0005[והלקה,\u0006 ציווה להלקותו\u0005]\u0006 \u0003רב כהנא,\u0004 בשל כך."],["\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב: עדים שאין יודעין לחתום, מקרעין להן נייר חלק ו\u0004הם \u0003ממלאים את הקרעים דיו.\u0004","\u0003אמר רבן שמעון בן גמליאל: במה דברים אמורים\u0004 — \u0003בגיטי נשים, אבל בשחרורי עבדים ושאר כל השטרות, אם יודעין\u0004 העדים \u0003לקרות\u0004 (לקרוא) \u0003ולחתום\u0004 — \u0003חותמין, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אין חותמין.\u0004","ותוהים: \u0003קרייה מאן דכר\u0004 \u0005[קריאה מי הזכיר]\u0006 את \u0003שמה,\u0004 מדוע בא רבן שמעון בן גמליאל והזכיר ענין של קריאה, כאשר דנו קודם רק במי שאינו יודע לחתום? ומשיבים: \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 הברייתא \u0005וכך\u0006 היא \u0005שנויה]:\u0006 \u0003עדים שאין יודעין לקרות\u0004 — \u0003קורין\u0004 (קוראים) \u0003לפניהם וחותמים, ושאין יודעין לחתום\u0004 — מקרעים להם נייר והם חותמים. על כך \u0003אמר רבן שמעון בן גמליאל: במה דברים אמורים\u0004 — \u0003בגיטי נשים, אבל\u0004 בשטרי \u0003שחרורי עבדים ושאר כל השטרות, אם יודעין\u0004 גם \u0003לקרות ו\u0004גם \u0003לחתום\u0004 — \u0003חותמין, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אין חותמין,\u0004 ואין סומכים על מה שקוראים לפניהם.","\u0003אמר ר' אלעזר: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רבן שמעון בן גמליאל\u0004 שהתיר לעשות כן בגיטין? — שהוא סבור שיש להקל בגיטין כדי \u0003שלא יהו בנות ישראל עגונות,\u0004 שאם לא נקל עליהן באופן עריכת הגט וחתימתו, הרי שבמקרה שהבעל רוצה לצאת לדרך רחוקה ורוצה לתת גט לאשתו ואין במקומם עדים היודעים גם לקרוא וגם לחתום, ייצא הבעל דרכו בלא לתת לה גט ונמצאו הן עגונות.","\u0003אמר רבא: הלכה כרבן שמעון בן גמליאל. ורב גמדא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא אמר: אין הלכה\u0004 כרבן שמעון בן גמליאל. ושואלים: \u0003ואלא כמאן\u0004 \u0005[כמי]\u0006 תהיה ההלכה — \u0003כרבנן\u0004 \u0005[כחכמים]\u0006 ובכל השטרות מותר לעשות זאת?","\u0003והא ההוא דעבד עובדא\u0004 \u0005[והרי\u0006 היה \u0005אדם אחד שעשה מעשה\u0006 שכזה\u0005]\u0006 \u0003בשאר שטרות,\u0004 שקרע את הנייר עבור עדים שאינם יודעים לחתום, \u0003ונגדיה\u0004 \u0005[והלקה אותו]\u0006 \u0003רב כהנא\u0004 על כך! ומתרצים: \u0003תרגמא אקריאה\u0004 \u0005[תרגם,\u0006 הסבר, דברי רב גמדא רק \u0005לגבי קריאה]\u0006 שלענין ידיעת קריאה אין הלכה כרבן שמעון בן גמליאל אלא כחכמים, וסומכים אף בשאר שטרות על זה שמקריאים את השטר בפני העד.","ומסופר כי \u0003רב יהודה\u0004 בזיקנתו היה מתקשה לראות, והיה מתאמץ לקרוא ו\u0003מיצטער\u0004 עד שהיה \u0003קרי וחתים\u0004 \u0005[קורא\u0006 את השטר \u0005וחותם\u0006 עליו כעד, או כדיין\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003עולא: לא צריכת\u0004 \u0005[צריך אתה]\u0006 לכך, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003ר' אלעזר מרא\u0004 \u0005[אדון,\u0006 המורה] של \u0003ארץ ישראל קרו קמיה וחתים\u0004 \u0005[\u0006והיו \u0005קוראים לפניו ו\u0006הוא \u0005חותם]\u0006 ואם כן, יכול אף אתה לנהוג כמותו. \u0003ורב נחמן קרו קמיה ספרי דייני וחתים\u0004 \u0005[היו קוראים לפניו סופרי הדיינים\u0006 את השטר \u0005והיה חותם].\u0006 ומעירים: \u0003ודווקא רב נחמן וספרי דייני\u0004 \u0005[וסופרי הדיינים],\u0006 \u0003דאית להו אימתא\u0004 \u0005[שיש להם אימה]\u0006 מלפניו, שהיה אדם גדול ודיין והם היו כפופים לו, ולכן אין לחשוש שמא לא קראו כדין, \u0003אבל\u0004 אם היה \u0003רב נחמן וספרי אחריני\u0004 \u0005[וסופרים אחרים],\u0006 או \u0003ספרי דייני ואיניש אחרינא\u0004 \u0005[סופרי הדיינים ואדם אחר]\u0006 — \u0003לא,\u0004 ואי אפשר לסמוך על כך.","ועוד, בענין הסתמכות על קריאה של אדם אחר בשטר, מסופר: \u0003רב פפא כי הוה אתי לקמיה שטרא פרסאה דעביד\u0004 \u0005[כאשר היה בא לפניו שטר פרסי שהיה עשוי]\u0006 \u0003בערכאות של כותים,\u0004 והוא לא ידע לקרות פרסית, \u0003מקרי להו\u0004 \u0005[היה נותן לקרוא]\u0006 \u0003לשני כותים\u0004 את השטר \u0003זה שלא בפני זה, ב\u0004אופן שיהיה כל אחד מהם \u0003מסיח לפי תומו,\u0004 לא בתורת עדות, אלא שהיה מבקש ממנו כאילו לקרוא סתם. \u0003ו\u0004כשהיה מתברר מה כתוב בשטר \u0003מגבי ביה ממשעבדי\u0004 \u0005[היה גובה בו\u0006 אפילו \u0005מ\u0006נכסים \u0005משועבדים],\u0006 שסבר שלדיני ממונות שטר כזה נחשב לשטר גמור.","\u0003אמר רב אשי: אמר לי רב הונא בר נתן, הכי\u0004 \u0005[כך]\u0006 \u0003אמר אמימר: האי שטרא פרסאה\u0004 \u0005[שטר פרסי זה]\u0006 \u0003דחתימי עליה סהדי ישראל\u0004 \u0005[שחתומים עליו עדים יהודים],\u0006 \u0003מגבינן ביה ממשעבדי\u0004 \u0005[גובים אנו בו\u0006 אפילו \u0005מ\u0006נכסים \u0005משועבדים].\u0006","ושואלים: \u0003והא לא ידעי למיקרי\u0004 \u0005[והרי אין\u0006 העדים \u0005יודעים לקרוא]\u0006 את השטר! ומשיבים: מדובר פה \u0003בדידעי\u0004 \u0005[ב\u0006עדים \u0005שיודעים\u0006 לקרוא\u0005].\u0006 ושואלים עוד: \u0003והא בעינן\u0004 \u0005[והרי צריכים אנו]\u0006 שיהיה \u0003כתב שאינו יכול להזדייף, וליכא\u0004 \u0005[ואין כאן]\u0006 בשטר זה, כיון שאין הפרסים מקפידים על כך! אומרים: מדובר פה \u0003בדאפיצן\u0004 \u0005[ב\u0006מקרה \u0005ש\u0006היו הקלפים של השטרות \u0005עשויים בעפצים]\u0006 ואז אי אפשר לזייף את הכתב. ומקשים עוד: \u0003והא בעינן\u0004 \u0005[והרי צריכים אנו]\u0006 בכתיבת שטרות \u0003לחזור מענינו של שטר בשיטה\u0004 (שורה) \u0003אחרונה\u0004 של השטר, \u0003וליכא\u0004 \u0005[ואין כאן]\u0006 דבר זה בדרך כלל בשטרות הפרסיים! ומשיבים: מדובר פה \u0003בדמהדר\u0004 \u0005[ב\u0006מקרה \u0005שחזר]\u0006 על עניינו של שטר בשורה אחרונה.","ושואלים: \u0003ו\u0004אם כל אלה היו בו \u0003אלא מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בכך — ששטר שנכתב כדינו ולא היה בו דבר אלא שנכתב ב\u0003כל לשון\u0004 — \u0003כשר?\u0004 הלא כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 דבר זה: \u0003גט שכתבו\u0004 (הכתב שלו) \u0003עברית ועדיו\u0004 חתומים ב\u0003יונית,\u0004 או היה כתבו \u0003יונית ועדיו\u0004 חתומים ב\u0003עברית\u0004 — \u0003כשר!\u0004","ודוחים: משם אין ראיה ברורה, שכן \u0003אי מההיא הוה אמינא\u0004 \u0005[אם מאותה\u0006 ברייתא, \u0005הייתי אומר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003בגיטין,\u0004 שהקלו בהם הרבה כדי שלא תישאר האישה עגונה, \u0003אבל בשאר שטרות\u0004 — \u0003לא,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 אמימר שאף בשאר שטרות הרי זה כשר.","\u0003אמר שמואל: נתן לה\u0004 הבעל לאשתו \u0003נייר חלק ואמר לה: \"הרי זה גיטיך\"\u0004 — \u0003מגורשת\u0004 בו. ומדוע? \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא במי מילין כתבו\u0004 והכתב נבלע בנייר ואינו נראה בו עתה, אבל היה כתוב בו גט כהלכתו.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא: האומר לאישה \u0003\"הרי זה גיטך\",\u0004 \u0003ו\u0004לא פתחתו לראותו אלא \u0003נטלתו וזרקתו לים, או לאור\u0004 (אש), \u0003או לכל דבר האבד, וחזר\u0004 הבעל \u0003ואמר:\u0004 לא היה זה גט, אלא \u0003שטר פסים\u0004 (שטר שלא נועד אלא למראית עין בלבד, שייחשב המחזיק בו כעשיר) \u0003הוא,\u0004 או \u0003שטר אמנה\u0004 (בטחון) \u0003הוא\u0004 — \u0003מגורשת, ולא כל הימנו\u0004 (אין בכוחו) \u0003לאוסרה\u0004 על אחרים כאשת איש, כשאומר שלא היה זה גט ועדיין היא נשואה לו.","ומדקדקים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 \u0003דאיכא\u0004 \u0005[שיש\u0006 בו], בגט הזה \u0003כתב, הא ליכא\u0004 \u0005[הרי\u0006 אם \u0005אין\u0006 בו\u0005]\u0006 \u0003כתב\u0004 — \u0003לא,\u0004 ואין אומרים שהיה זה גט שנכתב במי מילין! ומשיבים: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003שמואל\u0004 שמגורשת באותו נייר חלק, הרי זה במקרה \u0003דבדקינן ליה במיא דנרא\u0004 \u0005[שבודקים אנו אותו,\u0006 את הנייר \u0005במי צבע מיוחדים],\u0006 \u0003אי פליט\u0004 \u0005[אם פולט]\u0006 את האותיות והן נראות — \u0003פליט\u0004 \u0005[פולט]\u0006 הוא והרי זה גט, \u0003ואי לא פליט\u0004 \u0005[ואם אינו פולט]\u0006 — \u0003לאו\u0004 \u0005[לא]\u0006 \u0003כלום הוא\u0004 ואין היא מגורשת.","ושואלים: \u0003וכי פליט מאי הוי\u0004 \u0005[ואם\u0006 הוא \u0005פולט מה בכך]?\u0006 הרי ייתכן כי רק \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003הוא דפליט\u0004 \u0005[שפולט]\u0006 ונראות בו האותיות, אבל מתחילתו לא היה כתוב בכתב הראוי להיקרא כלל! ואומרים: \u0003שמואל נמי\u0004 \u0005[גם כן]\u0006 \u0003\"חיישינן\" קאמר\u0004 \u0005[\"חוששים אנו\", אמר],\u0006 ולא שאנו סומכים על כך לומר שזהו גט גמור, אלא אנו חוששים שמא מתחילה נכתב כראוי ואחר כך נבלעו האותיות, ומפני כן תהא האשה כספק מגורשת.","\u0003אמר רבינא: אמר לי אמימר, הכי\u0004 \u0005[כך]\u0006 \u0003אמר מרימר משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב דימי: הני בי תרי דיהיב גיטא קמייהו\u0004 \u0005[שניים\u0006 שהיו עדים \u0005שניתן גט לפניהם],\u0006 \u0003צריכי למיקרייה\u0004 \u0005[צריכים לקרוא אותו],\u0006 את הגט. \u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא: האומר לאישה \u0003\"הרי זה גיטך\", ונטלתו וזרקתו לים, או לאור, או לכל דבר האבד, וחזר ואמר:\"שטר פסים הוא\",\u0004 או שאמר \u0003\"שטר אמנה הוא\"\u0004 — \u0003מגורשת, ולא כל הימנו לאוסרה. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003צריכי למיקרייה\u0004 \u0005[צריכים\u0006 העדים \u0005לקרוא אותו],\u0006 את הגט, אם כן \u0003בתר דקריוה\u0004 \u0005[אחרי שקראו אותו]\u0006 \u0003מי מצי אמר לה הכי\u0004 \u0005[האם\u0006 הבעל \u0005יכול לומר לה כך]?\u0006","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה],\u0006 אלא לאופן \u0003דבתר דקריוה עייליה לבי ידיה ואפקיה\u0004 \u0005[שאחר שקראוהו הכניסו\u0006 הבעל \u0005לחיקו,\u0006 את הגט הזה וחזר \u0005והוציא אותו]\u0006 ונתנו לאשה; \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003חלופי חלפיה\u0004 \u0005[החליף אותו]\u0006 בשטר אחר, ומה שנתן לאשה לא היה שטר גט אלא שטר פסים או שטר אמנה כטענתו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין אנו חוששים לחילוף.","מסופר: \u0003ההוא גברא דזרק לה גיטא לדביתהו לביני דני\u0004 \u0005[אדם אחד שזרק לה גט ל\u0006חצר \u0005אשתו לבין החביות],\u0006 ולבסוף \u0003אשתכח מזוזתא\u0004 \u0005[נמצאה\u0006 שם \u0005מזוזה],\u0006 והשאלה היתה: האם יש לחשוש שזרק לה גט והגט אבד, והמזוזה הגיעה לשם בדרך אחרת, או שמא מזוזה הוא שזרק לה? \u0003אמר רב נחמן: מזוזתא ביני דני לא שכיחא\u0004 \u0005[מזוזה בין החביות אינה מצוייה]\u0006 ומן הסתם זה היה הדבר שזרק, ולא גט.","ומעירים: \u0003והני מילי דאשתכח חדא\u0004 \u0005[ודברים אלה\u0006 אמורים \u0005שנמצאה\u0006 רק מזוזה \u0005אחת],\u0006 \u0003אבל\u0004 אם נמצאו שם \u0003שנים שלשה\u0004 קלפים של מזוזות, אומרים אנו: \u0003מדהא הואי\u0004 \u0005[מכיון שזו\u0006 האחרת \u0005היתה]\u0006 — \u0003הא נמי הואי\u0004 \u0005[זו גם כן היתה]\u0006 שם לפני שזרק את הגט, \u0003ו\u0004אילו \u0003גיטא\u0004 \u0005[הגט]\u0006 שלא מצאוהו — \u0003אימור\u0004 \u0005[אמור]\u0006 שה\u0003עכברים שקלוה\u0004 \u0005[לקחו אותו],\u0006 ולכן אינו מצוי כעת אבל האשה כבר התגרשה בכך שהגט ניתן בחצירה.","מסופר: \u0003ההוא גברא דעל לבי כנישתא\u0004 \u0005[אדם אחד שנכנם לבית הכנסת],\u0006 \u0003שקל\u0004 \u0005[לקח]\u0006 \u0003ספר תורה יהיב\u0004 \u0005[נתן]\u0006 \u0003לה לדביתהו\u0004 \u0005[לאשתו],\u0006 \u0003ואמר לה: הא\u0004 \u0005[זה]\u0006 \u0003גיטך. אמר רב יוסף: למאי ליחוש לה\u0004 \u0005[למה נחשוש\u0006 כאן\u0005]\u0006 לומר שאשה זו מגורשת? \u0003אי\u0004 \u0005[אם]\u0006 תאמר שנחשוש \u0003משום מי מילין,\u0004 שמא כתב לה גט על גבי הגוויל של ספר התורה הזה מבחוץ במי מילין ולכן אין הכתב נראה — הלא \u0003אין מי מילין על גבי מי מילין,\u0004 וכיון שכבר יש עיבוד בעפצים של הגווילים עצמם, לא ייתכן שיכתוב עוד משהו בעפצים על גביו."],["\u0003אי\u0004 \u0005[אם]\u0006 \u0003משום כריתות דאית\u0004 \u0005[שיש]\u0006 \u0003בה\u0004 בתורה, שהרי כתובה בה הפרשה של \"וכתב לה ספר כריתות\", אולם גם זה אינו מועיל — שכן \u0003הא בעינא\u0004 \u0005[הרי צריכים אנו]\u0006 בדיני הגט \u0003\"וכתב לה\"\u0004 (דברים כד, א), כלומר, \u0003לשמה\u0004 של האשה המתגרשת, \u0003וליכא\u0004 \u0005[ואין]\u0006 דבר זה בספר תורה.","\u0003וכי תימא\u0004 \u0005[ואם תאמר],\u0006 \u0003ליחוש דילמא אקדים ויהב ליה זוזא לספרא מעיקרא\u0004 \u0005[נחשוש שמא הקדים ונתן לו זוז\u0006 כסף \u0005לסופר מתחילה]\u0006 כאשר כתב את הספר, ואמר לו לכתוב את פרשת כריתות שבספר לשם אשתו, אולם \u0003הא בעינן\u0004 \u0005[הרי צריכים אנו]\u0006 בדיני הגט שיהיו כתובים בו גם דברים אחרים, ואם אין אותם הדברים כתובים — הרי הגט פסול. ואפילו כתובים הם אלא ש\u0003שינה\u0004 את \u0003שמו ושמה, שם עירו ושם עירה\u0004 — הרי זה גט פסול, הרי שכשרותו של הגט תלויה בכך \u0003ו\u0004הרי \u0003ליכא\u0004 \u0005[אין]\u0006 בכל בספר תורה כל שם.","ושואלים: אם כן, \u0003ורב יוסף מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בדבריו? הרי פשוט שאי אפשר לחשוש שספר תורה ישמש כגט! ואומרים: השמיע לנו \u0003שאין מי מילין על גבי מי מילין.\u0004 וזהו החידוש שבדבר, שאין חוששים כלל לכך.","\u0003אמר רב חסדא: גט שכתבו שלא לשמה והעביר עליו קולמוס,\u0004 שחזר וכתב על גבי אותם הדברים \u0003לשמה, באנו\u0004 בזה \u0003למחלוקת ר' יהודה ורבנן\u0004 \u0005[וחכמים].\u0006","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי שהיה\u0004 הסופר הכותב ספר תורה \u0003צריך לכתוב את השם\u0004 (שם הויה), אבל הוא טעה \u0003ונתכוין\u0004 לא \u0003לכתוב\u0004 שם הויה אלא את השם \u0003\"יהודה\",\u0004 \u0003ו\u0004אולם \u0003טעה\u0004 גם אז בכתיבה \u0003ולא הטיל בו דל\"ת,\u0004 ואם כן, נמצא שכתב שם הויה וכתבו במקום הראוי לו, אלא שכתב אותו שלא לשם כוונת כתיבת שם קודש, אלא כשם אדם — \u0003מעביר עליו קולמוס,\u0004 כלומר, כותב שוב על גבי הכתוב \u0003ומקדשו\u0004 בכוונה שהפעם הוא כותב את השם לשמו, אלו \u0003דברי ר' יהודה. וחכמים אומרים: אין השם מן המובחר\u0004 כשכותב אותו כך. ואם כן לדעת ר' יהודה גם גט שהעביר על הכתוב בו קולמוס לשמה כשר, ולדעת חכמים הוא פסול.","\u0003אמר רב אחא בר יעקב: דילמא\u0004 \u0005[שמא]\u0006 \u0003לא היא,\u0004 כלומר, שמא אין זה אותו עיקרון, שכן \u0003עד כאן לא\u0004 שמענו כי \u0003קאמרי רבנן התם\u0004 \u0005[אמרו חכמים שם]\u0006 בענין כתיבת השם שאין זה כשר, אלא משום \u0003דבעינא\u0004 \u0005[שצריכים אנו]\u0006 לקיים בדבר שבקדושה כגון זה — בכתיבת ספר תורה — \u0003\"זה אלי ואנוהו\"\u0004 (שמות טו, כ) \u0003וליכא\u0004 \u0005[ואין כאן],\u0006 שהרי בוודאי אין זה דבר נאה (\"אנוהו\") כשהוא חוזר וכותב את השם בפעם השניה לשמה, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 בגט — \u0003לא,\u0004 משום שבגט אין צורך בכתיבה שיש בה נוי, ושמא העברת קולמוס תועיל בגט גם לדעת חכמים.","\u0003אמר רב חסדא: יכילנא למיפסלינהו לכולי גיטי דעלמא\u0004 \u0005[יכול אני לפסול את כל הגיטין שבעולם],\u0006 שאם היו רוצים לעמוד ולדקדק בכמה דברים, הרי רוב הגיטין הכתובים אפשר היה לפסול אותם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: מאי טעמא\u0004 \u0005[מה הטעם],\u0006 משום מה היית יכול לפסול אותם? \u0003אילימא\u0004 \u0005[אם נאמר]\u0006 \u0003משום דכתיב\u0004 \u0005[שנאמר]\u0006 בתורה: \u0003\"וכתב\u0004 לה ספר כריתות\u0003\"\u0004 (דברים כד, א), \u0003והכא\u0004 \u0005[וכאן]\u0006 ברוב הגיטין שבעולם \u0003איהי קא כתבה ליה\u0004 \u0005[היא כותבת לו],\u0006 שכן המנהג הוא שהאשה היא זו שנותנת שכר לסופר לכתוב את הגט. אולם בכך אין קושי, \u0003ודילמא אקנויי אקנו ליה רבנן\u0004 \u0005[ושמא הקנו לו חכמים]\u0006 את הגט, למרות שלא הוא עצמו כתבו!","\u0003ואלא\u0004 תאמר שהוא \u0003משום דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ונתן\"\u0004 (שם), שיהא הדבר הניתן בעל ערך, \u0003והכא\u0004 \u0005[וכאן]\u0006 ברוב גיטין שבעולם \u0003לא יהיב\u0004 \u0005[נותן]\u0006 \u0003לה מידי\u0004 \u0005[דבר]\u0006 — גם על זה יש להעיר \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003נתינת גט\u0004 \u0003היא\u0004 הנתינה האמורה בתורה ולא נתינת דבר שיש לו ערך! \u0003תדע\u0004 שאין צורך בנתינה של דבר בעל ערך לצורך הגירושין, שכן \u0003שלחו מתם\u0004 \u0005[משם,\u0006 מארץ ישראל\u0005]:\u0006 גט ש\u0003כתבו על\u0004 דברים שהם \u0003איסורי הנאה\u0004 אף על פי שחומר הגט אסור בהנאה והוא חסר ערך ממוני כלשהו — מכל מקום הגט עצמו \u0003כשר.\u0004","\u0003גופא\u0004 \u0005[לגופה]\u0006 של ההלכה שהזכרנו, \u0003שלחו מתם\u0004 \u0005[משם,\u0006 מארץ ישראל\u0005]:\u0006 גט ש\u0003כתבו על איסורי הנאה\u0004 — \u0003כשר. אמר רב אשי: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 מעין הדברים הללו במשנה, שכותבים את הגט \u0003על העלה של זית,\u0004 והרי עלה של זית חסר כל ערך! משמע שאין צורך שהגט עצמו יהיה בעל ערך כלשהו, ואף איסורי הנאה אף שאין להם ערך כלל, ראויים שגט ייכתב עליהם. ודוחים: \u0003דילמא שאני\u0004 \u0005[שמא שונה]\u0006 \u0003עלה של זית,\u0004 משום \u0003דחזי לאיצטרופי\u0004 \u0005[ש\u0006הוא \u0005ראוי להצטרף],\u0006 שאמנם העלה הזה עצמו שווה פחות משווה פרוטה, אבל יש לו ערך כלשהו, שאם אוספים עלים רבים אפשר להשתמש בהם למטרה מסויימת ויש להם ערך, אבל איסורי הנאה הם חסרי ערך לחלוטין, אף בכמות רבה.","ובאותו ענין מביאים, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי אומר: כתבו על איסורי הנאה\u0004 — \u0003כשר. נפק\u0004 \u0005[יצא]\u0006 \u0003לוי, דרשה,\u0004 את ההלכה הזאת, \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבי ולא קלסוה\u0004 \u0005[שיבחו אותו],\u0006 דרש אותה אחר כך \u0003משמיה דרבים\u0004 \u0005[משם רבים]\u0006 כסתם הלכה, \u0003וקלסוה\u0004 \u0005[ושיבחו אותו].\u0006 ולמדים ממה ששיבחוהו: \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003הלכתא כותיה\u0004 \u0005[הלכה כמותו],\u0006 ומשום כך כשאמר את הדברים בשם רבי בלבד ואפשר היה לחשוב שזו דעת יחיד שאינה כהלכה — לא שיבחוהו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 נאמר בתורה בענין הגט: \u0003\"וכתב\u0004 לה ספר כריתות \u0003\"\u0004ויש בכך הדגשה: \u0003ולא חקק.\u0004 ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 מכאן ש\u0003חקיקה לאו\u0004 \u0005[לא]\u0006 \u0003כתיבה היא? ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא: \u0003עבד שיצא\u0004 לחירות בשטר שחרור שהיה \u0003בכתב ש\u0004חקוק \u0003על גבי טבלא\u0004 (לוח), או על גבי \u0003פינקס\u0004 — \u0003יצא לחירות\u0004 על ידי קבלת הטבלה או הפינקס הללו, \u0003אבל לא\u0004 יצא לחירות \u0003בכתב שעל גבי כיפא ואנדוכתרי\u0004 (בגד רקום). שאם רקם עליהם האדון את כתב השיחרור ונתנו לו — אין זה נחשב לכתיבת שטר. על כל פנים, כתב שעל גבי פינקס הריהו כתב חקוק, ובכל זאת יוצא בו לחירות!","\u0003אמר עולא אמר ר' אלעזר, לא קשיא\u0004 \u0005[אין זה קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שחקיקה אינה נחשבת כתיבה, מדובר באופן ש\u0003חק\u0004 (חקק) את ה\u0003תוכות.\u0004 שחקק את צורת האותיות על ידי זה שגילף מבחוץ, ועל ידי כך נוצרה צורת אות, שאין זו נקראת כתיבה משום שגוף האותיות עצמן לא נכתב. ואילו \u0003הא\u0004 \u0005[זה]\u0006 שחקיקה נחשבת לכתיבה, מדובר באופן ש\u0003חק\u0004 (חקק) \u0003יריכות,\u0004 שחקק ולחץ את צורת האותיות עצמן מצידו האחד של החפץ עליו הן צריכות להיכתב ונמצאו בכך בולטות מצידו האחר, ובמקרה כזה כתב גמור הוא.","ושואלים: \u0003ו\u0004אם הוא חוקק רק \u0003תוכות\u0004 — \u0003לא?\u0004 אין זה נחשב לכתיבה? \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003לא היה כתבו\u0004 של הציץ שבראשו של הכהן הגדול \u0003שוקע,\u0004 שלא היה חרוט בו, \u0003אלא בולט,\u0004 כלומר, האותיות היו בולטות ממנו \u0003כדינרי זהב. והא\u0004 \u0005[והרי]\u0006 האותיות שעל גבי \u0003דינרי זהב תוכות הן,\u0004 שהאופן שבו נעשה הכתב בדינרי זהב הוא באופן של חקיקת תוכות על ידי לחץ על סביבות האותיות, ומשמע שגם זו נקראת כתיבה!","ומשיבים: הכוונה היא \u0003כדינרי זהב,\u0004 אבל \u0003לא כדינרי זהב\u0004 לגמרי; \u0003כדינרי זהב\u0004 הכוונה — ש\u0003בולט\u0004 הכתב, \u0003ולא כדינרי זהב\u0004 — ש\u0003אילו התם\u0004 \u0005[שם]\u0006 בדינרי זהב חוקק \u0003תוכות, הכא\u0004 \u0005[כאן]\u0006 בציץ, החקיקה היתה חקיקת \u0003יריכות,\u0004 שהיו חורטים ולוחצים את האותיות מהצד האחורי של הציץ ונמצאות האותיות בולטות מלפניו, וכתיבתו היתה כתיבת אותיות ממש.","ובאותו נושא, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי:\u0004 האם \u0003רושמא\u0004 (החותם) היוצר את פני המטבע, האם הוא \u0003מיחרץ חריץ\u0004 \u0005[חורץ]\u0006 את הרקע בתוך הזהב וצורת המטבע נוצרת מאליה, \u0003או כנופי מכניף\u0004 \u0005[אוסף,\u0006 מכניס את הזהב לתוכו\u0005],\u0006 שהמתכת נלחצת כלפי המקום החלול שבחותם, ואז נוצרות האותיות? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מיחרץ חריץ\u0004 \u0005[חורץ\u0006 הוא\u0005].\u0006","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ממה ששנינו: \u0003לא היה כתבו\u0004 של ציץ \u0003שוקע, אלא בולט כדינרי זהב. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר שהחותם רק \u0003מיחרץ חריץ\u0004 \u0005[\u0006ש\u0005עושה\u0006 רק \u0005חריץ]\u0006 —"],["\u0003הא בעינא\u0004 \u0005[הרי צריכים אנו]\u0006 לקיים בו ככתוב \u0003\"מכתב\u0004 פיתוחי חותם\u0003\"\u0004 (שמות לט, ל) \u0003וליכא\u0004 \u0005[ואין כאן]\u0006 כתב! ומשיבים: הציץ היה אמנם עשוי \u0003כדינרי זהב ו\u0004אולם \u0003לא\u0004 היה \u0003כדינרי זהב\u0004 לגמרי, \u0003כדינרי זהב\u0004 — שהיה הכתב \u0003בולט, ולא כדינרי זהב,\u0004 ש\u0003אילו התם\u0004 \u0005[שם]\u0006 לחיצת החותם נעשתה \u0003מגואי\u0004 \u0005[מבפנים,\u0006 מהצד הנראה\u0005],\u0006 \u0003והכא מאבראי\u0004 \u0005[וכאן\u0006 נעשה \u0005מבחוץ]\u0006 שהיו דוחפים מהצד האחר עד שהאותיות היו יוצאות ובולטות החוצה, אבל היו חוקקים את האותיות עצמן והרי זה בכלל \"מכתב\".","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבא מרב נחמן: כתב לה\u0004 הבעל \u0003גט על טס\u0004 (לוח) \u0003של זהב, ואמר לה\u0004 לאשתו \u0003\"התקבלי גיטך והתקבלי\u0004 בזה גם את סכום \u0003כתובתך\",\u0004 שדי היה בזהב שבטס כדי לפרוע לה את סכום כתובתה, \u0003מהו\u0004 הדין? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003נתקבלה גיטה ונתקבלה כתובתה.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 על כך ממה ששנינו שאם נתן לאשה את גיטה כשהוא כתוב על דבר גדול, ואמר לה \u0003\"התקבלי גיטך, והשאר,\u0004 החלק שאין הגט כתוב עליו, מיועד \u0003ל\u0004פרעון \u0003כתובתך\"\u0004 — \u0003נתקבלה גיטה, והשאר\u0004 יהיה \u0003לכתובתה.\u0004","ונדייק מכאן: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003שאר, הא ליכא\u0004 \u0005[הרי\u0006 אם \u0005אין]\u0006 \u0003שאר\u0004 — \u0003לא,\u0004 ואף כאן נכתב הגט על כל הטס ואין שאר!","והשיב לו רב נחמן: \u0003הוא הדין אף על גב\u0004 \u0005[אף על פי]\u0006 \u0003דליכא\u0004 \u0005[שאין]\u0006 \u0003שאר,\u0004 כגון שכתוב הגט על כל הדבר כולו, \u0003והא קא משמע לן\u0004 \u0005[וזה\u0006 ששנינו שיש שאר \u0005השמיע לנו],\u0006 \u0003דאף על גב דאיכא\u0004 \u0005[שאף על פי שיש]\u0006 \u0003שאר,\u0004 דווקא \u0003אי\u0004 \u0005[אם]\u0006 \u0003אמר לה\u0004 בפירוש שהשאר הוא לכתובתה — \u0003אין\u0004 \u0005[כן]\u0006 ייחשב הדבר כתשלום כתובתה, ואולם \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 אמר לה כן בפירוש — \u0003לא,\u0004 וצריך לתת לה כתובתה בנפרד, בשלימות.","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — שאנו אומרים שאם לא ציין במפורש שהשאר מיועד לכתובתה, השאר \u0003אוירא דמגילתא\u0004 \u0005[הגליון,\u0006 השוליים \u0005של מגילת\u0006 הגט\u0005]\u0006 \u0003הוא\u0004 נחשב, ואם כן, כולו גט. ולכן צריך להודיע לה בפירוש שהשאר הוא לכתובה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אמר הבעל לאשתו \u0003\"הרי זה גיטך ו\u0004אולם \u0003הנייר\u0004 ישאר \u0003שלי\"\u0004 — \u0003אינה מגורשת,\u0004 שצריך שיהיו הגירושין נעשים בנתינה של גט, וכיון שהנייר הוא שלו גם לאחר הנתינה — נמצא שלא נתן לה אלא אותיות שאין בהן ממש. ואולם אם אמר לה \u0003\"על מנת שתחזירי לי את הנייר\"\u0004 — \u0003הרי זו מגורשת,\u0004 הואיל והגט שלה לגמרי באותה שעה, והחזרת הנייר אינה אלא תנאי.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב פפא:\u0004 אם אמר שהנייר ש\u0003בין שיטה לשיטה\u0004 (שורה לשורה) \u0003ובין תיבה לתיבה\u0004 (מלה למלה) בגט יהיה שלו, אבל לא הנייר שתחת המילים, \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין? לשאלה זו לא נמצאה תשובה ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","ושואלים: מדוע לא ניתנה תשובה לשאלת רב פפא? \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 תשובה לשאלה זו ממקור אחר, שהרי \u0003\"ספר\"\u0004 שמשמעו ספר \u0003אחד אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 בענין מתן גט (\"וכתב לה ספר כריתות\". דברים כד, א) \u0003ולא\u0004 שיהיו \u0003שנים ושלשה ספרים.\u0004 ואם מה שמקבלת האשה מיד בעלה אינו אלא הנייר שתחת המילים, ואילו הנייר האחר שבגט שייך לבעל, נמצא שאין זה כבר ספר אחד אלא כמה וכמה ספרים, ולא יהא זה גט! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 השאלה אלא במקרה ש\u0003מעורה\u0004 (מחובר), שהיו האותיות כתובות כך שגם אם ינטל הנייר שביניהן נשאר כל כתב הגט קשור יחד כדבר אחד.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא:\u0004 \u0003היו\u0004 הדיינים \u0003מוחזקים\u0004 (יודעים כבירור) \u0003בעבד שהוא שלו,\u0004 של האיש, \u0003וגט\u0004 שכתב אותו האיש לאשתו היה \u0003כתוב על ידו\u0004 של אותו עבד, שהשתמש בעבד כחומר עליו נכתב הגט, \u0003ו\u0004עתה \u0003הרי הוא,\u0004 העבד, \u0003יוצא מתחת ידה\u0004 (ברשותה), \u0003מהו\u0004 \u0005[מה]\u0006 דינו של גט זה?","וצדדי השאלה: \u0003מי אמרינן אקנויי אקני לה\u0004 \u0005[האם אומרים אנו שהקנה לה]\u0006 הבעל את העבד לאשתו, ואם כן, הרי זה כאילו נתן לה גט באופן כשר, וכפי שמפורש במשנתנו, והרי היא מגורשת בו. \u0003או דלמא\u0004 \u0005[שמא]\u0006 נאמר כי \u0003הוא,\u0004 העבד \u0003מנפשיה עייל\u0004 \u0005[מעצמו,\u0006 מרצונו, \u0005בא]\u0006 לאשה, שמעדיף הוא להיות תחת ידה ולא תחת ידי הבעל, ואילו הבעל לא נתנו כלל לאשה, ולכן אינה מגורשת?","\u0003אמר רבא: ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 לרמי בר חמי תשובה לשאלה זו מטעם אחר, ש\u0003כתב שיכול להזדייף הוא\u0004 שהרי כתב שנכתב על יד של אדם, הריהו כתב שאפשר בקלות למחוק אותו ולכתוב אחר, וגט שנכתב בכתב כזה פסול! ושואלים: \u0003ולרבא\u0004 שהקשה קושיה זו, \u0003קשיא מתניתין\u0004 \u0005[קשה משנתנו]\u0006 ששנינו בה שיכול לכתוב גט גם \u0003על היד של עבד!\u0004","ואומרים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 \u0003לרבא לא קשיא\u0004 \u0005[קשה],\u0006 שכן אפשר לומר שמדובר שנתן לה את העבד הזה \u0003בעדי מסירה, ו\u0004כשיטת \u0003ר' אלעזר היא,\u0004 שלדעתו לא כתיבת השטר או הגט עצמו היא הקובעת, אלא מסירתו בעדים, וכאן היתה מסירה כדין, ואף על פי שהכתב ראוי להזדייף — אינו פסול לדעת ר' אלעזר. \u0003אלא לרמי בר חמא קשיא\u0004 \u0005[קשה],\u0006 שהרי במקרה שהעלה בשאלתו לא נמסר העבד לאשה בפני עדי מסירה, ומדוע לא נפסול הגט משום כתב שיכול להזדייף!","ומשיבים: \u0003לרמי בר חמא נמי לא קשיא\u0004 \u0005[גם כן אין\u0006 זה \u0005קשה],\u0006 שהוא לא שאל את שאלתו במקרה שנכתב הגט על ידו של העבד בדיו, אלא \u0003בכתובת קעקע,\u0004 שבודאי אינה ניתנת להימחק ולהזדייף. ואומרים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שהגעת לכך],\u0006 \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 שמכשירה גט שנכתב על גבי עבד \u0003לרבא נמי לא תיקשי\u0004 \u0005[גם כן לא תהיה קשה],\u0006 שגם בה מדובר \u0003בכתובת קעקע.\u0004","על כל פנים השאלה ששאל רמי בר חמא נשארה בעינה, ואם כן, \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה],\u0006 על שאלה זו, למעשה? ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 פתרון לדבר ממה ש\u0003אמר ריש לקיש: הגודרות\u0004 (צאן), כיון שהן נודדות ממקום למקום, \u0003אין להן חזקה\u0004 בידי מי שמחזיק בהן, ואינו יכול לטעון ששלו הן כיון שהן בידו, כי כל דבר שיכול לנוע מדעת עצמו, אין חזקה למחזיק בו. ואם כן, הוא הדין גם לגבי עבד, שאם אין עדים על מסירתו ליד האשה, אין הימצאותו ברשותה (\"יוצא מתחת ידה\") עדות לכך שהגט ניתן לה כדין, ואין האשה מגורשת.","שאלה נוספת \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רמי בר חמא: היו\u0004 הדיינים \u0003מוחזקין בטבלא\u0004 (לוח) \u0003שהיא שלה,\u0004 של האשה \u0003וגט כתוב עליה, והרי היא\u0004 עכשיו הטבלא הזו \u0003יוצאה מתחת ידו\u0004 של הבעל, והוא רוצה לגרש את אשתו בטבלא זו, \u0003מהו? מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 כי \u0003אקנויי אקניתא ליה\u0004 \u0005[הקנתה לו]\u0006 את הטבלא הזו במתנה גמורה, ונמצא זה גט כשר. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003אשה לא ידעה לאקנויי\u0004 \u0005[יודעת להקנות]\u0006 קנין גמור בדבר שחוזר בסוף אליה, ולכן לא גמרה בליבה להקנותה בשלימות לבעלה, ונמצא איפוא שלא היתה כאן נתינת גט מהבעל לאשה, ואין הגט כשר.","\u0003אמר אביי: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 תשובה לשאלה זו ממה שמסופר במשנה: \u0003אף הוא,\u0004 ר' יהודה בן בבא, שדבריו הקודמים נזכרו באותה משנה \u0003העיד על כפר קטן שהיה בצד ירושלים, והיה בו זקן אחד והיה מלוה לכל בני הכפר, וכותב\u0004 את השטרות \u0003בכתב ידו ואחרים\u0004 היו \u0003חותמים, ובא מעשה\u0004 זה \u0003לפני חכמים והכשירוהו. ו\u0004לכאורה \u0003אמאי\u0004 \u0005[מדוע]\u0006 הכשירוהו? \u0003הא בעינא\u0004 \u0005[הרי צריכים אנו]\u0006 \u0003\"ספר מקנה\"\u0004 (ירמיה לב, יא), שהשטר עצמו צריך לעבור מרשות המקנה לרשות הקונה, \u0003וליכא\u0004 \u0005[ואין כאן],\u0006 שהרי היה אותו זקן כותב את השטרות עבור האנשים, על הנייר שלו!","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דאמרינן אקנויי מקנה להו\u0004 \u0005[שאנו אומרים\u0006 שבוודאי \u0005מקנה להם]\u0006 את השטרות כראוי, למרות שידע שמיד אחר כך יחזרו לרשותו. ואם כן הוא הדין בגט שנכתב על גבי טבלא של האשה שניתנה לבעל!","\u0003אמר רבא: ומאי קושיא\u0004 \u0005[ומה הקושיה],\u0006 כלומר, כיצד אפשר להוכיח מכאן? \u0003דילמא\u0004 \u0005[שמא]\u0006"],["\u0003זקן שאני\u0004 \u0005[שונה],\u0006 שהיה זה זקן = חכם, \u0003דידע לאקנויי\u0004 \u0005[שיודע להקנות]\u0006 במקרה כזה, מה שאין כן אשה.","\u0003אלא אמר רבא:\u0004 יש לפתור את הבעיה \u0003מהכא\u0004 \u0005[מכאן],\u0006 ממה ששנינו: \u0003ערב היוצא לאחר חיתום שטרות,\u0004 שאחרי שנחתם שטר ההלוואה הוסיף הערב בכתב ידו שהוא ערב לפרעון החוב — \u0003גובה\u0004 המלווה מן הערב רק \u0003מנכסים בני חורין\u0004 אבל לא מנכסים משועבדים, שהם נכסים שהיו של הערב ונמכרו לאחר לאחר חתימת הערבות, שכיון שלא היו עדים על הערבות של ערב זה, נחשב הדבר כעין הלוואה בעל פה, שאין נגבית אלא מנכסים בני חורין. וההוכחה היא מכך, שאם אין המלווה מקנה את השטר לערב על מנת שיחתום בו, כיצד בכלל חל שעבוד כלשהו על ידי כתב זה? הרי גוף הכתב אינו שייך לערב והשטר שייך למלווה!","\u0003אמר רב אשי: מאי קושיא\u0004 \u0005[מה הקושי\u0006 שבדבר\u0005]?\u0006 \u0003דלמא גברא שאני, דידע לאקנויי\u0004 \u0005[שמא גבר שונה, ש\u0006הוא \u0005יודע להקנות],\u0006 ואולם השאלה שלנו היתה לגבי אשה! \u0003אלא אמר רב אשי:\u0004 יש להביא ראיה \u0003מהכא\u0004 \u0005[מכאן],\u0006 ממה ששנינו: יכולה \u0003אשה\u0004 שתהא \u0003כותבת\u0004 בעצמה, או נותנת לסופר שיכתוב עבורה \u0003את גיטה,\u0004 ונותנת אותו לבעלה על מנת שיתנו לה, \u0003ו\u0004כן \u0003האיש כותב את שוברו\u0004 (הקבלה שתתן לו האשה לאחר שתקבל את המגיע לה בכתובתה), משום שלא הכתיבה היא הקובעת, \u0003שאין קיום הגט אלא בחותמיו,\u0004 כלומר, בעדים שעליו. מכל מקום אפשר ללמוד מכאן לענייננו שאשה יודעת להקנות כראוי את גוף הגט שעתידה לחזור ולקבל מבעלה.","\u0003אמר רבא: כתב לה,\u0004 לאשתו, \u0003גט ונתנו,\u0004 לגט זה, \u0003ביד עבדו, וכתב לה שטר מתנה עליו,\u0004 על העבד הזה — \u0003קנאתהו,\u0004 את העבד, בשטר המתנה \u0003ומתגרשת בו,\u0004 בגט שבידו, שאנו אומרים שהעבד נחשב כקרקע שלה, וכאילו ניתן הגט לרשותה באותה שעה וקנאתו בקנין חצר.","ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 יהיה הדין כך? הלא \u0003חצר מהלכת היא\u0004 העבד, \u0003וחצר מהלכת לא קנה!\u0004 שרשותו של אדם קונה לו רק כאשר היא קבועה, ולא כאשר אינה כזו, והעבד גם אם דינו כקרקע לשאר דברים — הרי הוא כחצר מהלכת! \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שמדובר כאן \u0003ב\u0004עבד \u0003עומד, והאמר\u0004 \u0005[ו\u0006אולם \u0005הרי אמר]\u0006 \u0003רבא: כל שאילו\u0004 היה \u0003מהלך\u0004 באותה שעה \u0003לא קנה,\u0004 גם אם היה \u0003עומד ויושב\u0004 — \u0003לא קנה!\u0004 ואומרים: \u0003והלכתא\u0004 \u0005[והלכה\u0006 זו\u0005]\u0006 יכולה להתקיים \u0003ב\u0004מקרה שהיה העבד \u0003כפות\u0004 ואינו יכול לזוז ממקומו, שאז אינו בגדר חצר מהלכת, ואז האשה קונה אותו ואת הגט שבידו.","\u0003ו\u0004עוד \u0003אמר רבא: כתב לה,\u0004 לאשתו \u0003גט ונתנו בחצרו, וכתב לה שטר מתנה עליו,\u0004 על החצר — \u0003קנאתהו\u0004 לחצר, \u0003ומתגרשת\u0004 בגט הנמצא \u0003בו.\u0004","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שייאמרו שני דבריו אלה של רבא, גם בעבד וגם בקרקע, ואינם יכולים להילמד זה מזה, ומה ההבדל? — \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק ב\u0003עבד,\u0004 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003דוקא\u0004 על ידי \u0003עבד\u0004 יכול להקנות כך, \u0003אבל\u0004 במקרה של \u0003חצר\u0004 — \u0003ליגזר\u0004 \u0005[\u0006יש מקום \u0005לגזור]\u0006 שלא יהיה זה גט, \u0003משום\u0004 מקרה אחר של \u0003חצרה הבאה לאחר מכאן.\u0004 שיטעו אנשים להכשיר גם אם הניח הבעל גט במקום מסויים שאינו שלו, ואחר כך קנתה האשה את המקום הזה. ואולם אין זה גט, משום שבשעה שהניח הבעל את הגט באותה חצר לא היתה זו חצר שלה, ולא הוא זה שבסופו של דבר נתן לה את החצר עם הגט בתוכה. ולכן השמיע לנו שאין גוזרים גזירה זו.","ומצד שני: \u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רבא \u0003חצר\u0004 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003דוקא\u0004 על ידי \u0003חצר\u0004 מתגרשת באופן זה, \u0003אבל\u0004 ב\u0003עבד\u0004 — \u0003ליגזר\u0004 \u0005[\u0006יש מקום \u0005לגזור]\u0006 בעבד \u0003כפות אטו\u0004 \u0005[משום]\u0006 עבד \u0003שאינו כפות,\u0004 ונאמר שאף בכפות אינו גט, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבכל זאת הרי זה גט.","\u0003אמר אביי\u0004 להקשות על רבא: \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003חצר מהיכא איתרבי\u0004 \u0005[מהיכן נתרבתה]?\u0006 מאיזה ריבוי במקרא למדנו שאשה מתגרשת גם אם ניתן הגט בחצירה? \u0003מ\u0004מה שנאמר \u0003\"\u0004ונתן ב\u0003ידה\"\u0004 (דברים כד, א) ואנו אומרים שלאו דווקא בידה ממש, אלא כל דבר שהוא ברשותה.","אולם כיון שהלימוד הוא מ\"ידה\", והחצר נחשבת כהרחבה של ידה, צריך להשוות את החצר ליד גם בדין אחר; \u0003מה ידה דאיתא\u0004 \u0005[שישנה,\u0006 שמועילה\u0005]\u0006 ומתגרשת בה \u0003בין מדעתה ובין בעל כורחה, אף חצרה\u0004 צריך להיות \u0003דאיתא\u0004 \u0005[שישנה]\u0006 \u0003בין מדעתה ובין בעל כורחה. והא\u0004 \u0005[והרי]\u0006 \u0003מתנה\u0004 — \u0003מדעתה איתא\u0004 \u0005[ישנה],\u0006 ואילו \u0003בעל כורחה ליתא\u0004 \u0005[אינה]\u0006 שהרי אם לא תרצה לקבל את המתנה — אין זו מתנה. ואם כן, חצר זו שמקנה הבעל לאשה בדרך מתנה אינה דומה לידה ולא תועיל לקנות עימה את הגט!","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב שימי בר אשי:\u0004 לדברי אביי, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003שליחות לקבלה,\u0004 אם שולחת האשה שליח לקבל עבורה את הגט, ש\u0003מדעתה איתא\u0004 \u0005[יש]\u0006 שליחות כזו, ואילו \u0003בעל כורחה ליתא\u0004 \u0005[אין],\u0006 שהרי אין אחר יכול למנות שליח לקבלת הגט מלבד האשה, \u0003ו\u0004בכל זאת \u0003קא הוי\u0004 \u0005[הריהו]\u0006 \u0003שליח לקבלה!\u0004 ומשמע אם כן שאין עומדים על כך שתהיה השוואה שלימה לידה!","\u0003ואביי\u0004 טוען כנגד זה: \u0003אטו\u0004 \u0005[וכי]\u0006 דין \u0003שליחות מ\"ידה\" איתרבי\u0004 \u0005[נתרבה]?\u0006 שדין שליחות אינו נלמד מהריבוי של \"ידה\", אלא \u0003מ\u0004שינוי המילים, שלא נאמר בכתוב \u0003\"ושלח\u0004 את אשתו \u0003\",\u0004 אלא \u0003\"ושלחה\"\u0004 (דברים כד, א), \u0003איתרבי\u0004 \u0005[נתרבה],\u0006 ללמד שגם האשה יכולה לשלוח שליח לקבל את הגט. ואם כן, דין שליחות שמקורו אחר אינו קשור להגבלות שיש בדין יד, אך חצר צריכה שתהיה בין מדעתה ובין בעל כורחה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 באופן אחר: \u0003שליחות לקבלה נמי אשכחן\u0004 \u0005[גם כן מצאנו]\u0006 שהיא יכולה להיות \u0003בעל כורחה,\u0004 כיצד? \u0003שכן אב מקבל גט לבתו\u0004 כשהיא \u0003קטנה בעל כורחה,\u0004 ואם כן, יש גם בשליחות לקבלה ענין של קבלה בעל כורחה, ואם כן הריהי דומה לידה.","שנינו במשנה שיכול הבעל לכתוב גט גם \u0003על העלה של זית\u0004 ועל הקרן של פרה ועל יד של עבד, ונותן לה את העבד או הפרה. ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 בענין \u0003יד\u0004 של \u0003עבד\u0004"],["\u0003לא אפשר למקצייה\u0004 \u0005[לקצוץ אותה],\u0006 שוודאי אסור לקצוץ את ידו של העבד, \u0003אלא קרן של פרה\u0004 — \u0003ליקצייה וליתביה\u0004 \u0005[שיקצוץ אותה ויתן אותה]\u0006 \u0003לה,\u0004 לאשה!","ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וכתב... ונתן לה\"\u0004 (ראה דברים כד, א), לומר שאין גט כשר אלא \u0003מי\u0004 (דבר) \u0003שאינו מחוסר אלא כתיבה ונתינה, יצא זה,\u0004 קרן של פרה \u0003שמחוסר כתיבה, קציצה, ונתינה,\u0004 ולכן גט שצריך לקצוץ אותו על מנת ליתנו בו אינו גט, אלא אם כן נותן את הדבר כולו.","שנינו במשנה ש\u0003ר' יוסי הגלילי אומר\u0004 שאין כותבים על דבר שיש בו רוח חיים ולא על האוכלים. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יוסי הגלילי?\u0004 ומשיבים, שדבר זה שנינו במפורש, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר בתורה בענין גט \"וכתב לה \u0003ספר\u0004 כריתות\" (שם) — \u0003אין לי אלא ספר\u0004 בלבד, \u0003מנין לרבות כל דבר? תלמוד לומר: \"וכתב לה\"\u0004 — \u0003מכל מקום,\u0004 כל צורת כתיבה, על כל דבר. \u0003אם כן,\u0004 כיון שיכול לכתוב על כל דבר, \u0003מה תלמוד לומר \"ספר\"?\u0004 ללמד: \u0003מה ספר\u0004 הוא \u0003דבר שאין בו רוח חיים ואינו אוכל\u0004 (מאכל), \u0003אף כל דבר\u0004 אחר ראוי לכתיבת גט עליו, ובלבד שיתקיימו בו תנאים אלו — \u0003שאין בו רוח חיים ואינו אוכל.\u0004","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 המכשירים כתיבת גט אף על דבר שאין בו רוח חיים ועל אוכלים, מה אומרים הם על כך? ומשיבים: \u0003אי כתיב\u0004 \u0005[אם\u0006 היה \u0005כתוב]\u0006 \u0003\"\u0004וכתב \u0003בספר\",\u0004 הייתי מפרש \u0003כדקאמרת\u0004 \u0005[כפי שאתה אומר],\u0006 שהכוונה לדבר שכותבים עליו, \u0003השתא דכתיב\u0004 \u0005[עכשיו שנאמר]\u0006 \u0003\"ספר\",\u0004 אין משמעותו הדבר שכותבים עליו את הגט, אלא \u0003לספירת\u0004 (סיפור) \u0003דברים הוא דאתא\u0004 \u0005[שבא].\u0006 כלומר, \"ספר\" הוא שם עצם מופשט, שפירושו: סיפור ענין הכריתות.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 \u0003האי\u0004 \u0005[\u0006ריבוי \u0005זה]\u0006 של \u0003\"וכתב\" מאי עבדי ליה\u0004 \u0005[מה עושים\u0006 הם \u0005בו]?\u0006 ומשיבים: הם רואים אותו כמיעוט; \u0003מיבעי להו\u0004 \u0005[צריכים\u0006 הם \u0005אותו]\u0006 כדי לומר שדווקא \u0003בכתיבה\u0004 האשה \u0003מתגרשת, ואינה מתגרשת בכסף.\u0004 ומסבירים: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]\u0006 שמתגרשת בכסף, שהרי הכתוב \u0003אקיש\u0004 \u0005[השווה]\u0006 \u0003יציאה\u0004 (גירושין) של האשה מבית בעלה \u0003להוייה\u0004 של אישות (קידושין), ומשום כך נלמד: \u0003מה הוייה\u0004 של קידושין היא \u0003בכסף, אף יציאה נמי\u0004 \u0005[גם כן]\u0006 תהיה \u0003בכסף,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 הכתוב שאינה מתגרשת בכסף.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר],\u0006 ר' יוסי הגלילי, מהיכן לומד הוא דבר זה? ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא,\u0006 נלמד \u0005לו]\u0006 הדבר \u0003מ\u0004מה שנאמר \u0003\"ספר כריתות\",\u0004 לומר: \u0003ספר כורתה\u0004 מבעלה, \u0003ואין דבר אחר,\u0004 כגון כסף \u0003כורתה.\u0004","ושואלים: \u0003ואידך\u0004 \u0005[ול\u0006בעל הדעה \u0005האחרת]\u0006 של חכמים, מה עושה הוא בהדגשה זו של \"כריתות\"? ומשיבים: \u0003מיבעי ליה\u0004 \u0005[נצרכה לו]\u0006 ההדגשה \"כריתות\" לומר שהגט צריך להיות \u0003דבר הכורת\u0004 ומבדיל לגמרי \u0003בינו לבינה,\u0004 ואינו משאיר כל קשר ביניהם. \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005],\u0006 האומר לאשתו: \u0003\"הרי זה גיטיך על מנת שלא תשתי יין\",\u0004 או \u0003\"על מנת שלא תלכי לבית אביך\",\u0004 אם אמר לה שתנאי זה הוא \u0003\"לעולם\"\u0004 — \u0003אין זה כריתות,\u0004 כיון שלא כרת וניתק לגמרי את הקשר ביניהם, שהרי מוטלת על האשה הגבלה זו מכוח נישואיה לבעלה. אבל אם אמר לה שלא תעשה דבר זה \u0003\"עד שלשים יום\"\u0004 — \u0003הרי זה כריתות,\u0004 כיון שתנאי זה קצוב בזמן — ועם מילואו ניתק הקשר בינה לבינו לחלוטין.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר],\u0006 ר' יוסי הגלילי, מהיכן לומד הוא הלכה זו? ומשיבים: \u0003מ\u0004מה שהיה יכול להיכתב \u0003\"\u0004ספר \u0003כרת\",\u0004 ונכתב \u0003\"כריתות\",\u0004 הרי זה בא ללמד שני דברים במלה אחת.","\u0003ואידך\u0004 \u0005[והאחר],\u0006 חכמים, מה הם דורשים מכך?ומשיבים: הם \u0003\"כרת\" \"כריתות\" לא דרשי\u0004 \u0005[דורשים],\u0006 שאינם סבורים שיש ללמוד הלכה משינוי הלשון בכתוב זה.","\u0003אין כותבין\u0004 גט \u0003ב\u0004דבר ה\u0003מחובר לקרקע.\u0004 אם \u0003כתבו במחובר\u0004 לקרקע, ואחר כך \u0003תלשו וחתמו ונתנו לה\u0004 — \u0003כשר. ר' יהודה פוסל\u0004 גט \u0003עד שתהא כתיבתו וחתימתו בתלוש.\u0004","\u0003ר' יהודה בן בתירא אומר: אין כותבין\u0004 גט \u0003לא על הנייר המחוק ולא על הדיפתרא\u0004 (עור שלא נגמר עיבודו), והטעם — \u0003מפני שהוא יכול להזדייף. וחכמים מכשירין\u0004 אם נכתב גט על אלה.","שנינו במשנה: \u0003כתבו על המחובר\u0004 ותלשו — הרי זה כשר. ומקשים: \u0003והאמרת רישא\u0004 \u0005[והרי אמרת\u0006 ב\u0005תחילת\u0006 המשנה\u0005]\u0006 ש\u0003אין כותבין\u0004 במחובר! \u0003אמר רב יהודה אמר שמואל: ו\u0004זה ששנינו שאם נתלש ונחתם הגט כשר, \u0003הוא\u0004 דווקא באופן \u0003ששייר מקום התורף,\u0004 שכאשר כתבו במחובר — לא כתב את כולו אלא רק את הנוסח הכללי, הטופס של הגט, ואת החלק המיוחד והפרטי שבו שמות האיש והאשה ועוד, שהוא עיקרו של הגט, לא כתב.","\u0003וכן אמר ר' אלעזר אמר ר' אושעיא: והוא ששייר מקום התורף. וכן אמר רבה בר בר חנה אמר ר' יוחנן: והוא ששייר מקום התורף. ו\u0004כל זה שיטת \u0003ר' אלעזר היא,\u0004 ש\u0003אמר: עדי מסירה כרתי\u0004 \u0005[\u0006הם ה\u0005כורתים],\u0006 המסיימים את חלותו של הגט.","שלא חתימת העדים של הגט היא המכשירה אותו, אלא מסירתו על ידי עדים היא העיקר, ולפי זה \"וכתב\" האמור בתורה מתייחס לכתיבת הגט עצמו ולא לחתימתו, \u0003ו\u0004משום כך, \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 במשנתנו: לכתחילה \u0003אין כותבין\u0004 אפילו \u0003טופס\u0004 במחובר \u0003שמא יכתוב\u0004 כך גם את ה\u0003תורף,\u0004 אבל אם \u0003כתבו לטופס ותלשו,\u0004 ואחר כך \u0003כתבו לתורף ונתנו לה\u0004 — \u0003כשר.\u0004","\u0003וריש לקיש אמר:\u0004 אין לפרש \"וחתמו\" שבמשנה במשמעות של כתיבת התורף, אלא \u0003חתמו\u0004 ממש \u0003שנינו, ו\u0004שיטת \u0003ר' מאיר היא\u0004 ש\u0003אמר עדי חתימה כרתי\u0004 \u0005[\u0006הם ה\u0005כורתים].\u0006","\u0003והכי קאמר\u0004 \u0005[וכך אמר]:\u0006 \u0003אין כותבין תורף\u0004 במחובר, והטעם — \u0003גזרה שמא\u0004 אף \u0003יחתום\u0004 במחובר, ואולם אם \u0003כתבו\u0004 אפילו \u0003לתורף\u0004 במחובר, \u0003תלשו, חתמו ונתנו לה\u0004 — \u0003כשר.\u0004","אגב דיון זה דנים בכמה הלכות שבהגדרת תלוש ומחובר. אם \u0003כתבו,\u0004 את הגט, \u0003על חרס של עציץ נקוב\u0004 — \u0003כשר, דשקיל ליה ויהיב ליה ניהלה\u0004 \u0005[שלוקח אותו,\u0006 את העציץ הזה, \u0005ונותן אותו לה].\u0006 אבל אם כתב אותו \u0003על עלה של\u0004 צמח הנמצא ב\u0003עציץ נקוב,\u0004 מה יהא הדין? \u0003אביי אמר: כשר, ורבא אמר: פסול.\u0004 ומפרטים: \u0003אביי אמר כשר,\u0004"],["\u0003דשקיל ליה ויהיב ליה ניהלה\u0004 \u0005[שלוקח אותו,\u0006 את העציץ ובו העלה \u0005ונותן אותו לה].\u0006 \u0003רבא אמר פסול,\u0004 שאמנם מעיקר הדין אם יתן לה את העלה כפי שהוא מחובר לצמח הגדל בעציצו, הרי זה כשר. אבל בכל זאת פוסלים אותו משום \u0003גזרה שמא יקטום\u0004 (יתלוש) רק את העלה הזה ויתן אותו לה, ונמצא שנתן לה גט מדבר שנתלש מן המחובר לאחר כתיבתו.","באותו ענין עצמו של עציץ נקוב דנים עוד: היה \u0003עציץ של אחד וזרעים\u0004 שבו היו \u0003של אחר,\u0004 ו\u0003מכר בעל\u0004 ה\u0003עציץ\u0004 את עציצו \u0003לבעל\u0004 ה\u0003זרעים, כיון שמשך\u0004 בעל הזרעים את העציץ — \u0003קנה,\u0004 שהעציץ עצמו נחשב כמיטלטלים ומיטלטלים נקנים במשיכה. אבל אם \u0003מכר בעל זרעים לבעל עציץ\u0004 את הזרעים — \u0003לא קנה\u0004 בעל עציץ את הזרעים \u0003עד שיחזיק\u0004 (יעשה מעשה חזקה) \u0003בזרעים\u0004 עצמם, כגון לעדור או לנכש את האדמה שסביבם. שכיון שהזרעים מחוברים לקרקע — הם נחשבים כקרקע, וקרקע אינה נקנית במשיכה.","היו \u0003עציץ וזרעים של אחד, ומכרן לאחר,\u0004 כיון ש\u0003החזיק\u0004 הקונה \u0003בזרעים\u0004 ונקנו לו בכך — \u0003קנה\u0004 איתם גם את ה\u0003עציץ. וזו היא ששנינו: נכסים שאין להם אחריות\u0004 (מיטלטלים) \u0003נקנין עם נכסים שיש להן אחריות\u0004 (קרקעות) \u0003בכסף ובשטר ובחזקה.\u0004 ולכן המחזיק בזרעים, שדינם כקרקע, קנה אגב כך גם את העציץ שהוא מיטלטלים.","אבל אם \u0003החזיק\u0004 הקונה \u0003בעציץ\u0004 בלבד — \u0003אף\u0004 את ה\u0003עציץ לא קנה,\u0004 שאין מיטלטלים נקנים בחזקה, \u0003עד שיחזיק בזרעים\u0004 ואז יקנה אף את העציץ,","ועוד בנושא זה: היה עציץ נקוב עומד על גבולה של ארץ ישראל, והיה \u0003נקבו\u0004 (הנקב שלו) \u0003בארץ\u0004 (ארץ ישראל) \u0003ונופו\u0004 של הצומח בעציץ יוצא \u0003בחוצה לארץ,\u0004 מה דינו של הצמח לענין המצוות התלויות בארץ, כגון תרומות ומעשרות? \u0003אביי אמר: בתר\u0004 \u0005[אחרי]\u0006 \u0003נקבו אזלינן\u0004 \u0005[הולכים אנו]\u0006 ודינו כצמח שצמח בארץ. \u0003רבא אמר: בתר\u0004 \u0005[אחרי]\u0006 \u0003נופו אזלינן\u0004 \u0005[הולכים אנו]\u0006 ודינו כדבר הגדל בחוצה לארץ.","ומעירים: \u0003בדאשרוש\u0004 \u0005[ב\u0006מקרה \u0005שהשריש],\u0006 שהצמח שבתוך העציץ שלח שורשים בתוך הקרקע שמחוץ לעציץ \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 שדינו כדין המקום שממנו הוא יונק. \u0003כי פליגי\u0004 \u0005[כאשר חלוקים\u0006 הם\u0005]\u0006 — הרי זה \u0003ב\u0004מקרה ש\u0003לא אשרוש\u0004 \u0005[השריש]\u0006 בקרקע, ואז יש לדון האם הולכים אחרי הנקב או אחר הנוף.","ומקשים: \u0003ובדאשרוש\u0004 \u0005[ו\u0006האם \u0005ב\u0006מקרה \u0005שהשריש]\u0006 הצמח בקרקע \u0003לא פליגי\u0004 \u0005[נחלקו]\u0006 והכל מודים שהולכים אחר מקום הנקב? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 היו \u0003שתי גנות\u0004 של שני אנשים העשויות כמדרגות \u0003זו על גב זו, וירק\u0004 צומח \u0003בינתים\u0004 (באמצע) על דופן המדרגה שבין הגינות, \u0003ר' מאיר אומר:\u0004 הירק הזה \u0003של עליון,\u0004 בעל הקרקע העליונה. \u0003ר' יהודה אומר: של תחתון,\u0004 בעל הקרקע התחתונה. משמע שאפילו כאשר הצמח היכה שורשים בקרקע העליון ויונק ממנה, ואולם נופו נמצא במקום אחר, יש דעה שהולכים אחר נופו!","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 יש סיבה אחרת למחלוקת, \u0003כדקתני טעמא\u0004 \u0005[כפי שנשנה הטעם]\u0006 במפורש, \u0003אמר ר' מאיר: מה אם ירצה\u0004 ה\u0003עליון ליטול את עפרו,\u0004 ואז \u0003אין כאן ירק\u0004 עוד, ולכן הירק הוא של עליון.","וכנגדו \u0003אמר ר' יהודה: מה אם ירצה התחתון למלאות את\u0004 אויר \u0003גנתו עפר, אין כאן ירק,\u0004 ולכן הירק שייך לתחתון. ואם כן לא נחלקו בשאלת חשיבותם של מקום היניקה ושל הנוף, אלא במידת שליטתם של בעלי הגינות בקיומם של גידולים אלה, ואין להוכיח לענייננו ממחלוקת זו.","ושואלים עוד: \u0003ואכתי, בדאשרוש\u0004 \u0005[ועדיין\u0006 האם במקרה \u0005שהשריש]\u0006 \u0003לא פליגי\u0004 \u0005[נחלקו]?\u0006 \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אילן\u0004 שהיה \u0003מקצתו בארץ\u0004 ישראל \u0003ומקצתו בחוצה לארץ\u0004 — \u0003טבל וחולין מעורבין זה בזה,\u0004 בכל אחד מפירות האילן, אלו \u0003דברי רבי. רבן שמעון בן גמליאל אומר:\u0004 פירותיו של חלק האילן \u0003הגדל בחיוב,\u0004 כלומר, בארץ — \u0003חייב, והגדל בפטור,\u0004 בחוצה לארץ — \u0003פטור.\u0004","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר שם ש\u0003מקצת נופו\u0004 היה \u0003בארץ\u0004 ישראל \u0003ומקצת נופו בחוצה לארץ\u0004 למרות ששורשיו נמצאים במקום אחד? ואם כן, בין לדעת רבי ובין לדעת רבן שמעון בן גמליאל אין מקום ההשרשה לבדו קובע!","ודוחים: \u0003לא,\u0004 מדובר פה ש\u0003מקצת שרשין בארץ\u0004 ( ארץ ישראל) \u0003ומקצת שרשין בחוצה לארץ.\u0004 ושואלים: \u0003ומאי טעמא\u0004 \u0005[ומה הטעם]\u0006 של \u0003רבן שמעון בן גמליאל?\u0004 הרי כל פירות העץ יונקים גם מן הארץ וגם מחוצה לארץ! ומשיבים: מדובר שם ש\u0003מפסיק צונמא\u0004 \u0005[סלע]\u0006 באמצע השורשים עד הגזע ולכן אפשר להבחין בין חלקי האילן היונקים מארץ ישראל לבין אלו היונקים מחוצה לארץ.","ושואלים: אם כן, במקרה זה \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רבי?\u0004 ומשיבים: סבור הוא שלמרות שבתוך השורשים יש הפסק, בכל זאת \u0003דהדרי ערבי\u0004 \u0005[שחוזרים ומתערבים]\u0006 יניקות השורשים בגוף האילן.","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון הם \u0005חלוקים]?\u0006 ומשיבים: \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 רבי, \u0005סבור]:\u0006 \u0003אוירא\u0004 \u0005[האויר,\u0006 מה שנמצא מעל לקרקע\u0005]\u0006 \u0003מבלבל,\u0004 מערב את היניקות של השורשים השונים, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רבן שמעון בן גמליאל, \u0005סבור]:\u0006 \u0003האי לחודיה קאי והאי לחודיה קאי\u0004 \u0005[זה לבדו עומד וזה לבדו עומד]\u0006 מן השורשים ועד הנוף.","שנינו במשנה ש\u0003ר' יהודה בן בתירא אומר\u0004 שאין כותבים גט על דבר שעשוי להזדייף, לא על נייר מחוק ולא על הדיפתרא. ומבררים מהו עניינו של דיפתרא. \u0003אמר ר' חייא בר אסי משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא, שלשה עורות הן,\u0004 כלומר, יש שלוש דרגות בעיבוד העור, והן קרויות: \u0003מצה, חיפה, ודיפתרא.\u0004","\u0003מצה\u0004 — \u0003כמשמעו,\u0004 עור הדומה למצה, שהוא \u0003לא מליח\u0004 \u0005[עובד במלח]\u0006 \u0003ו\u0004ש\u0003לא קמיח\u0004 \u0005[עובד בקמח]\u0006 \u0003ו\u0004ש\u0003לא אפיץ\u0004 \u0005[עובד בעפצים].\u0006 ומבררים: \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 נזכר סוג זה של עור — \u0003להוצאת שבת,\u0004 לגבי קביעת השיעור הקטן ביותר של עור מסוג זה שחייבים עליו אם הוציאוהו בשבת מרשות היחיד לרשות הרבים. \u0003וכמה שיעורו\u0004 של עור כזה? — \u0003כדקתני\u0004 \u0005[כפי ששנה]\u0006 \u0003רב שמואל בר יהודה: כדי לצור\u0004 (לצרור) בו \u0003משקל\u0004 (משקולת) \u0003קטנה. וכמה\u0004 היא קטנה? — \u0003אמר אביי: כי ריבעא דריבעא\u0004 \u0005[כמו רבע רביעית]\u0006 של \u0003פומבדיתא,\u0004 שזוהי משקולת קטנה.","\u0003חיפה\u0004 — זהו עור \u0003דמליח\u0004 \u0005[שעובד במלח]\u0006 \u0003ולא קמיח\u0004 \u0005[עובד בקמח]\u0006 \u0003ולא אפיץ\u0004 \u0005[עובד בעפצים].\u0006 \u0003למאי הילכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 נזכר עור זה? — \u0003להוצאת שבת. וכמה שיעורו?\u0004 — \u0003כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 \u0003עור\u0004 — \u0003כדי לעשות\u0004 בו \u0003קמיע,\u0004 ומדובר בעור במצב עיבוד זה.","\u0003דיפתרא\u0004 — הוא עור \u0003דמליח וקמיח\u0004 \u0005[שעובד במלח ובקמח]\u0006 \u0003ו\u0004עדיין \u0003לא אפיץ\u0004 \u0005[עובד בעפצים].\u0006 \u0003למאי הילכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה\u0006 נזכר\u0005]?\u0006 — \u0003להוצאת שבת. וכמה שיעורו?\u0004 — \u0003כדי לכתוב עליו את הגט.\u0004","שנינו במשנה ש\u0003חכמים מכשירין\u0004 גם בנייר מחוק ודיפתרא. ושואלים: \u0003מאן\u0004 \u0005[מי הם]\u0006 \u0003חכמים\u0004 אלה? \u0003אמר\u0004 האמורא \u0003ר' אלעזר:\u0004"],["שיטת התנא \u0003ר' אלעזר היא,\u0004 ש\u0003אמר: עדי מסירה כרתי\u0004 \u0005[כורתים],\u0006 שעיקרו של הגט במסירתו בפני עדים, והואיל והעדים קראו אותו בשעה שנמסר בפניהם — עליהם אנו סומכים כדי לקיים את הגט בבית הדין ולא על הכתוב בגט, ולכן יש להכשיר אף גט שנכתב על נייר מחוק ודיפתרא.","\u0003ואמר ר' אלעזר: לא הכשיר ר' אלעזר\u0004 גט כזה \u0003אלא לאלתר,\u0004 שמייד לאחר שנמסר לאשה מביאים אותו לבית הדין לקיימו. \u0003אבל מכאן עד עשרה ימים\u0004 — \u0003לא,\u0004 אין הוא כשר, ומדוע? — \u0003חיישינן דילמא הוה ביה תנאה וזייפתיה\u0004 \u0005[חוששים אנו שמא היה בו תנאי וזייפה אותו],\u0006 שהרי הוא כתוב על חומר שאפשר לזייף את הכתוב בו בנקל.","\u0003ור' יוחנן אמר: אפילו מכאן עד עשרה ימים\u0004 — \u0003כשר,\u0004 ומדוע? — ש\u0003אם\u0004 \u0003איתא דהוה ביה\u0004 \u0005[אכן היה בו]\u0006 \u0003תנאי\u0004 — \u0003מידכר דכירי\u0004 \u0005[זוכרים]\u0006 העדים דבר זה, ולא היו שוכחים דבר בולט כזה, ואם זייפה אותו תנאי — לא יקיימו העדים את הגט.","\u0003ו\u0004עוד \u0003אמר ר' אלעזר\u0004 (האמורא): \u0003לא הכשיר\u0004 התנא \u0003ר' אלעזר\u0004 שטר העשוי להזדייף \u0003אלא בגיטין, אבל בשאר שטרות\u0004 — \u0003לא, דכתיב\u0004 \u0005[שנאמר]\u0006 בקשר לשטרות מכר: \u0003\"ונתתם בכלי חרש למען יעמדו ימים רבים\"\u0004 (ירמיה לב, יד), משמע ששטר מכר וכיוצא בו צריך להיות דבר שיכול להתקיים זמן רב מאז נתינתו בלא שייעשו בו שינויים. ואילו שטר שיכול להזדייף מעיקרו אינו שטר שאפשר לסמוך עליו לאורך זמן.","\u0003ור' יוחנן אמר: אפילו ב\u0004שאר \u0003שטרות\u0004 הכשיר ר' אלעזר. ושואלים לשיטת ר' יוחנן, \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"למען יעמדו ימים רבים\"!\u0004 ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003עצה טובה\u0004 בלבד \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ולא כעיכוב להלכה. שיעץ שמוטב שיהא השטר כתוב כך שיוכל להישאר זמן רב, שמא יזדקקו לו לראיה, ויסמכו על חותמיו.","\u0003הכל כשרין לכתוב את הגט, אפילו חרש, שוטה וקטן.\u0004 וכן \u0003האשה כותבת את גיטה\u0004 בעצמה, ותתננו לבעל, ואחר כך ימסרנו לה הבעל, \u0003והאיש כותב את שוברו,\u0004 את הקבלה שצריכה האשה לתת לו לאישור לאחר שנפרעה ממנו את כתובתה. \u0003וטעם הדבר — לפי\u0004 \u0003שאין קיום הגט אלא בחותמיו,\u0004 ולפיכך אין זה משנה מי כתבו.","ושואלים: כיצד יכולים חרש שוטה וקטן לכתוב גט? \u0003והא לאו\u0004 \u0005[והרי לא]\u0006 \u0003בני דיעה נינהו\u0004 \u0005[הם]\u0006 ואינם יודעים לכתוב הגט לשמה! \u0003אמר רב הונא:\u0004"],["\u0003והוא שהיה גדול עומד על גביו\u0004 של זה שאינו בר דעת, ואומר לו שיכתוב לשמו ולשם אשתו, והדבר מועיל כיון שלדעתו של הגדול הוא כותב.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן: אלא\u0004 לדבריך, שכל הפסול לכתיבת גט, אם כתבו כאשר גדול עומד על גביו — כשר, \u0003מעתה,\u0004 אם היה הכותב \u0003גוי, וישראל עומד על גביו\u0004 ואומר לו לכתוב לשמה \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר שהוא \u0003כשר? וכי תימא הכי נמי\u0004 \u0005[ואם תאמר כך\u0006 הוא \u0005גם כן],\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003גוי פסול\u0004 בכל אופן לכתיבת הגט! והשיב לו: \u0003גוי לדעתיה דנפשיה עבד\u0004 \u0005[לדעת עצמו\u0006 הוא \u0005עושה]\u0006 גם אם גדול עומד על גביו, מה שאין כן אלה שאינם בני דעת, שעושים לפי מה שמורים להם לעשות.","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר רב נחמן: לאו מילתא היא דאמרי\u0004 \u0005[אין זה דבר\u0006 של ממש מה \u0005שאמרתי,\u0006 שהקשיתי מגוי\u0005],\u0006 שהרי \u0003דמדקא פסיל ליה\u0004 \u0005[מתוך ש\u0006הוא \u0005פוסל אותו]\u0006 \u0003לגוי לענין הבאה\u0004 של הגט במשנה להלן בתוך שאר הפסולים, \u0003מכלל\u0004 הדברים אתה למד כי \u0003לענין כתיבה\u0004 במשנתנו, שלא נכלל בתוך הפסולים — \u0003כשר\u0004 הוא.","ושואלים: אף לשיטתו \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003גוי פסול!\u0004 ומשיבים: \u0003ההיא,\u0004 אותה ברייתא — שיטת \u0003ר' אלעזר היא,\u0004 ש\u0003אמר: עדי מסירה כרתי\u0004 \u0005[כורתים]\u0006 את הגט, ואם כן מה שנאמר \"וכתב לה\" \u0005(דברים כד, א)\u0006 אין הכוונה לחתימה אלא לכתיבת הגט עצמו \u0003ובעינן\u0004 \u0005[וצריכים אנו]\u0006 לפיכך שתהא \u0003כתיבה\u0004 של הגט \u0003לשמה, והא\u0004 \u0005[והרי]\u0006 \u0003ודאי גוי אדעתיה דנפשיה קעביד\u0004 \u0005[על דעת עצמו\u0006 הוא \u0005עושה]\u0006 ולא לדעת מי שמכתיב לו, ואין כן שיטת משנתנו.","ועוד בענין זה \u0003אמר רב נחמן, אומר היה ר' מאיר: אפילו מצאו\u0004 הבעל את הגט \u0003באשפה,\u0004 ונזדמן שהיו השמות הכתובים בו כשמו וכשם אשתו, והלך ו\u0003חתמו\u0004 בעדים, \u0003ונתנו לה\u0004 — הרי זה \u0003כשר,\u0004 שהכל הולך אחר עדי החתימה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן:\u0004 נאמר \u0003\"וכתב לה\"\u0004 ודרשו: \"לה\" — \u0003לשמה. מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה ל\u0003כתיבת הגט\u0004 ממש? ודחה: \u0003לא,\u0004 הכוונה היא \u0003חתימת עדים.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא\u0004 עוד ממה ששנינו: \u0003כל גט שנכתב שלא לשום\u0004 (לשם) ה\u0003אשה\u0004 המתגרשת בו — \u0003פסול!\u0004 ענה לו: \u0003אימא\u0004 \u0005[אמור]\u0006 לשיטת ר' מאיר: \u0003שנחתם שלא לשום אשה\u0004 — \u0003פסול.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 רבא עוד ממה ששנינו: \u0003כשהוא כותבו\u0004 — \u0003כאילו כותבו לשמה, מאי לאו\u0004 \u0005[האם אין]\u0006 פירוש הדבר כך: \u0003כשהוא כותבו לתורף,\u0004 לעיקר הגט, שבו רשומים שם האיש והאשה והזמן, ונוסח \"הרי את מותרת לכל אדם\", \u0003לשמה\u0004 — \u0003כאילו כותבו לטופס,\u0004 לנוסח המלא של הגט \u0003לשמה!?\u0004 הרי שצריך בגט כתיבה לשמה!","ודחה רב נחמן: \u0003לא,\u0004 לשיטת ר' מאיר הכוונה היא \u0003כשהוא חותמו,\u0004 מחתים את העדים, \u0003לשמה\u0004 — \u0003כאילו כותבו לשמה. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003הני מתניתין מני\u0004 \u0005[אותן המשניות\u0006 שהקשו מהן, שיטת \u0005מי הן]?\u0006 — שיטת \u0003ר' אלעזר היא,\u0004 ש\u0003אמר: עדי מסירה כרתי\u0004 \u0005[כורתים],\u0006 שהם גומרים את הכריתות, ולדעתו אכן צריך שתהא הכתיבה לשמה, ואילו דברי היו לשיטת ר' מאיר.","\u0003ורב יהודה אמר שמואל:\u0004 משנתנו המכשירה גט שכתבוהו חרש שוטה וקטן מדברת כשכתבו הם רק את הטופס של הגט, \u0003והוא ששייר מקום התורף,\u0004 ותורפו, עיקרו של הגט, ייכתב אחר כך על ידי בן דעת לשמה. \u0003וכן אמר רב חגא משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא: והוא ששייר מקום התורף, ו\u0004שיטת \u0003ר' אלעזר היא.\u0004","\u0003ור' זריקא אמר ר' יוחנן: אינה תורה.\u0004 על דברים אלה שואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש הביטוי \u0003\"אינה תורה\"? אמר ר' אבא: כאן הודיעך\u0004 ר' יוחנן \u0003שאין כח לשמה\u0004 בכתיבה אלא דווקא בחתימה, \u0003ו\u0004שיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר: עדי חתימה כרתי\u0004 \u0005[כורתים].\u0006","ושואלים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבה בר בר חנה אמר ר' יוחנן\u0004 על משנתנו ששיטת \u0003ר' אלעזר היא!\u0004 ומשיבים: מחלוקת \u0003אמוראי נינהו\u0004 \u0005[אמוראים היא]\u0006 \u0003ו\u0004שניהם \u0003אליבא\u0004 \u0005[לשיטתו]\u0006 של \u0003ר' יוחנן,\u0004 אם כר' מאיר או כר' אלעזר.","\u0003הכל כשרין\u0004 להיות שליחים \u0003להביא את הגט\u0004 לאשה \u0003חוץ מחרש, שוטה, וקטן, וסומא\u0004 (עיוור), \u0003וגוי.\u0004","\u0003קיבל הקטן\u0004 את הגט \u0003והגדיל\u0004 אחר כך, או קיבלו כשהיה \u0003חרש ונתפקח,\u0004 או שקיבלו כשהוא \u0003סומא ונתפתח\u0004 (החל לראות), וכן אם קיבלו כשהיה \u0003שוטה ונשתפה\u0004 לאחר זמן, או שקיבלו כשהיה \u0003גוי ונתגייר\u0004 — \u0003פסול\u0004 בכל אלה.","\u0003אבל\u0004 אם קיבלו כשהיה \u0003פקח ונתחרש\u0004 לאחר מכן \u0003וחזר ונתפקח,\u0004 או שהיה \u0003פתוח ונסתמא\u0004 (נתעוור) \u0003וחזר\u0004 לאחר מכן \u0003ונתפתח,\u0004 או שהיה \u0003שפוי ונשתטה וחזר ונשתפה\u0004 — \u0003כשר. זה הכלל: כל שתחילתו וסופו בדעת\u0004 — \u0003כשר,\u0004 גם אם באמצע היה זמן שבו היה פסול.","על אותם שנאמר עליהם במשנה שאינם יכולים להביא את הגט, שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 פסולם של \u0003חרש, שוטה וקטן\u0004 — משום \u0003דלאו\u0004 \u0005[שלא]\u0006 \u0003בני דיעה נינהו\u0004 \u0005[הם]\u0006 ושליחות יכולה להיות רק על ידי בן דעת, \u0003גוי נמי\u0004 \u0005[גם כן]\u0006 פסול — \u0003דלאו בר היתירא\u0004 \u0005[שלא בן היתר]\u0006 \u0003הוא\u0004 על ידי גט, וכל דבר שאדם אינו יכול לעשות בעצמו, אינו יכול להיות שליח בו, \u0003אלא סומא אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא\u0004 כשר להביא גט? \u0003אמר רב ששת: לפי שאינו יודע ממי נוטלו ולמי נותנו.\u0004 וכיון שאינו יודע, אינו יכול להעיד על כך.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף:\u0004 אם חוששים שאין הסומא מבחין בין בני אדם, אם כן \u0003היאך\u0004 \u0005[איך]\u0006 ה\u0003סומא מותר באשתו?\u0004 שמא אינה אשתו, וכן \u0003היאך\u0004 סתם \u0003בני אדם מותרים בנשותיהם בלילה\u0004 כשאינם רואים אותן? \u0003אלא\u0004 צריך אתה לומר שמותרים הם \u0003בטביעות עינא דקלא\u0004 \u0005[בטביעת עין של הקול],\u0006 שמכירים זה את זה על פי קולם, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לגבי קבלת הגט יכול הסומא להכיר \u0003בטביעות עינא דקלא\u0004 \u0005[בטביעת עין של הקול]\u0006 את נותן הגט ומקבלו.","\u0003אלא אמר רב יוסף: הכא\u0004 \u0005[כאן]\u0006 בבעל השולח גט \u0003בחוצה לארץ עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003דבעי למימר\u0004 \u0005[שצריך\u0006 השליח \u0005לומר]:\u0006 \u0003\"בפני נכתב ובפני נחתם\", ולא מצי למימר\u0004 \u0005[ואינו יכול לומר]\u0006 זאת שהרי עיוור הוא ואינו יכול לראות את הדבר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה,\u0004 מי שהיה \u0003פתוח\u0004 (רואה) בזמן קבלת הגט \u0003ונסתמא\u0004 אחר כך, \u0003דמצי אמר\u0004 \u0005[שיכול לומר]\u0006 \"בפני נכתב ובפני נחתם\", שהרי מעיד על הזמן שבו ראה את הדברים, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר שיהיה \u0003כשר? והא קתני\u0004 \u0005[והרי שנה\u0006 במשנה\u0005]:\u0006 \u0003פתוח ונסתמא וחזר ונתפתח\u0004 — \u0003כשר,\u0004 ונדייק מכאן: דווקא \u0003חזר ונתפתח\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 אבל אם \u0003לא חזר ונתפתח\u0004 — \u0003לא!\u0004","את הקושיה הזו דוחים: באמת \u0003הוא הדין\u0004 בסומא \u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003לא חזר ונתפתח\u0004 יכול להיות שליח ולהעיד על מה שראה קודם לכן, \u0003ואיידי דקתני\u0004 \u0005[ומתוך ששנה]\u0006 \u0003שפוי ונשתטה וחזר ונשתפה,\u0004 ושם \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003חזר ונשתפה, הא\u0004 \u0005[הרי]\u0006 אם \u0003לא חזר ונשתפה\u0004 — \u0003לא,\u0004 שבוודאי מי שאינו בן דעת אינו יכול להעיד על דבר, לכן \u0003תנא נמי\u0004 \u0005[שנה גם כן]\u0006 \u0003פתוח ונסתמא וחזר ונתפתח.\u0004 אבל באמת בסומא אם היה פיקח בזמן כתיבת הגט וחתימתו תחילתו ורק אחר כך נסתמא — כשר.","\u0003אמר רב אשי: דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 לפרש כך, ומדוע — \u0003דקתני\u0004 \u0005[ששנה\u0006 במשנה\u0005],\u0006 \u0003זה הכלל: כל שתחילתו וסופו בדעת\u0004 — \u0003כשר, ולא קתני\u0004 \u0005[שנה]:\u0006 \u0003כל שתחילתו וסופו בכשרות\u0004 — \u0003כשר, שמע מינה\u0004 \u0005[למד מכאן]\u0006 שאין מדקדקים שיהיה תחילתו וסופו בכשרות, שפעמים אם תחילתו בכשרות אין צורך שיהיה גם סופו בכשרות, אבל ברור שצריך להיות תחילתו וסופו בדעת, וסומא הריהו כזה.","\u0003בעו מיניה\u0004 \u0005[שאלו אותו]\u0006 \u0003מר' אמי: עבד, מהו שיעשה שליח לקבל גט אשה מיד בעלה?\u0004 האם ראוי הוא לכך, או לא? \u0003אמר להו\u0004 \u0005[להם],\u0006 לשואלים: \u0003מדקא פסיל ליה\u0004 \u0005[מתוך ש\u0006הוא \u0005פוסל לו\u0006 במשנה\u0005]\u0006 \u0003לגוי,\u0004"],["\u0003מכלל\u0004 הדברים אתה למד ש\u0003עבד כשר.\u0004 לעומת זאת \u0003אמר רב אסי אמר ר' יוחנן: אין העבד נעשה שליח לקבל גט לאשה מיד בעלה, לפי שאינו בתורת גיטין וקדושין.\u0004 וכיון שאין בו דין גיטין — על כן אינו ראוי להיות שליח בגיטין.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' אלעזר,\u0004 לדרך זו של הסבר: \u0003טעמא\u0004 \u0005[הטעם]\u0006 לפסולו של עבד בשליחות הוא דווקא \u0003במילתא דליתיה\u0004 \u0005[בדבר שאינו\u0006 שייך \u0005בו],\u0006 \u0003הא במילתא דאיתיה\u0004 \u0005[הרי בדבר שישנו בו],\u0006 כלומר, במצוה שעבד שייך בה, \u0003כשר\u0004 להיות בה שליח?","\u0003והא\u0004 \u0005[והרי]\u0006 \u0003גוי, והא\u0004 \u0005[והרי]\u0006 \u0003כותי\u0004 (שומרוני) \u0003דאיתנהו\u0004 \u0005[שישנם]\u0006 \u0003בתורת תרומה דנפשייהו\u0004 \u0005[של עצמם],\u0006 שיכולים הם להרים תרומה משלהם, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הגוי והכותי שתרמו משלהם\u0004 — \u0003תרומתם תרומה, ותנן\u0004 \u0005[ושנינו\u0006 במשנה אחרת\u0005]:\u0006 \u0003גוי שתרם\u0004 מתוך תבואתו \u0003של ישראל, אפילו\u0004 תרם \u0003ברשות\u0004 הישראלי — \u0003אין תרומתו תרומה\u0004 כל עיקר,","\u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004כן תרימו גם \u0003אתם\"\u0004 (במדבר יח, כח), ודורשים את ההדגשה \u0003\"גם אתם\"\u0004 — כמו אתם; \u0003מה אתם ישראל\u0004 — \u0003אף שלוחכם ישראל,\u0004 ואין עבד בכלל ישראל? והוא הדין אם כן לכל שליחות, ובכלל זה שליחות הגט!","\u0003אמרי דבי\u0004 \u0005[אומרים\u0006 חכמים \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי: לא,\u0004 כך יש לדרוש את הכתוב: \u0003מה אתם בני ברית, אף שלוחכם בני ברית,\u0004 ומשום כך הגוי איננו יכול להיות שליח בדבר, שאין הוא בכלל בן ברית, אבל העבד שאדונו מצווה למול אותו, וחייב במקצת מצוות — בכלל בני ברית הוא, ולכן בכלל שליחות הוא.","ומביאים: \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: אין העבד נעשה שליח לקבל גט אשה מיד בעלה, לפי שאינו בתורת גיטין וקידושין, ואף על פי ששנינו:\u0004 האומר לשפחה כנענית \u0003\"הרי את שפחה וולדך בן חורין\", אם היתה עוברה\u0004 (מעוברת) באותה שעה — \u0003זכתה לו\u0004 לעובר את שחרורו.","וקודם מבררים: \u0003מאי\u0004 \u0005[מה]\u0006 ענין \u0003\"אם היתה עוברה זכתה לו\"?\u0004 כלומר, מה הקשר בין דברי ר' יוחנן בענין שליחות העבד בגיטין, לענין שחרור העבד? \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב שמואל בר יהודה, אמר: ר' יוחנן תרתי\u0004 \u0005[שני\u0006 דברים\u0005]\u0006 שונים \u0003אמר;\u0004 האחד, שאין העבד נעשה שליח לקבל גט אשה מיד בעלה. והאחר: \u0003נראים דברים שהעבד מקבל גט,\u0004 שטר שחרור \u0003לחבירו\u0004 העבד \u0003מיד רבו\u0004 (אדוניו) \u0003של חבירו, אבל לא מיד רבו שלו,\u0004 אם היו שניהם עבדים אצל אדון אחד.","\u0003ואם לחשך\u0004 (ילחש לך, יעלה לך קושיה) \u0003אדם לומר:\u0004 הלא \u0003זו\u0004 שאינו יכול לקבל גט עבור חבירו מיד אדונו שלו היא \u0003הלכה שנויה\u0004 להיפך, שכן שנינו: \u0003אם היתה עוברה\u0004 — \u0003זכתה לו,\u0004 ונמצא שהשפחה נעשית כשליח לקבל את שחרור בנה מיד אדוניה! \u0003אמור לו\u0004 כי \u0003שני גדולי הדור\u0004 כבר \u0003פירשו את הדבר,\u0004 והם: \u0003ר' זירא ור' שמואל בר רב יצחק.\u0004","\u0003חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006 — שיטת \u0003רבי היא,\u0004 ש\u0003אמר: המשחרר חצי עבדו\u0004 — \u0003קנה, וחד\u0004 \u0005[ואחד]\u0006 מהם הוסיף ו\u0003אמר: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רבי בהא\u0004 \u0005[בזו]?\u0006 — \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003עובר ירך אמו הוא, ונעשה כמי שהקנה לה אחד מאבריה.\u0004 שכיון שהיתה השפחה מעוברת הרי הוולד נחשב כחלק ממנה, והרי זה כאילו שיחרר חלק מגופה, ושחרור זה חל. ולפי זה יש פה טעם מיוחד שאינו מדין שליחות, אלא משום שהעובר הוא חלק מגופה.","\u0003אף\u0004 אלה \u0003הנשים שאינן נאמנות\u0004 להעיד לאשה ו\u0003לומר \"מת בעלה\",\u0004 משום שחזקה שהן שונאות אותה, ולכן הן חשודות שמא הן משקרות ובאות לקלקלה, שתינשא על פי עדותן ולבסוף תצטרך לצאת מבעלה השני, מכל מקום, אף הן \u0003נאמנות להביא את גיטה,\u0004 ואלו הן: \u0003חמותה, ובת חמותה, וצרתה\u0004 (אשתו האחרת של בעלה), \u0003ויבמתה\u0004 (אשת אחי בעלה), \u0003ובת בעלה.\u0004","ומסבירים: \u0003מה בין גט למיתה,\u0004 ומדוע סומכים עליהן בגט? — שבגט \u0003הכתב מוכיח,\u0004 ומה שמסתמכים על דבריהן הוא רק לסיוע בלבד. וכן \u0003האשה עצמה מביאה את גיטה, ובלבד שהיא צריכה לומר: \"בפני נכתב ובפני נחתם\",\u0004 וכאשר יבואר הדבר בגמרא.","שואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כשם שאין נאמנות\u0004 אלה הנשים \u0003לומר \"מת בעלה\", כך אין נאמנות להביא\u0004 את \u0003גיטה! אמר רב יוסף: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן\u0004 במשנתנו מדובר \u0003בארץ\u0004 (ארץ ישראל), ואילו \u0003כאן\u0004 בברייתא מדובר \u0003בחוצה לארץ.\u0004","ומסביר את ההבדל: \u0003בארץ, דלאו אדיבורה דידה קא סמכינן\u0004 \u0005[שלא על הדיבור שלה אנו סומכים]\u0006 להכשיר את הגט באמירת \"בפני נכתב ובפני נחתם\", ואינה אלא שליחה בלבד — \u0003מהימנא\u0004 \u0005[נאמנת\u0006 היא\u0005]\u0006 להביא את הגט. ואולם \u0003בחוצה לארץ, דאדיבורה דידה קא סמכינן\u0004 \u0005[שעל הדיבור שלה אנו סומכים]\u0006 ולא ניתן לערער עוד על הגט — \u0003לא מהימנא\u0004 \u0005[אינה נאמנת],\u0006 שהרי אנו חושדים בה שאומרת דברי שקר כדי לקלקלה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אדרבה\u0004 \u0005[להיפך],\u0006 \u0003איפכא מסתברא\u0004 \u0005[ההיפך מסתבר],\u0006 ויש לומר: \u0003בארץ, דאי אתי\u0004 \u0005[שאם יבוא]\u0006 ה\u0003בעל מערער\u0004 \u0005[\u0006ו\u0005יערער]\u0006 \u0003משגחינן ביה\u0004 \u0005[משגיחים אנו בו,\u0006 מקבלים אנו את דבריו\u0005]\u0006 וערעורו על הגט מתקבל, שהרי לא אמרה \"בפני נכתב ובפני נחתם\", \u0003דאיכא למימר לקלקולא קא מיכוונה\u0004 \u0005[שיש לומר לקלקול\u0006 של האשה שהיא שונאת היא \u0005מתכוונת],\u0006 שתביא לה גט ולבסוף יתברר שלא היה זה גט כשר, ותצטרך לצאת מהבעל השני שתינשא לו — שם \u0003לא מהימנא\u0004 \u0005[נאמנת].\u0006 ואילו \u0003בחוצה לארץ, דאי אתי\u0004 \u0005[שאם יבוא]\u0006 ה\u0003בעל מערער\u0004 \u0005[\u0006ו\u0005יערער]\u0006 \u0003לא משגחינן ביה\u0004 \u0005[משגיחים אנו בו]\u0006 — \u0003מהימנא\u0004 \u0005[נאמנת\u0006 היא\u0005].\u0006","ומעירים: ואכן, \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003אביי: ר' שמעון בן אלעזר אומר משום\u0004 (משם) \u0003ר' עקיבא: אשה נאמנת להביא גיטה מקל וחומר; ומה נשים שאמרו חכמים\u0004 ש\u0003אין\u0004 הן \u0003נאמנות לומר \"מת בעלה\"\u0004 — \u0003נאמנות\u0004 מכל מקום \u0003להביא\u0004 את \u0003גיטה, היא\u0004 עצמה \u0003שנאמנת לומר \"מת בעלה\"\u0004 — \u0003אינו דין שנאמנת להביא\u0004 את \u0003גיטה?\u0004"],["\u0003וממקום שבאת,\u0004 כלומר, מתוך ראיה זו עצמה אנו למדים: \u0003מה להלן\u0004 השליחות \u0003צריכות שיאמרו: \"בפנינו נכתב ובפנינו נחתם\", אף היא\u0004 עצמה המביאה את גיטה \u0003צריכה שתאמר: \"בפני נכתב ובפני נחתם\".\u0004 ומכאן נלמד לענייננו שמדובר בהבאת גט בחוצה לארץ, שהרי נזכר שאותן נשים עליהן דובר במשנה צריכות לומר \"בפני נכתב\" וכו'.","\u0003אמר רב אשי: מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן מדוייקת\u0006 כך\u0005],\u0006 \u0003דקתני\u0004 \u0005[ששנה\u0006 בה\u0005]:\u0006 \u0003האשה עצמה מביאה\u0004 את \u0003גיטה, ובלבד שתהא צריכה לומר\u0004 \"בפני נכתב ובפני נחתם\", \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שמדובר בשליחות בחוצה לארץ. ושואלים: \u0003ו\u0004לדעת \u0003רב יוסף,\u0004 האם אפשר לומר ש\u0003רישא\u0004 \u0005[ראשה\u0006 של המשנה\u0005]\u0006 הקודמת \"הכל כשרים להביא את הגט\" וכו' \u0003וסיפא\u0004 \u0005[וסופה\u0006 של המשנה\u0005]\u0006 \"האשה עצמה\" וכו' מדברים בהבאת גט \u0003בחוצה לארץ,\u0004 ואילו \u0003מציעתא\u0004 \u0005[אמצעה]\u0006 \"אף הנשים\" וכו' מדברת בהבאתו \u0003בארץ?\u0004 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003רישא וסיפא\u0004 \u0005[ראשה וסופה]\u0006 \u0003בחוצה לארץ, מציעתא\u0004 \u0005[\u0006ו\u0005אמצעה]\u0006 \u0003בארץ.\u0004","","ומסבירים: \u0003ממאי\u0004 \u0005[ממה]\u0006 הוא מוכיח זאת? — \u0003מדקתני\u0004 \u0005[ממה ששנה\u0006 במשנה\u0005]:\u0006 \u0003מה בין גט למיתה\u0004 — \u0003שהכתב מוכיח, ולא קתני\u0004 \u0005[שנה]:\u0006 \u0003שהכתב ופה מוכיח.\u0004 משמע שאין כאן ענין של אמירה (\"בפני נכתב\" וכו'), ולכן הוא מפרש שמדובר כאן בארץ.","שנינו במשנה ש\u0003האשה עצמה מביאה\u0004 את גיטה ואומרת שבפניה נכתב ונחתם. ושואלים: לשם מה היא צריכה להביא ולהעיד? הלא \u0003אשה מכי מטי\u0004 \u0005[מכאשר הגיע]\u0006 \u0003גיטה לידה איגרשה\u0004 \u0005[התגרשה]\u0006 \u0003לה\u0004 כבר! \u0003אמר רב הונא: באומר\u0004 לאשתו: \u0003לא תתגרשי בו אלא בפני בית דין פלוני.\u0004 ואומרים: \u0003סוף סוף כי מטיא התם איגרשה בה\u0004 \u0005[כאשר\u0006 היא \u0005מגיעה לשם\u0006 בפני אותו בית דין, מייד היא \u0005מתגרשת בו],\u0006 שהרי קיימה את התנאי של בעלה! ולשם מה היא צריכה להביא ולהעיד?","\u0003אלא אמר רב הונא בר מנוח משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא:\u0004 ש\u0003אמר לה\u0004 הבעל כך: \u0003כי מטית התם, אתנחיה אארעא ושקליה\u0004 \u0005[כאשר את מגיעה לשם, הניחי אותו,\u0006 את הגט, \u0005על הארץ וקחי אותו],\u0006 שתקבל את הגט רק באותו מקום.","ומקשים: \u0003אי הכי, הוה ליה\u0004 \u0005[אם כן, הרי זה]\u0006 כמו המקרה שאומר לאשתו: \u0003\"טלי גיטך מעל גבי קרקע\", ואמר רבא\u0004 על כך: האומר לאשתו \u0003\"טלי גיטך מעל גבי קרקע\"\u0004 — \u0003לא אמר כלום,\u0004 שנמצא שלא הוא שנתן לה גט אלא היא לקחתו בעצמה!","\u0003אלא,\u0004 צריכים לפרש כך: ש\u0003אמר לה\u0004 לאשתו: \u0003הוי\u0004 \u0005[היי]\u0006 \u0003שליח\u0004 שלי \u0003להולכה\u0004 של הגט \u0003עד דמטית התם\u0004 \u0005[שאת מגיעה לשם],\u0006 \u0003וכי מטית התם\u0004 \u0005[וכאשר את מגיעה לשם],\u0006 למקום שאני אומר לך \u0003הוי\u0004 \u0005[היי]\u0006 \u0003שליח לקבלה, וקבלי את גיטך\u0004 כשליח.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא חזרה שליחות אצל הבעל!\u0004 שהשליחות הראשונה שעשתה בתורת שליח להולכה לא נגמרה, שעל השליח להיות ראוי לחזור למשלח ולהודיע לו על ביצוע השליחות, וזו, כיון שבהגיעה לאותו מקום הריהי נעשית בעל המעשה עצמו ומכאן ואילך בטלה שליחותה, הרי שיש חיסרון בעצם השליחות, ואם כן, כיצד יכולה היא לקבל מיד עצמה את הגט! אלא צריך לומר כך, ש\u0003אמר לה: הוי\u0004 \u0005[היי]\u0006 \u0003שליח להולכה עד דמטית התם\u0004 \u0005[שאת מגיעה לשם],\u0006 \u0003וכי מטית התם\u0004 \u0005[וכאשר את מגיעה לשם]\u0006 \u0003שוי\u0004 \u0005[עשי]\u0006 \u0003שליח לקבלה\u0004 עבורך, ותני לו את הגט. ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]:\u0006 \u0003אשה עושה שליח לקבל גיטה מיד שליח בעלה,\u0004 ואינה צריכה לקבל את הגט בעצמה. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]:\u0006 \u0003אין האשה עושה שליח לקבל גיטה מיד שליח בעלה, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","","ומשיבים: \u0003טעמא מאי\u0004 \u0005[מהו הטעם]\u0006 של מי שאמר שאין האשה עושה שליח? \u0003משום דאיכא\u0004 \u0005[שיש]\u0006 בכך \u0003בזיון\u0004 של ה\u0003בעל,\u0004 שהוא רוצה למסור את הגט ביד האשה ולא ביד שליח, \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003בעל לא קפיד\u0004 \u0005[מקפיד],\u0006 שהרי הוא עצמו אמר לה לעשות כך. על כך שואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]:\u0006 שהטעם בענין זה הוא \u0003משום\u0004 החשש ל\u0003בזיון\u0004 של ה\u0003בעל, אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]:\u0006 שזוהי גזירה \u0003משום חצרה הבאה לאחר מיכן,\u0004 שאם היו מתירים לה למנות שליח לקבלה מיד שליח הבעל, היו סבורים שגם בחצר הדין כן, באופן שנתן את הגט בחצר, ואחר כך קנתה האשה את החצר ועל ידי כך קיבלה את הגט. ובאמת, אין הדברים דומים, כי בחצר אינה זוכה מדין שליחות אלא כאילו היתה זאת ידה, וכשהחצר אינה שלה — אין כאן נתינה לידה, ואין זה גט. אם כן, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 כיצד יכולה היא לעשות שליח לקבלה? ומשיבים: צריכים לפרש כך, ש\u0003אמר לה,\u0004 לאשה: \u0003הוי\u0004 \u0005[היי]\u0006 לגבי הגט \u0003שליח להולכה עד דמטית התם\u0004 \u0005[שאת מגיעה לשם],\u0006 \u0003וכי מטית התם\u0004 \u0005[וכאשר את מגיעה לשם]\u0006 \u0003שוי\u0004 \u0005[עשי]\u0006 \u0003שליח\u0004 נוסף \u0003להולכה, וקבלי את גיטך מיניה\u0004 \u0005[ממנו],\u0006 משליח זה.","","","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור],\u0006 ש\u0003אמר לה\u0004 כך: \u0003הוי\u0004 \u0005[היי]\u0006 \u0003שליח להולכה עד דמטית התם\u0004 \u0005[שאת מגיעה לשם],\u0006 \u0003וכי מטית התם\u0004 \u0005[וכאשר את מגיעה לשם]\u0006 \u0003אימר קמי בי דינא\u0004 \u0005[אמרי בפני בית הדין]\u0006 \u0003\"בפני נכתב ובפני נחתם\", ומשוי בי דינא\u0004 \u0005[ויעשו בית הדין]\u0006 \u0003שליח וליתבוה ניהליך\u0004 \u0005[ויתנו לך]\u0006 את הגט.","","\u0003כל גט שנכתב שלא לשום\u0004 (לשם) \u0003אשה,\u0004 אלא סתם — \u0003פסול. כיצד? היה\u0004 אדם \u0003עובר בשוק, ושמע קול סופרים\u0004 שכותבים גיטין \u0003מקרין\u0004 (מקריאים) לתלמידיהם כתרגיל: \u0003איש פלוני מגרש את פלונית ממקום פלוני,\u0004 ונכנס \u0003ואמר: זה שמי וזה שם אשתי,\u0004 תנו לי את הגט הזה שכתבתם ואשתמש בו — גט כזה \u0003פסול לגרש בו,\u0004 שהרי לא נכתב לשם גירושי אשה.","\u0003יתר מיכן,\u0004 אפילו \u0003כתב\u0004 אדם \u0003לגרש את אשתו ונמלך\u0004 ולא גירשה, ונשאר בידו הגט, \u0003מצאו בן עירו ואמר לו: שמי כשמך ושם אשתי כשם אשתך\u0004 ומקומנו שווה, תן לי את הגט ואשתמש אני בו — \u0003פסול\u0004 השני \u0003לגרש בו.\u0004"],["\u0003יתר מיכן\u0004 — \u0003היו לו שתי נשים ושמותיהן שוות,\u0004 ו\u0003כתב\u0004 גט \u0003לגרש\u0004 אחת מהן, כגון \u0003את הגדולה\u0004 ונמלך — \u0003לא יגרש בו את הקטנה.\u0004","\u0003יתר מיכן,\u0004 אפילו \u0003אמר\u0004 בעל של שתי נשים ששמותיהן שווים \u0003ללבלר: \"כתוב\u0004 גט, \u0003לאיזו\u0004 מהן \u0003שארצה אגרש\"\u0004 — \u0003פסול לגרש בו.\u0004","שנינו במקרה השני במשנה: \u0003כתב לגרש את אשתו ונמלך וכו'.\u0004 ושואלים: \u0003ואלא רישא\u0004 \u0005[בראשה\u0006 של המשנה\u0005]\u0006 שנאמר \"איש פלוני מגרש את פלונית\" וכו' \u0003במאי\u0004 \u0005[במה\u0006 מדובר\u0005],\u0006 האם לא במקרה כזה שציווה פלוני לכתוב גט לאשתו ונמלך ולא גירשה? ואם כן הרי המקרה הראשון במשנה זהה למקרה השני!","\u0003אמר רב פפא: בסופרין העשויין להתלמד עסקינן\u0004 \u0005[עוסקים אנו]\u0006 שכותבים אותו כתרגול בלא שיאמר להם אדם לכתוב גט עבורו. \u0003אמר רב אשי: דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 מלשון המשנה, \u0003דקתני\u0004 \u0005[ששנה\u0006 בה\u0005]\u0006 \u0003\"סופרין מקרין\",\u0004 שמשמעו — מקריאים לתלמידיהם, על מנת להרגיל אותם בכתיבת גיטין, \u0003ולא קתני\u0004 \u0005[שנה]\u0006 \u0003\"סופרין קוראין\".\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך הוא.","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 המשמעות של \u0003\"יתר מיכן\"?\u0004 מה נתווסף בכל מקרה במשנה על קודמו? ומביאים מברייתא: \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: לא\u0004 רק \u0003זה,\u0004 במקרה הראשון שכתבו סופרים גט, \u0003שנכתב שלא לשום\u0004 (לשם) \u0003גירושין\u0004 כלל, אלא כתרגיל כתיבה — פסול, \u0003אלא אף זה\u0004 שכתב אדם לגרש את אשתו ונמלך, \u0003שנכתב\u0004 מתחילתו \u0003לשום גירושין\u0004 — \u0003פסול\u0004 ואין חבירו יכול לגרש בו.","\u0003ולא\u0004 רק \u0003זה שנכתב שלא לשום גירושין דידיה\u0004 \u0005[שלו]\u0006 אלא של איש אחר — פסול, \u0003אלא אף זה\u0004 שכתבו על מנת לגרש את אשתו האחת \u0003שנכתב לשום גירושין דידיה\u0004 \u0005[שלו]\u0006 — \u0003פסול\u0004 לגרש בו את אשתו האחרת שלא לשמה נכתב. \u0003ולא\u0004 רק \u0003זה\u0004 שכתבו לאשתו האחת, \u0003שלא נכתב לשום גירושין הא\u0004 \u0005[\u0006של \u0005זו],\u0006 אשתו האחרת — פסול, \u0003אלא אף זה\u0004 שהתנה שכותב לאחת משתי נשיו כפי שירצה, \u0003ש\u0004מכל מקום \u0003נכתב לשום\u0004 (לשם) \u0003גירושין הא\u0004 \u0005[\u0006של \u0005זו],\u0006 שהרי חשב גם עליה — גם כן \u0003פסול.\u0004","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? מניין לנו שיש צורך בדיוק גדול כל כך של \"לשמה\"? — שנאמר בפרשת גירושין שבתורה (דברים כד, א): \"וכתב לה ספר כריתות ונתן בידה\". וכך אנו למדים: \u0003אי כתב\u0004 \u0005[אילו היה כתוב]\u0006 בתורה רק \u0003\"ונתן ספר כריתות בידה\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שדבר זה בא \u0003למעוטי האיך קמא\u0004 \u0005[למעט\u0006 ולפסול רק את \u0005זה,\u0006 המקרה \u0005הראשון]\u0006 שכתבו סופרים להתלמד, \u0003דלא עביד לשום\u0004 \u0005[שאין\u0006 הגט \u0005עשוי לשם]\u0006 \u0003כריתות, אבל כתב\u0004 אדם אחר \u0003לגרש את אשתו ונמלך, דעביד\u0004 \u0005[שעשוי]\u0006 \u0003לשום כריתות\u0004 — \u0003אימא\u0004 \u0005[אמור]\u0006 שהוא גט \u0003כשר,\u0004 על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]:\u0006 \u0003\"וכתב\"\u0004 שצריך לכתוב בעצמו, לשם גירושיו שלו, ולא שייכתב על ידי אדם אחר.","\u0003אי כתב רחמנא\u0004 \u0005[\u0006ו\u0005אילו היתה כותבת התורה]\u0006 רק \u0003\"וכתב\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 דבר זה בא \u0003למעוטי האי דלא איהו קא כתיב לה\u0004 \u0005[למעט\u0006 את \u0005זה שלא הוא כתב אותו],\u0006 \u0003אבל\u0004 מי ש\u0003יש לו שתי נשים\u0004 ששמותיהן שווים, \u0003דאיהו קא כתיב לה\u0004 \u0005[שהוא\u0006 עצמו \u0005כותב אותו\u0006 לעצמו\u0005]\u0006 — \u0003אימא\u0004 \u0005[אמור]\u0006 שהוא גט \u0003כשר\u0004 — \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]:\u0006 \u0003\"\u0004וכתב \u0003לה\",\u0004 וכוונתו \u0003לשמה\u0004 של אותה אשה דווקא.","ושואלים: \u0003וסיפא\u0004 \u0005[וסופה\u0006 של המשנה\u0005]\u0006 במי שרוצה לתת גט לאחת מנשותיו על תנאי, \u0003למה לי?\u0004 והרי כבר ידוע לנו שיש צורך לכתוב את הגט לשם האשה המתגרשת! ואומרים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו],\u0006 ש\u0003אין ברירה,\u0004 ואין אומרים שכיון שנתן לזו — התברר הדבר למפרע שלה התכוון מתחילה, אלא צריך לכתוב לשמה כבר מתחילת הכתיבה.","שנינו במשנה: \u0003כתב לגרש את הגדולה\u0004 — \u0003לא יגרש בו את הקטנה\u0004 למרות ששמותיהן שווים. ומדייקים מכאן: \u0003קטנה הוא דלא מצי מגרש ביה\u0004 \u0005[שאינו יכול לגרש בו],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003גדולה\u0004 שכתב בשבילה — \u0003מצי מגרש ביה\u0004 \u0005[יכול לגרש בו],\u0006 למרות שהפרטים שבגט זהים לחלוטין לאשה אחרת המצוייה באותו מקום, ואשה יכולה לגבות את כתובתה ולהינשא לאיש אחר על סמך גט זה.","\u0003אמר רבא: זאת אומרת,\u0004 ש\u0003שני\u0004 אנשים ששמותיהם זהים, כגון ששניהם נקראים \u0003יוסף בן שמעון הדרין בעיר אחת\u0004 למרות ששמותיהם שווים בדיוק — \u0003מוציאין\u0004 (מציגים לפרעון) \u0003שטר\u0004 \u0003חוב על אחרים,\u0004 ואין הלווה יכול לומר ליוסף בן שמעון שהוא בעל השטר שהשטר נכתב עבור יוסף בן שמעון האחר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה,\u0004 לפי אופן זה שאתה מדייק, \u0003רישא דקתני\u0004 \u0005[\u0006ב\u0005ראשה\u0006 של משנתנו \u0005ששנה\u0006 בה\u0005]\u0006 שפוגש את חבירו ואומר לו: \u0003שמי כשמך\u0004 — \u0003פסול לגרש בו,\u0004 אף כאן נדייק: \u0003שני הוא\u0004 ש\u0003לא מצי מגרש ביה\u0004 \u0005[יכול לגרש בו],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 ה\u0003ראשון מצי מגרש ביה\u0004 \u0005[יכול לגרש בו]\u0006 למרות ששמותיהם שווים? \u0003והא אמרינן\u0004 \u0005[והרי אנו אומרים]\u0006 במשנה במפורש במקרה ששני אנשים ששמותיהם שווים: \u0003ולא אחר יכול להוציא עליהן שטר חוב,\u0004 משום שכל אחד מהם יכול להשתמט ולומר שלא הוא החייב, ולא לשמו נכתב השטר! ואף כאן יש לחשוש שאשה שיש בידה גט כזה משתמשת לתביעת כתובתה ולנישואיה בגט שאינו שלה.","\u0003אלא מאי אית לך למימר\u0004 \u0005[מה יש לך לומר],\u0006 כיצד יכול הראשון בכל זאת לגרש בו ונוכל לסמוך על גט זה כראיה? — שמסר את הגט \u0003בעדי מסירה\u0004 ועליהם אנו סומכים לאשר את הגט בבית הדין, \u0003ו\u0004דעת \u0003ר' אלעזר היא,\u0004 שסבור שעיקרו של הגט הוא במסירתו בפני עדים.","אם כן, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בשתי נשים בעלות אותו שם, אפשר לפרש שמדובר כשנמסר הגט לאשה ב\u0003עדי מסירה,\u0004 ואין לדייק מכאן, כפי שדייק רבא, שיכולים שני יוסף בן שמעון הדרים בעיר אחת להוציא שטר חוב על אחרים, \u0003ו\u0004שיטת \u0003ר' אלעזר היא.\u0004","\u0003אמר רב:\u0004 כל הגיטין הללו \u0003כולן\u0004 שנמנו במשנה ואמרו שהם פסולים ואינם כשרים לגרש בהם אשה — בכל זאת \u0003פוסלין בכהונה.\u0004 שאם ניתנו לאשה — הרי היא נפסלת על ידי כך להינשא לכהן משום דין גרושה, \u0003חוץ מן\u0004 הגט \u0003הראשון\u0004 שעסקה בו המשנה, שלא נכתב כלל לשם גירושין אלא להתלמד. \u0003ושמואל אמר: אף ראשון נמי\u0004 \u0005[גם כן]\u0006 \u0003פוסל.\u0004","ומעירים: \u0003ואזדא\u0004 \u0005[והלך]\u0006 \u0003שמואל לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר שמואל: כל מקום ששנו חכמים \"גט פסול\"\u0004 — כוונתו: \u0003פסול\u0004 שאין האשה יכול להינשא מכוחו, \u0003ו\u0004אולם \u0003פוסל\u0004 אותה מכהונה. ובכל מקום שאמרו \u0003\"חליצה פסולה\"\u0004 — הכוונה היא ש\u0003פסולה,\u0004 שאין היבמה יכולה עדיין להינשא לאדם אחר, כדין יבמה הזקוקה לייבום. \u0003ו\u0004אולם \u0003פוסלתה מן האחין,\u0004 שגם האחים האחרים אינם יכולים עוד לייבם אותה, כדין יבמה שחלץ לה אחד מן האחים.","\u0003במערבא אמרי משמיה\u0004 \u0005[בארץ ישראל אמרו משמו]\u0006 של \u0003ר' אלעזר:\u0004 מי שחלץ ברגל \u0003שמאל\u0004 או שחלץ ב\u0003לילה\u0004 — הרי אלו חליצות \u0003פסולות,\u0004 \u0003ו\u0004בכל זאת \u0003פוסלות\u0004 את היבמה לאחים,"],["אבל אם היה החולץ \u0003קטן,\u0004 או שחלץ לא בסנדל כי אם ב\u0003אנפיליא\u0004 (גרב של בד) — הרי אלו חליצות \u0003פסולות\u0004 לגמרי, \u0003ו\u0004לא רק שאינן מתירות אותה להינשא, אלא גם \u0003אין פוסלות\u0004 אותה מן האחים.","שיטה נוספת על אלה של רב ושמואל בענין הפוסלים לכהונה, היא של \u0003זעירי\u0004 ש\u0003אמר:\u0004 כל המקרים הללו \u0003כולן,\u0004 כל המקרים שנשנו במשנה \u0003אין פוסלין\u0004 את האשה מכהונה \u0003חוץ מן\u0004 המקרה \u0003האחרון,\u0004 ששמות נשיו שווים, והורה לסופר לכתוב גט סתם והשאיר בידו את הברירה למי מהן יתן את הגט.","\u0003וכן אמר רב אסי: כולן אין פוסלין חוץ מן האחרון.\u0004 \u0003ו\u0004אילו \u0003ר' יוחנן אמר\u0004 שיטה אחרת בענין זה: \u0003אף אחרון נמי\u0004 \u0005[גם כן]\u0006 \u0003אינו פוסל\u0004 לכהונה, שאין אנו חוששים כלל לדעה שיש ברירה לומר שהוברר בנתינת הגט שלשמה של אותה אשה נכתב.","ומעירים: \u0003ואזדא\u0004 \u0005[והולך]\u0006 \u0003ר' יוחנן לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005].\u0006 ש\u0003אמר ר' אסי אמר ר' יוחנן: האחין שחלקו\u0004 את ירושת אביהם \u0003לקוחות הן\u0004 מבחינת ההלכה, ונחשבים כאילו קנו זה מזה, \u0003ו\u0004לכן \u0003מחזירין זה לזה ביובל\u0004 כדין כל מי שקנה שדה מחבירו, וחולקים מחדש. ואין אנו אומרים יש ברירה — שבחלוקה הראשונה הוברר חלקו המיוחד של כל אחד מן האחים, והרי הוא שלו לצמיתות.","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שייאמרו דברי ר' יוחנן שאין ברירה גם בענין ירושה וגם בענין הגט. \u0003דאי איתמר בהא\u0004 \u0005[שאם היה נאמר\u0006 רק \u0005בזה],\u0006 בגט, היינו אומרים: דווקא \u0003בהא קאמר\u0004 \u0005[בזה אומר]\u0006 \u0003ר' יוחנן\u0004 ש\u0003אין ברירה, משום דבעינן\u0004 \u0005[שאנו צריכים]\u0006 שיהא הגט כתוב מתחילתו \u0003\"לה\",\u0004 כלומר \u0003לשמה, אבל התם\u0004 \u0005[שם]\u0006 לענין ירושה, יכולים היינו לומר: דווקא \u0003מכר הוא דאמר רחמנא\u0004 \u0005[שאמרה תורה]\u0006 \u0003ליהדר\u0004 \u0005[שיחזור]\u0006 \u0003ביובל, אבל ירושה ומתנה לא\u0004 יחזרו ביובל, לכן השמיע לנו שאין הדבר כן והאחים לקוחות הם, ואין ברירה.","\u0003ו\u0004לצד האחר: \u0003אי אשמעינן\u0004 \u0005[אם היה משמיע לנו]\u0006 רק ב\u0003שדה,\u0004 היינו אומרים שפסק כך \u0003משום דלחומרא\u0004 \u0005[שלהחמיר],\u0006 ושמא אין דעתו של ר' יוחנן מוחלטת בענין זה, אלא שמפני הספק הוא מחמיר להחזיר את הקרקעות זה לזה. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 לא פסק כך משום שאין ברירה, אלא מפני שביובל אנו מדברים על החזרת מצב הדברים \u0003כתחילה,\u0004 כמו שהיו הנחלות בזמן החלוקה לשבטים. \u0003אבל הכא\u0004 \u0005[כאן],\u0006 בגט, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 לכן, \u0003צריכא\u0004 \u0005[נצרכה]\u0006 שיאמר הדבר גם בגט, לומר שר' יוחנן סבור ככלל שאין ברירה.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב הושעיא מרב יהודה: אמר\u0004 הבעל \u0003ללבלר \"כתוב\u0004 גט \u0003לאיזו\u0004 מנשי \u0003שתצא בפתח תחילה\", מהו?\u0004 האם גט כשר הוא? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תניתוה\u0004 \u0005[\u0006כבר \u0005שניתם אותה\u0006 במשנה\u0005]:\u0006 \u0003יתר מיכן, אמר ללבלר \"כתוב לאיזו שארצה אגרש\"\u0004 — \u0003פסול לגרש בו, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003אין ברירה!\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 רב הושעיא ממה ששנינו, \u0003האומר לבניו: \"הריני שוחט את הפסח\u0004 בירושלים \u0003על מי שיעלה מכם ראשון לירושלים\", כיון שנכנס ראשון ראשו ורובו\u0004 לעיר — \u0003זכה בחלקו\u0004 על ידי אביו, \u0003ומזכה את אחיו עמו.\u0004 ומכאן שאומרים יש ברירה, שהרי כאן מתברר למפרע שעליו שחט האב את הפסח!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה: \u0003הושעיא ברי\u0004 \u0005[בני],\u0006 \u0003מה ענין פסחים אצל גיטין?\u0004 אין הדברים דומים! \u0003הא אתמר עלה\u0004 \u0005[הרי נאמר עליה],\u0006 על משנה זו שבפסחים, \u0003אמר ר' יוחנן:\u0004 אין כוונת האב שבאמת רק הראשון מבניו הוא שיזכה, ולא אמר זאת האב אלא רק \u0003כדי לזרזן במצות\u0004 ובאמת זיכה את הפסח לכולם.","מעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק\u0006 כך \u0005גם כן]\u0006 מלשון המשנה, \u0003דקתני\u0004 \u0005[ששנה]:\u0006 \u0003כיון שנכנס ראשון ראשו ורובו\u0004 — \u0003זכה בחלקו ומזכה את אחיו עמו;\u0004 \u0003אי אמרת בשלמא דאמנינהו מעיקרא\u0004 \u0005[נניח אם אומר אתה ש\u0006כבר \u0005מינה אותם\u0006 האב על הפסח \u0005מתחילה]\u0006 — \u0003שפיר\u0004 \u0005[יפה],\u0006 שכולם היו מנויים ולכן זכו כולם, \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003לא אמנינהו\u0004 \u0005[מינה אותם]\u0006 מתחילה בזמן שחיטת הפסח, \u0003לאחר שחיטה מי קמיתמנו\u0004 \u0005[האם\u0006 אפשר עוד \u0005להתמנות]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003נמנין\u0004 על הפסח בתוך חבורה מסויימת, \u0003ומושכין ידיהן\u0004 (מבטלים) \u0003ממנו,\u0004 ממה שנמנו על חבורה זו, \u0003עד שישחט\u0004 קרבן הפסח, ואולם לאחר שנשחט הקרבן אי אפשר עוד להיכנס לחבורה ולא לצאת ממנה! אלא ודאי שהמנה האב מלכתחילה את כל בניו, ולא אמר כן אלא כדי לזרזם.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 לחזק את דברי ר' יוחנן שאין מדובר כאן אלא בזירוז: ש\u0003מעשה\u0004 היה שאמר אב לבניו דבר כגון זה, \u0003וקדמו בנות לבנים, ונמצאו בנות זריזות ובנים שפלים\u0004 (עצלים). וכיון שלא נאמר שרק הבנות הן שזכו בפסח, אלא רק שהן נמצאו זריזות — משמע שכל זה לא היה ענין של זכייה ממשית אלא של זירוז בלבד.","על משא ומתן זה שבין רב יהודה ורב הושעיא \u0003אמר אביי\u0004 בתמיהה: רב הושעיא \u0003קא בעי מיניה\u0004 \u0005[שואל אותו],\u0006 את רב יהודה שאלה העוסקת במקרה של אדם ש\u0003תולה\u0004 את הברירה \u0003בדעת אחרים,\u0004 במי שתצא ראשונה מהפתח, \u0003ו\u0004אילו רב יהודה \u0003קא פשיט ליה\u0004 \u0005[פותר לו]\u0006 ממקרה שיש בו ברירה באופן של \u0003תולה בדעת עצמו,\u0004 למי שהוא ירצה לתת לה את הגט, \u0003והדר מותיב ליה\u0004 \u0005[ו\u0006אחר כך \u0005חוזר\u0006 רב הושעיא \u0005ומקשה לו]\u0006 ממקרה של \u0003תולה בדעת אחרים,\u0004 במי שיעלה ראשון לירושלים? ומה ההגיון שבדבר?","\u0003אמר רבא: מאי קושיא\u0004 \u0005[מה הקושי\u0006 שבזה\u0005]?\u0006 \u0003דלמא דמאן דאית ליה\u0004 \u0005[שמא שמי שיש לו,\u0006 שסבור\u0005]\u0006 שיש \u0003ברירה\u0004 בכל האופנים: \u0003לא שנא\u0004 \u0005[שונה]\u0006 \u0003תולה בדעת עצמו ולא שנא\u0004 \u0005[שונה]\u0006 \u0003תולה בדעת אחרים\u0004 — תמיד \u0003אית ליה\u0004 \u0005[יש לו,\u0006 הריהו מקבל\u0005]\u0006 את העיקרון של \u0003ברירה, ומאן דלית ליה\u0004 \u0005[ומי שאין לו,\u0006 אינו מקבל\u0005]\u0006 את העיקרון של \u0003ברירה\u0004 גם הוא \u0003לא שנא\u0004 \u0005[שונה]\u0006 \u0003תולה בדעת עצמו ולא שנא\u0004 \u0005[שונה]\u0006 \u0003תולה בדעת אחרים\u0004 — בכל אופן \u0003לית ליה\u0004 \u0005[אין לו,\u0006 אינו \u0005מקבל\u0006\u0005]\u0006 את העיקרון של \u0003ברירה!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב משרשיא לרבא:\u0004 אי אפשר לומר כך, \u0003והא\u0004 \u0005[והרי]\u0006 התנא \u0003ר' יהודה,\u0004 במקרה ש\u0003תולה בדעת עצמו לית ליה\u0004 \u0005[אין לו]\u0006 \u0003ברירה, ו\u0004כש\u0003תולה בדעת אחרים אית ליה\u0004 \u0005[יש לו]\u0006 \u0003ברירה!\u0004","ומפרשים את הדבר: \u0003תולה בדעת עצמו לית ליה\u0004 \u0005[אין לו]\u0006 \u0003ברירה, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הלוקח\u0004 (קונה) \u0003יין מבין הכותים\u0004 (שומרונים) ולשיטה זו הריהם כיהודים לענין חיובי תרומות ומעשרות, אלא שיש לחשוש שלא עישרו ונמצא שיש בידו יין של טבל, \u0003אומר\u0004 כך: \u0003שני לוגין שאני עתיד להפריש\u0004 לאחר זמן ממאה לוגים שיש לפני — \u0003הרי הן\u0004 מעכשיו \u0003תרומה\u0004 לכהן, \u0003עשרה\u0004 לוגים הן \u0003מעשר ראשון\u0004 ללוי, \u0003תשעה\u0004 (עשירית מן הנותר) הם \u0003מעשר שני\u0004 שהמפריש מעלהו לירושלים ואוכלו,"],["\u0003ומיחל\u0004 (מחלל) את המעשר שני על כסף \u0003ו\u0004אם רוצה \u0003שותה מיד,\u0004 וסומך על מה שיפריש לאחר מכן, שאז יתבררו הלוגים שהופרשו למעשר ולתרומה, אלו \u0003דברי ר' מאיר.\u0004 ואילו \u0003ר' יהודה ור' יוסי ור' שמעון אוסרין,\u0004 מפני שהם סבורים שאין ברירה. משמע שלדעת ר' יהודה במקרה שהדבר תלוי בדעתו, אין ברירה.","ומצד שני: במקרה של \u0003תולה בדעת אחרים אית ליה\u0004 \u0005[יש לו,\u0006 לר' יהודה, הריהו מקבל\u0005]\u0006 את העיקרון של \u0003ברירה, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 חולה שאמר לאשתו \"הרי זה גיטך מעכשיו אם אמות מחולי זה\", אם ימות — יחול הגט מאותה שעה שאמר, והשאלה היתה: \u0003מה היא\u0004 (מה דינה) \u0003באותן\u0004 \u0003הימים\u0004 של מחלתו?","— \u0003ר' יהודה אומר: הרי היא כאשת איש לכל דבריה,\u0004 לכל דיניה, \u0003ולכי מיית הוי גיטא\u0004 \u0005[וכאשר ימות יהא\u0006 זה \u0005גט].\u0006 והתולה דבר במיתתו, הריהו כתולה בדעת אחרים, וסבור ר' יהודה שכאשר מתברר הדבר הוא חל למפרע.","ועוד, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב משרשיא לרבא: הא\u0004 \u0005[הרי]\u0006 \u0003ר' שמעון\u0004 גם כן מבדיל בין תולה בדעת עצמו לתולה בדעת אחרים, שבמקרה של \u0003תולה בדעת עצמו לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 את העיקרון של \u0003ברירה, ותולה בדעת אחרים אית ליה\u0004 \u0005[יש לו]\u0006 \u0003ברירה!\u0004","ומבארים: \u0003תולה בדעת עצמו לית ליה\u0004 \u0005[אין לו]\u0006 \u0003ברירה\u0004 — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו]\u0006 בענין היין שקונה מן הכותים (שומרונים). \u0003תולה בדעת אחרים אית ליה\u0004 \u0005[יש לו]\u0006 \u0003ברירה, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 האומר לאשה \u0003\"הריני בועליך\u0004 לשם קידושין \u0003על מנת שירצה אבא\u0004 (אבי) בקידושין אלה \u0003\", אף על פי שלא רצה האב\u0004 — \u0003מקודשת,\u0004 שיש הנחה הלכתית שאין אדם עושה בעילתו בעילת זנות, ולכן אנו אומרים שגם אם לא ירצה האב, מתחילה היתה הבעילה לשם קידושין. \u0003ר' שמעון בן יהודה אומר משום\u0004 (משם) \u0003ר' שמעון:\u0004 אין הדבר כן, אלא רק אם \u0003רצה האב\u0004 — האשה \u0003מקודשת,\u0004"]]};
